pub struct ProcessExit {
    pub status: ExitStatus,
    pub group: bool,
}

pub fn conventional_exit_code(status: ExitStatus) -> i32 {
    status
        .code()
        .unwrap_or_else(|| 128 + status.signal().expect("signaled status has a signal"))
}

fn guest_host_address<M: GuestMemoryAccess<Error = crate::Error>>(
    memory: &M,
    guest_address: u64,
    length: usize,
) -> Result<M::Lent, i64> {
    memory
        .lend(guest_address, length)
        .map_err(|_| negative_errno(libc::EFAULT))
}

/// A `reverie_kvm::SyscallExecutor` that supplies the static-ELF guest-kernel semantics
/// (`execute_basic_syscall`) to the tool-driven run loop
/// (`reverie_kvm::KvmBackend::run_static_elf_with_tool`).
///
/// `execute` returns the raw syscall result and records, as side effects for
/// the run loop to apply after the tool handler completes, any pending FS/GS
/// base update (from `arch_prctl`) and the exit code (from `exit`/`exit_group`).
/// This lets a Reverie tool's `tail_inject` drive the same guest-kernel that
/// `reverie_kvm::KvmBackend::run_static_elf` uses directly.
pub struct ElfExecutor {
    pub state: LoadedStaticElf,
    task_generation: u64,
    process_generation: u64,
    pub signal_registry: Arc<ProcessSignalRegistry>,
    signal_binding: Arc<ProcessBinding>,
    // Retained view only; allocation/policy authority lives in its one owner.
    address_space: Option<GuestMemory>,
    file_table: Arc<std::sync::Mutex<FileTableState>>,
    // Only actual task executors own this token. Table observers may hold a
    // strong file_table Arc, but cannot defer last-task descriptor retirement.
    // A released executor takes its token exactly once; CLONE_FILES shares it.
    file_table_task_owner: Option<Arc<()>>,
    output: Option<CapturedOutput>,
    owns_output: bool,
    // Run-wide and never wrapped (see `allocate_task_id`), so a numeric PID
    // or TID is never reissued within a run. Task records keyed by number
    // alone, such as the lifecycle table and the scheduler's exited-process
    // bookkeeping, therefore cannot confuse two tasks.
    next_pid: Arc<AtomicI32>,
    sigchld_auto_reap: Arc<AtomicBool>,
    // TODO-HUMAN-REVIEW(PR-235): Review concurrent KVM process lifecycle ownership.
    pending_processes: std::collections::BTreeMap<i32, PendingProcess>,
    completed_processes: Vec<ChildProcessHandle>,
    // Failed host spawns still own constructed child Tool state. Retain its
    // consuming cleanup without polling inside the parent's borrowed callback.
    // Mutex makes the executor Sync while each owned future only needs Send.
    unstarted_tool_cleanup: Mutex<Vec<UnstartedToolCleanup>>,
    // Exiting workers transfer forks to their process owner before returning.
    transferred_processes: Arc<Mutex<std::collections::BTreeMap<i32, Vec<OwnedChildProcesses>>>>,
    // Run-wide. A process whose exit reparented its children to an outside
    // namespace init no longer owns their host completion; it moves them here
    // and the traced root, which outlives every process it transitively joins,
    // joins them. Keyed by PID, which is never reissued within a run.
    namespace_orphanage: Arc<Mutex<std::collections::BTreeMap<i32, PendingProcess>>>,
    process_action: Option<ProcessAction>,
    pending_segment: Option<(SegmentBase, u64)>,
    current_user_stack_pointer: Option<u64>,
    exit_status: Option<ExitStatus>,
    exit_group: bool,
    clear_child_tid: Option<u64>,
    signal_callback_nonce: u64,
    parent_death_exec: Mutex<Option<ParentDeathExecSnapshot>>,
    terminal_factory: Option<crate::terminal_cleanup::CleanupFactory>,
    terminal_cleanup: Option<crate::terminal_cleanup::TaskCleanup>,
    terminal_backend_stdin: Option<Arc<Mutex<Option<std::fs::File>>>>,
    parked_signals: Option<ParkedSignalState>,
    completed_signal_effects: Vec<reverie::SignalDequeue>,
    signal_effect_raw_result: Option<i64>,
    // The typed refusal of the last exec this executor declined because it
    // cannot perform the operation. The injecting runtime takes it after each
    // execution, so a stale refusal never describes a later syscall.
    unsupported_refusal: Option<reverie::UnsupportedRefusal>,
}

/// `AllocationCursors` is the machine crate's type; LinuxEmu builds it from a
/// task's state.
trait AllocationCursorsFromElf {
    fn from_elf(state: &LoadedStaticElf) -> Self;
}

impl AllocationCursorsFromElf for AllocationCursors {
    fn from_elf(state: &LoadedStaticElf) -> Self {
        Self {
            program_break: state.program_break,
            mmap_base: state.mmap_base,
            mmap_next: state.mmap_next,
            mmap_limit: state.mmap_limit,
        }
    }
}

/// Whether `[address, address + length)` is one contiguous range of user
/// addresses (mapped or not), including the stack window at the top of the
/// user address space.
fn range_is_valid<M: AddressSpace>(memory: &M, address: u64, length: u64) -> bool {
    memory.is_addressable(address, length)
}

fn align_up(value: u64, alignment: u64) -> Option<u64> {
    value
        .checked_add(alignment - 1)
        .map(|value| value & !(alignment - 1))
}

fn continue_with(result: i64) -> SyscallAction {
    SyscallAction::Continue {
        result,
        segment: None,
    }
}

fn io_error(error: std::io::Error) -> i64 {
    negative_errno(error.raw_os_error().unwrap_or(libc::EIO))
}

const fn negative_errno(errno: libc::c_int) -> i64 {
    -(errno as i64)
}

