    fn getdents64_alias_ledger(
        fault: &crate::alias_failure::Fault,
    ) -> Vec<crate::memory::RetainedWriteAliasSnapshot> {
        use crate::alias_failure::Case;
        let snapshots = crate::memory::retained_write_aliases_for_test();
        let case = fault.case();
        if matches!(case, Case::Reservation | Case::AtomicCollision) {
            assert!(snapshots.is_empty(), "{case:?}: {snapshots:?}");
            return snapshots;
        }
        assert_eq!(snapshots.len(), 1, "{case:?}: {snapshots:?}");
        let record = &snapshots[0];
        let addresses = fault.addresses();
        let page = PAGE_SIZE as usize;
        assert_ne!(record.retention_id, 0);
        assert_ne!(addresses.base, 0);
        assert_eq!(addresses.length, fault.pages() * page);
        let cleanup = match case {
            Case::CleanupAfterSuccess | Case::CleanupAtEof => {
                Some((0, addresses.base, addresses.length))
            }
            Case::ConstructionCleanup => Some((0, addresses.base, 2 * page)),
            Case::SuffixCleanup => Some((1, addresses.base + 3 * page, 2 * page)),
            Case::PersistentCleanup => {
                panic!("three independent persistent cases belong in memory tests")
            }
            _ => None,
        };
        let ambiguous = matches!(
            case,
            Case::SecondExtent
                | Case::Foreign
                | Case::WrongAddress
                | Case::MiddleExtent
                | Case::ConstructionCleanup
                | Case::SuffixCleanup
        );
        assert_eq!(
            addresses.ambiguous,
            if ambiguous {
                addresses.base + 2 * page
            } else {
                0
            }
        );
        let mut owned_ranges = [None; 3];
        let mut cleanup_errors = [None; 3];
        if let Some((slot, address, length)) = cleanup {
            owned_ranges[slot] = Some((address, length));
            cleanup_errors[slot] = Some((address, length, libc::ENOMEM));
        }
        let expected = crate::memory::RetainedWriteAliasSnapshot {
            retention_id: record.retention_id,
            address: addresses.base,
            length: addresses.length,
            ambiguous: ambiguous.then_some((addresses.base + 2 * page, page)),
            unexpected: (case == Case::WrongAddress).then_some((addresses.wrong, page)),
            unexpected_bounds_valid: case == Case::WrongAddress,
            owned_ranges,
            cleanup_errors,
            backing_count: if case == Case::CleanupAtEof {
                0
            } else {
                fault.pages().div_ceil(2)
            },
        };
        assert_eq!(
            record, &expected,
            "complete retained ownership for {case:?}"
        );
        if case == Case::WrongAddress {
            assert_ne!(addresses.wrong, 0);
            assert!(
                addresses.wrong + page <= addresses.base
                    || addresses.wrong >= addresses.base + addresses.length
            );
        } else {
            assert_eq!(addresses.wrong, 0);
        }
        snapshots
    }

    fn getdents64_alias_exact_cause<'a>(
        fault: &crate::alias_failure::Fault,
        snapshots: &[crate::memory::RetainedWriteAliasSnapshot],
        error: &'a crate::Error,
    ) -> &'a crate::Error {
        let cause = if let Some(record) = snapshots.first() {
            fault.cause(error, Some(record.retention_id))
        } else {
            fault.cause(error, None)
        };
        cause.unwrap_or_else(|| panic!("{:?}: {error:?}", fault.case()))
    }

    // Called only after the preselected case oracle has validated the complete
    // error. Preserve context tags while comparing every distinct leaf owner;
    // this is not a context-erasing replacement for that strict classifier.
    fn getdents64_alias_cause_owners(
        error: &crate::Error,
    ) -> Vec<(Option<&'static str>, *const crate::Error)> {
        fn visit(
            error: &crate::Error,
            phase: Option<&'static str>,
            owners: &mut Vec<(Option<&'static str>, *const crate::Error)>,
        ) {
            match error {
                crate::Error::MemoryMapping(_) | crate::Error::WriteAliasCleanup { .. } => {
                    let owner = (phase, std::ptr::from_ref(error));
                    if !owners.contains(&owner) {
                        owners.push(owner);
                    }
                }
                crate::Error::SharedFailure(error) => visit(error, phase, owners),
                crate::Error::WithCleanup { primary, cleanup } => {
                    visit(primary, phase, owners);
                    for error in cleanup {
                        visit(error, phase, owners);
                    }
                }
                crate::Error::Cleanup {
                    phase: observed,
                    error,
                } => {
                    assert!(phase.is_none(), "nested ambiguity context: {error:?}");
                    assert_eq!(*observed, crate::alias_failure::AMBIGUOUS_PHASE);
                    visit(error, Some(*observed), owners);
                }
                _ => panic!("unexpected alias cause or context: {error:?}"),
            }
        }
        let mut owners = Vec::new();
        visit(error, None, &mut owners);
        owners
    }

    fn getdents64_alias_lifecycle_case(fault: crate::alias_failure::Fault) {
        use crate::alias_failure::Case;
        let case = fault.case();
        assert_ne!(case, Case::PersistentCleanup);
        assert!(crate::memory::retained_write_aliases_for_test().is_empty());
        let root = TestDir::new();
        std::fs::write(root.0.join("entry"), b"directory control").unwrap();
        let mut state = test_state(&root.0);
        let mut directory = std::fs::File::open(&root.0).unwrap();
        let mut duplicate = directory.try_clone().unwrap();
        state.files.insert(0, directory.try_clone().unwrap());
        state.files.insert(1, duplicate.try_clone().unwrap());
        let length = fault.pages() * PAGE_SIZE as usize;
        let sentinel = vec![0xa5; length];
        let memory = GuestMemory::new(0, length).unwrap();
        memory.write_raw(0, &sentinel).unwrap();
        if case != Case::CleanupAtEof {
            for page in (0..fault.pages()).step_by(2) {
                memory
                    .map_user_range(page as u64 * PAGE_SIZE, PAGE_SIZE, false)
                    .unwrap();
            }
        }
        memory.enable_user_access();
        // This observer has an independent gate over the same initial backing.
        // It cannot turn poisoned ordinary guest access into successful access.
        let observer = memory.test_alias_backing_observer();
        let memory_owners = memory.test_mapping_owners();
        let observer_owners = observer.test_mapping_owners();
        assert_eq!(memory_owners(), 1);
        assert_eq!(observer_owners(), 1);

        // Independent native file description, no executor helper or alias.
        // The exact same unchanged directory supplies bytes and opaque cookies.
        let mut native = std::fs::File::open(&root.0).unwrap();
        let mut expected_bytes = sentinel.clone();
        let read_native = |file: &std::fs::File, bytes: &mut [u8]| {
            let result = unsafe {
                libc::syscall(
                    libc::SYS_getdents64,
                    file.as_raw_fd(),
                    bytes.as_mut_ptr(),
                    bytes.len(),
                )
            };
            assert!(
                result >= 0,
                "native getdents64: {:?}",
                std::io::Error::last_os_error()
            );
            result as i64
        };
        let first = read_native(&native, &mut expected_bytes);
        assert!(first > 0 && first < PAGE_SIZE as i64);
        assert_getdents64_names(
            &checked_dirents64(&expected_bytes[..first as usize]),
            "entry",
        );
        let expected_result = if case == Case::CleanupAtEof {
            let eof = native.stream_position().unwrap();
            assert!(eof > 0);
            assert_eq!(directory.seek(SeekFrom::Start(eof)).unwrap(), eof);
            expected_bytes.copy_from_slice(&sentinel);
            assert_eq!(read_native(&native, &mut expected_bytes), 0);
            assert_eq!(expected_bytes, sentinel);
            0
        } else {
            first
        };
        let native_cursor = native.stream_position().unwrap();
        let before = directory.stream_position().unwrap();
        assert_eq!(duplicate.stream_position().unwrap(), before);
        fault.arm();
        let transport = getdents64(
            &mut ProviderMemory(&memory),
            &state,
            &[0, 0, length as u64, 0, 0, 0],
        );
        let snapshots = getdents64_alias_ledger(&fault);
        let expected_cursor = if fault.case().setup_succeeds() {
            native_cursor
        } else {
            before
        };
        assert_eq!(directory.stream_position().unwrap(), expected_cursor);
        assert_eq!(duplicate.stream_position().unwrap(), expected_cursor);
        let mut actual = vec![0; length];
        observer.read_raw(0, &mut actual).unwrap();
        let wanted_bytes = if fault.case().setup_succeeds() {
            &expected_bytes
        } else {
            &sentinel
        };
        assert_eq!(
            &actual, wanted_bytes,
            "native full buffer/guard effects for {case:?}"
        );
        assert_eq!(memory.entry_gate().test_state().copies, 0);
        assert_eq!(memory.entry_gate().test_state().retained_operands, 0);

        if fault.succeeds() {
            assert_eq!(transport, expected_result);
            assert!(memory.entry_gate().pending_failure().is_none());
            let observation = fault.assert_fired();
            assert_eq!(observation.case, Case::AtomicCollision);
            // After the finite allocator contention observation is sealed,
            // ordinary guest access and the shared descriptor can continue.
            // Directory cookies are opaque: sample the native EOF transition
            // instead of assuming EOF leaves its earlier cursor unchanged.
            let mut after_continuation = expected_bytes.clone();
            after_continuation[length - 1] = b'x';
            let mut native_continuation = after_continuation.clone();
            assert_eq!(read_native(&native, &mut native_continuation), 0);
            assert_eq!(
                native_continuation, after_continuation,
                "native EOF preserves the complete buffer"
            );
            let native_eof_cursor = native.stream_position().unwrap();
            memory.write_raw(length as u64 - 1, b"x").unwrap();
            assert_eq!(
                getdents64(
                    &mut ProviderMemory(&memory),
                    &state,
                    &[1, 0, length as u64, 0, 0, 0]
                ),
                0
            );
            assert_eq!(directory.stream_position().unwrap(), native_eof_cursor);
            assert_eq!(duplicate.stream_position().unwrap(), native_eof_cursor);
            eprintln!(
                "\nnative getdents EOF cursor before={native_cursor} after={native_eof_cursor}"
            );
            assert!(memory.entry_gate().pending_failure().is_none());
            observer.read_raw(0, &mut actual).unwrap();
            assert_eq!(
                actual, after_continuation,
                "EOF continuation preserves all other bytes"
            );
            assert_eq!(crate::memory::retained_write_aliases_for_test(), snapshots);
            drop(memory);
            drop(observer);
            assert_eq!(memory_owners(), 0);
            assert_eq!(observer_owners(), 0);
            assert_eq!(crate::memory::retained_write_aliases_for_test(), snapshots);
            eprintln!(
                "\natomic getdents case={case:?} result={transport} native={expected_result} cursor={native_cursor} continuation=true"
            );
            return;
        }

        assert_eq!(transport, negative_errno(libc::EFAULT));
        let pending = memory.entry_gate().pending_failure().unwrap();
        let error = pending.error();
        let cause = getdents64_alias_exact_cause(&fault, &snapshots, &error);
        let cause_owners = getdents64_alias_cause_owners(&error);
        assert_eq!(
            cause_owners.len(),
            if matches!(case, Case::ConstructionCleanup | Case::SuffixCleanup) {
                2
            } else {
                1
            }
        );
        let refused = memory.write_raw(0, b"ordinary result").unwrap_err();
        assert!(std::ptr::eq(
            cause,
            getdents64_alias_exact_cause(&fault, &snapshots, &refused)
        ));
        assert_eq!(getdents64_alias_cause_owners(&refused), cause_owners);
        // A second dispatch must stop at the sticky gate before directory I/O.
        assert_eq!(
            getdents64(
                &mut ProviderMemory(&memory),
                &state,
                &[1, 0, length as u64, 0, 0, 0]
            ),
            negative_errno(libc::EFAULT)
        );
        assert_eq!(directory.stream_position().unwrap(), expected_cursor);
        assert_eq!(duplicate.stream_position().unwrap(), expected_cursor);
        let again = memory.entry_gate().pending_failure().unwrap().error();
        assert!(std::ptr::eq(
            cause,
            getdents64_alias_exact_cause(&fault, &snapshots, &again)
        ));
        assert_eq!(getdents64_alias_cause_owners(&again), cause_owners);
        observer.read_raw(0, &mut actual).unwrap();
        assert_eq!(&actual, wanted_bytes);
        assert_eq!(memory.entry_gate().test_state().copies, 0);
        assert_eq!(memory.entry_gate().test_state().retained_operands, 0);
        assert_eq!(crate::memory::retained_write_aliases_for_test(), snapshots);
        eprintln!(
            "\natomic getdents case={case:?} transport={transport} native={expected_result} cursor={expected_cursor} continuation=false retained={} bytes_match=true ledger={snapshots:?} cause_owners={cause_owners:?}",
            snapshots.len()
        );
        // All pointer/context comparisons and diagnostics are complete. Drop
        // the ordinary error owners too before observing terminal retention.
        drop(again);
        drop(refused);
        drop(error);
        drop(pending);
        drop(cause_owners);
        drop(memory);
        drop(observer);
        assert_eq!(memory_owners(), 0);
        assert_eq!(observer_owners(), 0);
        assert_eq!(crate::memory::retained_write_aliases_for_test(), snapshots);
        // Covers actual no-retry, foreign-prefix reuse and retained mapping
        // observations after the last ordinary memory handle has been dropped.
        let observation = fault.assert_fired();
        assert_eq!(observation.case, case);
        assert_eq!(crate::memory::retained_write_aliases_for_test(), snapshots);
        eprintln!(
            "atomic getdents teardown case={case:?} ordinary_errors_dropped=true mapping_handles=0 retained={}",
            snapshots.len()
        );
    }

    const GETDENTS64_UPPER_WORDS: [u64; 5] = [
        0,
        1 << 32,
        1 << 63,
        0xa5a5_5a5a_0000_0000,
        0xffff_ffff_0000_0000,
    ];

    #[derive(Debug, PartialEq, Eq)]
    struct CheckedDirent64 {
        inode: u64,
        offset: i64,
        record_length: u16,
        kind: u8,
        name: Vec<u8>,
    }

    fn checked_dirents64(bytes: &[u8]) -> Vec<CheckedDirent64> {
        let mut records = Vec::new();
        let mut offset = 0;
        while offset < bytes.len() {
            let remaining = &bytes[offset..];
            assert!(remaining.len() >= 24, "truncated dirent64 header");
            let record_length = u16::from_ne_bytes(remaining[16..18].try_into().unwrap());
            let length = usize::from(record_length);
            assert!(
                length >= 24 && length.is_multiple_of(8),
                "invalid dirent64 length"
            );
            assert!(length <= remaining.len(), "dirent64 exceeds syscall result");
            let name_area = &remaining[19..length];
            let terminator = name_area.iter().position(|byte| *byte == 0).unwrap();
            assert!(terminator > 0, "dirent64 name must not be empty");
            let name = name_area[..terminator].to_vec();
            assert!(!name.contains(&b'/'), "dirent64 name contains a slash");
            assert_eq!((19 + terminator + 1 + 7) & !7, length);
            let inode = u64::from_ne_bytes(remaining[..8].try_into().unwrap());
            assert_ne!(inode, 0, "the controlled fixture has no deleted entries");
            let kind = remaining[18];
            assert!(kind == libc::DT_DIR || kind == libc::DT_REG);
            records.push(CheckedDirent64 {
                inode,
                offset: i64::from_ne_bytes(remaining[8..16].try_into().unwrap()),
                record_length,
                kind,
                name,
            });
            offset += length;
        }
        assert_eq!(offset, bytes.len());
        records
    }

    fn assert_getdents64_names(records: &[CheckedDirent64], entry: &str) {
        let mut names = BTreeMap::new();
        for record in records {
            assert!(names.insert(record.name.clone(), record.kind).is_none());
        }
        assert_eq!(
            names,
            BTreeMap::from([
                (b".".to_vec(), libc::DT_DIR),
                (b"..".to_vec(), libc::DT_DIR),
                (entry.as_bytes().to_vec(), libc::DT_REG),
            ])
        );
    }

    fn checked_getdents64(
        memory: &mut GuestMemory,
        state: &mut LoadedStaticElf,
        fd: u64,
        address: u64,
        length: u64,
    ) -> (i64, Vec<CheckedDirent64>) {
        let sentinel = vec![0xa7; (memory.guest_end() - memory.guest_base()) as usize];
        memory.write_raw(memory.guest_base(), &sentinel).unwrap();
        let result = syscall_result(
            memory,
            state,
            libc::SYS_getdents64,
            [
                fd,
                address,
                length,
                u64::MAX,
                0x5a5a_a5a5_dead_beef,
                1 << 63,
            ],
        );
        let mut actual = vec![0; sentinel.len()];
        memory.read_raw(memory.guest_base(), &mut actual).unwrap();
        if result <= 0 {
            assert_eq!(
                actual, sentinel,
                "fd={fd:#x}, address={address:#x}, count={length}, result={result}"
            );
            return (result, Vec::new());
        }
        assert!(result as u64 <= length);
        let start = usize::try_from(address.checked_sub(memory.guest_base()).unwrap()).unwrap();
        let end = start.checked_add(result as usize).unwrap();
        assert!(end <= actual.len());
        assert_eq!(&actual[..start], &sentinel[..start], "prefix sentinel");
        assert_eq!(
            &actual[end..],
            &sentinel[end..],
            "buffer tail and suffix sentinel"
        );
        (result, checked_dirents64(&actual[start..end]))
    }

    fn getdents64_test_directory(path: &Path) -> std::fs::File {
        let file = std::fs::File::open(path).unwrap();
        // Keep host descriptors different from every modeled guest key, including
        // 257, so bypassing guest-table translation cannot accidentally work.
        // SAFETY: file owns a live descriptor; fcntl returns a new owned one.
        let fd = unsafe { libc::fcntl(file.as_raw_fd(), libc::F_DUPFD_CLOEXEC, 258) };
        assert!(fd >= 258);
        assert_ne!(fd, libc::c_int::MAX);
        // SAFETY: the successful fcntl call transferred ownership of fd.
        unsafe { std::fs::File::from_raw_fd(fd) }
    }

    fn getdents64_position(
        memory: &mut GuestMemory,
        state: &mut LoadedStaticElf,
        fd: libc::c_int,
    ) -> i64 {
        let position = syscall_result(
            memory,
            state,
            libc::SYS_lseek,
            [fd as u64, 0, libc::SEEK_CUR as u64, 0, 0, 0],
        );
        assert!(position >= 0);
        position
    }

    fn rewind_getdents64(memory: &mut GuestMemory, state: &mut LoadedStaticElf, fd: libc::c_int) {
        assert_eq!(
            syscall_result(
                memory,
                state,
                libc::SYS_lseek,
                [fd as u64, 0, libc::SEEK_SET as u64, 0, 0, 0],
            ),
            0
        );
    }

    fn native_getdents64_short_position(
        file: &mut std::fs::File,
        upper: u64,
        invalid_pointer: bool,
        length: u64,
    ) -> i64 {
        assert!(matches!(length, 0 | 1 | 23));
        let mut bytes = [0xa7; 16 + 23 + 16];
        let buffer = if invalid_pointer {
            usize::MAX as *mut libc::c_void
        } else {
            bytes[16..].as_mut_ptr().cast::<libc::c_void>()
        };
        // SAFETY: file owns a live descriptor. The valid buffer has room for
        // every tested count; Linux validates the deliberately invalid pointer.
        // This is an independent native syscall, not executor reinjection.
        let result = unsafe {
            libc::syscall(
                libc::SYS_getdents64,
                upper | file.as_raw_fd() as u64,
                buffer,
                length,
                u64::MAX,
                0x5a5a_a5a5_dead_beef_u64,
                1_u64 << 63,
            )
        };
        assert_eq!(result, -1, "native short count={length}, upper={upper:#x}");
        assert_eq!(
            std::io::Error::last_os_error().raw_os_error(),
            Some(libc::EINVAL)
        );
        assert_eq!(bytes, [0xa7; 16 + 23 + 16], "native whole-buffer sentinels");
        i64::try_from(file.stream_position().unwrap()).unwrap()
    }

    #[test]
    fn getdents64_consumes_low_descriptor_words() {
        const BUFFER: u64 = 0x100;
        const CAPACITY: u64 = 1024;
        let root = TestDir::new();
        let mut state = test_state(&root.0);
        let mut memory = GuestMemory::new(0, PAGE_SIZE as usize).unwrap();
        for fd in [0, 1, 3, 257, libc::c_int::MAX] {
            let directory = root.0.join(format!("directory-{fd}"));
            std::fs::create_dir(&directory).unwrap();
            std::fs::write(directory.join(format!("entry-{fd}")), b"payload").unwrap();
            state
                .files
                .insert(fd, getdents64_test_directory(&directory));
        }
        for fd in [0, 3, 257, libc::c_int::MAX] {
            let (count, canonical) =
                checked_getdents64(&mut memory, &mut state, fd as u64, BUFFER, CAPACITY);
            assert!(count > 0, "canonical guest fd {fd}");
            assert_getdents64_names(&canonical, &format!("entry-{fd}"));
            for upper in GETDENTS64_UPPER_WORDS {
                rewind_getdents64(&mut memory, &mut state, fd);
                let (alias_count, alias) = checked_getdents64(
                    &mut memory,
                    &mut state,
                    upper | fd as u64,
                    BUFFER,
                    CAPACITY,
                );
                assert_eq!(alias_count, count, "upper={upper:#x}, fd={fd}");
                assert_getdents64_names(&alias, &format!("entry-{fd}"));
                // Compare all fields except padding within the same rewound
                // stream. Inodes and opaque cookies across different directories
                // are deliberately not compared.
                assert_eq!(alias, canonical, "upper={upper:#x}, fd={fd}");
                assert_eq!(
                    checked_getdents64(
                        &mut memory,
                        &mut state,
                        upper | fd as u64,
                        BUFFER,
                        CAPACITY
                    )
                    .0,
                    0,
                    "alias must reach EOF"
                );
            }
        }
        assert_eq!(
            getdents64_position(&mut memory, &mut state, 1),
            0,
            "fd 257 must not consume the fd 1 decoy"
        );
    }

    /// Compare a copyout boundary with an independent native open of the same
    /// unchanged directory at the exact preceding opaque cookie. The native
    /// mapping mirrors the guest's middle PROT_NONE page and inaccessible tail;
    /// no executor helper or guest-backed alias is used for the reference.
    fn native_checked_getdents64_copyout(
        memory: &mut GuestMemory,
        state: &mut LoadedStaticElf,
        directory: &Path,
        fd: u64,
        alias: libc::c_int,
        address: u64,
        length: u64,
    ) -> (i64, Vec<CheckedDirent64>) {
        struct NativeArena(*mut libc::c_void, usize);
        impl Drop for NativeArena {
            fn drop(&mut self) {
                // SAFETY: this arena owns the complete mmap reservation.
                assert_eq!(unsafe { libc::munmap(self.0, self.1) }, 0);
            }
        }

        assert_eq!(memory.guest_base(), 0);
        assert_eq!(memory.guest_end(), 3 * PAGE_SIZE);
        assert!(length <= 1024);
        let before = getdents64_position(memory, state, fd as libc::c_int);
        assert_eq!(getdents64_position(memory, state, alias), before);
        let native_file = std::fs::File::open(directory).unwrap();
        // SAFETY: independent live directory fd and a previously observed cookie.
        assert_eq!(
            unsafe { libc::lseek(native_file.as_raw_fd(), before, libc::SEEK_SET) },
            before
        );
        let size = 4 * PAGE_SIZE as usize;
        // SAFETY: independent private mapping, no shared Rust references.
        let mapping = unsafe {
            libc::mmap(
                std::ptr::null_mut(),
                size,
                libc::PROT_READ | libc::PROT_WRITE,
                libc::MAP_PRIVATE | libc::MAP_ANONYMOUS,
                -1,
                0,
            )
        };
        assert_ne!(mapping, libc::MAP_FAILED);
        let arena = NativeArena(mapping, size);
        // SAFETY: the reservation is writable; protect exactly the page holes
        // modeled by this test, including the page beyond GuestMemory's end.
        unsafe {
            std::ptr::write_bytes(mapping.cast::<u8>(), 0xa7, size);
            assert_eq!(
                libc::mprotect(
                    mapping.cast::<u8>().add(PAGE_SIZE as usize).cast(),
                    PAGE_SIZE as usize,
                    libc::PROT_NONE
                ),
                0
            );
            assert_eq!(
                libc::mprotect(
                    mapping.cast::<u8>().add(3 * PAGE_SIZE as usize).cast(),
                    PAGE_SIZE as usize,
                    libc::PROT_NONE
                ),
                0
            );
        }
        let pointer = if address == u64::MAX {
            std::ptr::with_exposed_provenance_mut::<libc::c_void>(usize::MAX)
        } else {
            assert!(address < memory.guest_end());
            // SAFETY: the address is within the owned reservation, possibly
            // protected; only the kernel attempts the actual output access.
            unsafe { mapping.cast::<u8>().add(address as usize).cast() }
        };
        // SAFETY: the fd is live; the kernel handles the intentional faults.
        // Count is canonical unsigned32 here; only fd has high register bits.
        let native = unsafe {
            libc::syscall(
                libc::SYS_getdents64,
                (fd & 0xffff_ffff_0000_0000) | native_file.as_raw_fd() as u64,
                pointer,
                length,
                u64::MAX,
                0x5a5a_a5a5_dead_beef_u64,
                1_u64 << 63,
            )
        };
        let expected_result = if native == -1 {
            negative_errno(std::io::Error::last_os_error().raw_os_error().unwrap())
        } else {
            native as i64
        };
        // Capture errno above before any other libc call.
        let expected_position = unsafe { libc::lseek(native_file.as_raw_fd(), 0, libc::SEEK_CUR) };
        assert!(expected_position >= 0);
        // SAFETY: restore the owned arena before reading every byte and guard.
        assert_eq!(
            unsafe { libc::mprotect(mapping, size, libc::PROT_READ | libc::PROT_WRITE) },
            0
        );
        let native_bytes =
            unsafe { std::slice::from_raw_parts(mapping.cast::<u8>(), size) }.to_vec();
        assert!(
            native_bytes[3 * PAGE_SIZE as usize..]
                .iter()
                .all(|byte| *byte == 0xa7),
            "native protected tail guard"
        );
        drop(arena);

        let sentinel = vec![0xa7; 3 * PAGE_SIZE as usize];
        memory.write_raw(0, &sentinel).unwrap();
        let result = syscall_result(
            memory,
            state,
            libc::SYS_getdents64,
            [
                fd,
                address,
                length,
                u64::MAX,
                0x5a5a_a5a5_dead_beef,
                1 << 63,
            ],
        );
        let mut actual = vec![0; sentinel.len()];
        memory.read_raw(0, &mut actual).unwrap();
        assert_eq!(
            result, expected_result,
            "native result fd={fd:#x} address={address:#x} count={length}"
        );
        assert_eq!(
            actual,
            native_bytes[..sentinel.len()],
            "native full arena, including partial writes, padding and guards"
        );
        assert_eq!(
            getdents64_position(memory, state, fd as libc::c_int),
            expected_position,
            "native exact post-call cursor"
        );
        assert_eq!(
            getdents64_position(memory, state, alias),
            expected_position,
            "dup observes native post-call cursor"
        );
        if result <= 0 {
            return (result, Vec::new());
        }
        assert!(result as u64 <= length);
        let start = usize::try_from(address).unwrap();
        let end = start.checked_add(result as usize).unwrap();
        assert!(end <= actual.len());
        (result, checked_dirents64(&actual[start..end]))
    }

    #[test]
    fn getdents64_low_words_preserve_errors_and_cursor() {
        const BUFFER: u64 = 0x100;
        const CAPACITY: u64 = 1024;
        let root = TestDir::new();
        let directory = root.0.join("directory");
        let decoy = root.0.join("decoy");
        std::fs::create_dir(&directory).unwrap();
        std::fs::create_dir(&decoy).unwrap();
        std::fs::write(directory.join("entry"), b"payload").unwrap();
        std::fs::write(decoy.join("decoy-entry"), b"decoy").unwrap();
        // Independent opens of the same controlled directories supply the
        // native cursor oracle. A dup or try_clone would share the tested
        // cursor and could make an incorrect advance compare equal to itself.
        let mut native_directories = BTreeMap::from([
            (3, std::fs::File::open(&directory).unwrap()),
            (257, std::fs::File::open(&decoy).unwrap()),
        ]);
        let mut state = test_state(&root.0);
        state.files.insert(3, getdents64_test_directory(&directory));
        state.files.insert(257, getdents64_test_directory(&decoy));
        state
            .files
            .insert(4, std::fs::File::open(directory.join("entry")).unwrap());
        for (fd, path) in [(5, directory.clone()), (6, directory.join("entry"))] {
            state.files.insert(
                fd,
                std::fs::OpenOptions::new()
                    .read(true)
                    .custom_flags(libc::O_PATH)
                    .open(path)
                    .unwrap(),
            );
        }
        state.files.insert(7, getdents64_test_directory(&directory));
        let mut memory = GuestMemory::new(0, 3 * PAGE_SIZE as usize).unwrap();
        memory.map_user_range(0, PAGE_SIZE, false).unwrap();
        memory.map_user_range(PAGE_SIZE, PAGE_SIZE, true).unwrap();
        memory
            .map_user_range(2 * PAGE_SIZE, PAGE_SIZE, false)
            .unwrap();
        memory.enable_user_access();
        let alias = syscall_result(&mut memory, &mut state, libc::SYS_dup, [3, 0, 0, 0, 0, 0]);
        assert!(alias >= 0 && alias != 3 && alias != 257 && alias != 7);
        assert_eq!(
            syscall_result(&mut memory, &mut state, libc::SYS_close, [7, 0, 0, 0, 0, 0]),
            0
        );

        for upper in GETDENTS64_UPPER_WORDS {
            for low in [
                0x8000_0000,
                0x8000_0003,
                0x8000_0101,
                u32::MAX,
                libc::AT_FDCWD as u32,
                7,
                99,
            ] {
                for address in [BUFFER, u64::MAX] {
                    for length in [0, 1, 23, 24, CAPACITY] {
                        assert_eq!(
                            checked_getdents64(
                                &mut memory,
                                &mut state,
                                upper | u64::from(low),
                                address,
                                length
                            )
                            .0,
                            negative_errno(libc::EBADF),
                            "low={low:#x}, upper={upper:#x}, count={length}"
                        );
                    }
                }
            }
            for (fd, errno) in [(4, libc::ENOTDIR), (5, libc::EBADF), (6, libc::EBADF)] {
                for length in [0, 1, 23, 24, CAPACITY] {
                    assert_eq!(
                        checked_getdents64(&mut memory, &mut state, upper | fd, u64::MAX, length).0,
                        negative_errno(errno),
                        "directory validation must precede the pointer"
                    );
                }
            }
            for fd in [3, 257] {
                for address in [BUFFER, u64::MAX] {
                    for length in [0, 1, 23] {
                        assert_eq!(
                            checked_getdents64(
                                &mut memory,
                                &mut state,
                                upper | fd,
                                address,
                                length
                            )
                            .0,
                            negative_errno(libc::EINVAL),
                            "nonempty stream and small canonical count"
                        );
                        let expected = native_getdents64_short_position(
                            native_directories.get_mut(&(fd as libc::c_int)).unwrap(),
                            upper,
                            address == u64::MAX,
                            length,
                        );
                        assert_eq!(
                            getdents64_position(&mut memory, &mut state, fd as libc::c_int),
                            expected,
                            "native short-count cursor: fd={fd}, upper={upper:#x}, count={length}"
                        );
                        if fd == 3 {
                            assert_eq!(
                                getdents64_position(&mut memory, &mut state, alias as libc::c_int),
                                expected,
                                "the dup must observe the same native short-count cursor"
                            );
                        }
                    }
                }
            }
        }

        let decoy_before_faults = getdents64_position(&mut memory, &mut state, 257);
        let faults = [
            (u64::MAX, CAPACITY),
            (memory.guest_end() - 16, 24),
            (PAGE_SIZE, 24),
            (PAGE_SIZE - 23, 24),
        ];
        // Linux copies individual fields before a later fault and does not
        // write record padding. Compare those exact effects and the resulting
        // shared cursor with a native open, rather than imposing preflight.
        for upper in GETDENTS64_UPPER_WORDS {
            for (address, length) in faults {
                let before = getdents64_position(&mut memory, &mut state, 3);
                assert_eq!(
                    getdents64_position(&mut memory, &mut state, alias as libc::c_int),
                    before
                );
                let (result, records) = native_checked_getdents64_copyout(
                    &mut memory,
                    &mut state,
                    &directory,
                    upper | 3,
                    alias as libc::c_int,
                    address,
                    length,
                );
                if address == PAGE_SIZE - 23 {
                    assert_eq!(result, 24, "unused alignment padding need not be writable");
                    assert_eq!(records.len(), 1);
                } else {
                    assert_eq!(result, negative_errno(libc::EFAULT));
                }
                // Isolate the next cell only after checking actual copyout and
                // both post-call cursors; no successful progress is hidden.
                assert_eq!(
                    syscall_result(
                        &mut memory,
                        &mut state,
                        libc::SYS_lseek,
                        [3, before as u64, libc::SEEK_SET as u64, 0, 0, 0]
                    ),
                    before
                );
                assert_eq!(
                    getdents64_position(&mut memory, &mut state, alias as libc::c_int),
                    before
                );
            }
        }
        let (count, canonical) = checked_getdents64(&mut memory, &mut state, 3, BUFFER, CAPACITY);
        assert!(count > 24);
        assert_getdents64_names(&canonical, "entry");
        for upper in GETDENTS64_UPPER_WORDS {
            assert_eq!(
                checked_getdents64(&mut memory, &mut state, upper | alias as u64, u64::MAX, 1).0,
                0
            );
            // EOF has no actor/output write. Even invalid/protected pointers
            // return zero; any filesystem cookie normalization must match the
            // independently opened native stream exactly, not a guessed zero.
            for (address, length) in faults {
                let eof = getdents64_position(&mut memory, &mut state, 3);
                assert_eq!(
                    getdents64_position(&mut memory, &mut state, alias as libc::c_int),
                    eof
                );
                let (result, records) = native_checked_getdents64_copyout(
                    &mut memory,
                    &mut state,
                    &directory,
                    upper | 3,
                    alias as libc::c_int,
                    address,
                    length,
                );
                assert_eq!(result, 0);
                assert!(records.is_empty());
                let mut untouched = vec![0; 3 * PAGE_SIZE as usize];
                memory.read_raw(0, &mut untouched).unwrap();
                assert_eq!(untouched, vec![0xa7; untouched.len()], "EOF writes nothing");
            }
            rewind_getdents64(&mut memory, &mut state, alias as libc::c_int);
            for (address, length) in faults {
                let before = getdents64_position(&mut memory, &mut state, 3);
                assert_eq!(before, 0, "the explicit rewind must reset the cursor");
                assert_eq!(
                    getdents64_position(&mut memory, &mut state, alias as libc::c_int),
                    before
                );
                let (result, records) = native_checked_getdents64_copyout(
                    &mut memory,
                    &mut state,
                    &directory,
                    upper | alias as u64,
                    3,
                    address,
                    length,
                );
                if address == PAGE_SIZE - 23 {
                    assert_eq!(result, 24);
                    assert_eq!(records.len(), 1);
                    assert_eq!(records[0], canonical[0]);
                } else {
                    assert_eq!(result, negative_errno(libc::EFAULT));
                }
                rewind_getdents64(&mut memory, &mut state, alias as libc::c_int);
            }
            // A usable 24-byte prefix succeeds although the rest of the
            // requested buffer is inaccessible, and consumes exactly one record.
            let (first_count, mut shared) = checked_getdents64(
                &mut memory,
                &mut state,
                upper | alias as u64,
                PAGE_SIZE - 24,
                48,
            );
            assert_eq!(first_count, 24);
            assert_eq!(shared.len(), 1);
            let (rest_count, rest) =
                checked_getdents64(&mut memory, &mut state, upper | 3, BUFFER, CAPACITY);
            assert_eq!(first_count + rest_count, count);
            shared.extend(rest);
            assert_getdents64_names(&shared, "entry");
            assert_eq!(
                shared, canonical,
                "dup descriptors share the rewound cursor"
            );
            assert_eq!(
                checked_getdents64(
                    &mut memory,
                    &mut state,
                    upper | alias as u64,
                    BUFFER,
                    CAPACITY
                )
                .0,
                0
            );
        }
        assert_eq!(
            getdents64_position(&mut memory, &mut state, 257),
            decoy_before_faults,
            "primary-directory operations must preserve the tested decoy cursor"
        );
        let (_, decoy_records) = checked_getdents64(&mut memory, &mut state, 257, BUFFER, CAPACITY);
        assert_getdents64_names(&decoy_records, "decoy-entry");
    }

    #[test]
    fn getdents64_returns_host_directory_entries() {
        const PATH_ADDRESS: u64 = 0x100;
        const DIRENTS_ADDRESS: u64 = 0x1000;
        const DIRENTS_CAPACITY: usize = 0x4000;

        let root = TestDir::new();
        std::fs::write(root.0.join("alpha"), b"a").unwrap();
        std::fs::write(root.0.join("beta"), b"b").unwrap();
        let mut state = test_state(&root.0);
        let mut memory = GuestMemory::new(0, 0x8000).unwrap();
        memory.write(PATH_ADDRESS, b".\0").unwrap();

        let fd = syscall_result(
            &mut memory,
            &mut state,
            libc::SYS_openat,
            [
                libc::AT_FDCWD as u64,
                PATH_ADDRESS,
                (libc::O_RDONLY | libc::O_DIRECTORY) as u64 | (1_u64 << 31),
                0xdead,
                0,
                0,
            ],
        );
        assert_eq!(fd, 3);
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_getdents64,
                [fd as u64, DIRENTS_ADDRESS, 0, 0, 0, 0],
            ),
            negative_errno(libc::EINVAL)
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_getdents64,
                [fd as u64, u64::MAX, 23, 0, 0, 0],
            ),
            negative_errno(libc::EINVAL)
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_getdents64,
                [fd as u64, DIRENTS_ADDRESS, 1, 0, 0, 0],
            ),
            negative_errno(libc::EINVAL)
        );
        let count = syscall_result(
            &mut memory,
            &mut state,
            libc::SYS_getdents64,
            [fd as u64, DIRENTS_ADDRESS, DIRENTS_CAPACITY as u64, 0, 0, 0],
        );
        assert!(count > 0);
        let mut bytes = vec![0; count as usize];
        memory.read(DIRENTS_ADDRESS, &mut bytes).unwrap();

        let mut names = Vec::new();
        let mut offset = 0;
        while offset < bytes.len() {
            assert!(offset + 19 <= bytes.len());
            let record_length =
                usize::from(u16::from_ne_bytes([bytes[offset + 16], bytes[offset + 17]]));
            assert!(record_length >= 19);
            assert!(offset + record_length <= bytes.len());
            let name = &bytes[offset + 19..offset + record_length];
            let end = name.iter().position(|byte| *byte == 0).unwrap();
            names.push(name[..end].to_vec());
            offset += record_length;
        }
        assert!(names.iter().any(|name| name == b"."));
        assert!(names.iter().any(|name| name == b".."));
        assert!(names.iter().any(|name| name == b"alpha"));
        assert!(names.iter().any(|name| name == b"beta"));
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_getdents64,
                [fd as u64, DIRENTS_ADDRESS, DIRENTS_CAPACITY as u64, 0, 0, 0,],
            ),
            0
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_getdents64,
                [fd as u64, u64::MAX, 1, 0, 0, 0],
            ),
            0
        );
    }

    #[test]
    fn getdents64_does_not_advance_directory_on_guest_fault() {
        let root = TestDir::new();
        std::fs::write(root.0.join("entry"), b"x").unwrap();
        let mut state = test_state(&root.0);
        state.files.insert(3, std::fs::File::open(&root.0).unwrap());
        let mut memory = GuestMemory::new(0, 2 * PAGE_SIZE as usize).unwrap();
        memory.map_user_range(0, PAGE_SIZE, false).unwrap();
        memory.map_user_range(PAGE_SIZE, PAGE_SIZE, true).unwrap();
        memory.enable_user_access();

        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_getdents64,
                [3, PAGE_SIZE, PAGE_SIZE, 0, 0, 0],
            ),
            negative_errno(libc::EFAULT)
        );
        assert!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_getdents64,
                [3, 0, PAGE_SIZE, 0, 0, 0],
            ) > 0
        );
    }

    #[test]
    fn descriptor_lifecycle_and_error_precedence_match_linux() {
        const PATH_ADDRESS: u64 = 0x100;
        const PAYLOAD_ADDRESS: u64 = 0x200;
        const STAT_ADDRESS: u64 = 0x300;

        let root = TestDir::new();
        let mut state = test_state(&root.0);
        let mut memory = GuestMemory::new(0, 0x3000).unwrap();
        memory.write(PATH_ADDRESS, b"stdout-file\0").unwrap();
        memory.write(PAYLOAD_ADDRESS, b"redirected").unwrap();

        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_close,
                [libc::STDOUT_FILENO as u64, 0, 0, 0, 0, 0],
            ),
            0
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_close,
                [libc::STDOUT_FILENO as u64, 0, 0, 0, 0, 0],
            ),
            negative_errno(libc::EBADF)
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_fstat,
                [libc::STDOUT_FILENO as u64, STAT_ADDRESS, 0, 0, 0, 0],
            ),
            negative_errno(libc::EBADF)
        );

        let fd = syscall_result(
            &mut memory,
            &mut state,
            libc::SYS_open,
            [
                PATH_ADDRESS,
                (libc::O_CREAT | libc::O_WRONLY) as u64,
                0o600,
                0,
                0,
                0,
            ],
        );
        assert_eq!(fd, libc::STDOUT_FILENO as i64);
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_write,
                [fd as u64, PAYLOAD_ADDRESS, 10, 0, 0, 0],
            ),
            10
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_read,
                [fd as u64, u64::MAX, 1, 0, 0, 0],
            ),
            negative_errno(libc::EBADF)
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_pread64,
                [fd as u64, u64::MAX, 1, 0, 0, 0],
            ),
            negative_errno(libc::EBADF)
        );
        let read_only_fd = syscall_result(
            &mut memory,
            &mut state,
            libc::SYS_open,
            [PATH_ADDRESS, libc::O_RDONLY as u64, 0, 0, 0, 0],
        );
        assert_eq!(read_only_fd, 3);
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_write,
                [read_only_fd as u64, u64::MAX, 1, 0, 0, 0],
            ),
            negative_errno(libc::EBADF)
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_getdents64,
                [read_only_fd as u64, u64::MAX, 1, 0, 0, 0],
            ),
            negative_errno(libc::ENOTDIR)
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_read,
                [99, u64::MAX, 1, 0, 0, 0],
            ),
            negative_errno(libc::EBADF)
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_write,
                [99, u64::MAX, 1, 0, 0, 0],
            ),
            negative_errno(libc::EBADF)
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_pread64,
                [99, u64::MAX, 1, 0, 0, 0],
            ),
            negative_errno(libc::EBADF)
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_getdents64,
                [99, u64::MAX, 1, 0, 0, 0],
            ),
            negative_errno(libc::EBADF)
        );
        assert_eq!(
            std::fs::read(root.0.join("stdout-file")).unwrap(),
            b"redirected"
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_close,
                [libc::STDIN_FILENO as u64, 0, 0, 0, 0, 0],
            ),
            0
        );
        let reused_stdin = syscall_result(
            &mut memory,
            &mut state,
            libc::SYS_open,
            [PATH_ADDRESS, libc::O_RDONLY as u64, 0, 0, 0, 0],
        );
        assert_eq!(reused_stdin, libc::STDIN_FILENO as i64);
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_read,
                [reused_stdin as u64, 0x500, 10, 0, 0, 0],
            ),
            10
        );
        let mut reopened_input = [0; 10];
        memory.read(0x500, &mut reopened_input).unwrap();
        assert_eq!(&reopened_input, b"redirected");
    }

    #[test]
    fn rejects_supervisor_procfs_and_reports_long_paths() {
        const PATH_ADDRESS: u64 = 0x100;
        const LINK_ADDRESS: u64 = 0x400;
        const STAT_ADDRESS: u64 = 0x800;
        const LONG_PATH_ADDRESS: u64 = 0x1000;

        let root = TestDir::new();
        let mut state = test_state(&root.0);
        let mut memory = GuestMemory::new(0, 0x4000).unwrap();
        let proc_mem = format!("/proc/{}/mem\0", std::process::id());
        memory.write(PATH_ADDRESS, proc_mem.as_bytes()).unwrap();
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_open,
                [PATH_ADDRESS, libc::O_RDONLY as u64, 0, 0, 0, 0],
            ),
            negative_errno(libc::EACCES)
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_stat,
                [PATH_ADDRESS, STAT_ADDRESS, 0, 0, 0, 0],
            ),
            negative_errno(libc::EACCES)
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_statx,
                [
                    libc::AT_FDCWD as u64,
                    PATH_ADDRESS,
                    0,
                    libc::STATX_BASIC_STATS as u64,
                    STAT_ADDRESS,
                    0,
                ],
            ),
            negative_errno(libc::EACCES)
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_access,
                [PATH_ADDRESS, libc::F_OK as u64, 0, 0, 0, 0],
            ),
            negative_errno(libc::EACCES)
        );

        std::os::unix::fs::symlink(&proc_mem[..proc_mem.len() - 1], root.0.join("proc-link"))
            .unwrap();
        memory.write(LINK_ADDRESS, b"proc-link\0").unwrap();
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_lstat,
                [LINK_ADDRESS, STAT_ADDRESS, 0, 0, 0, 0],
            ),
            0
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_stat,
                [LINK_ADDRESS, STAT_ADDRESS, 0, 0, 0, 0],
            ),
            negative_errno(libc::EACCES)
        );

        memory.write(LONG_PATH_ADDRESS, b"missing\0").unwrap();
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_access,
                [LONG_PATH_ADDRESS, 8, 0, 0, 0, 0],
            ),
            negative_errno(libc::EINVAL)
        );
        memory.write(LONG_PATH_ADDRESS, &[120; 4096]).unwrap();
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_open,
                [LONG_PATH_ADDRESS, libc::O_RDONLY as u64, 0, 0, 0, 0],
            ),
            negative_errno(libc::ENAMETOOLONG)
        );
    }

    #[test]
    fn relative_open_keeps_cwd_directory_identity() {
        const PATH_ADDRESS: u64 = 0x100;
        const READ_ADDRESS: u64 = 0x200;

        let root = TestDir::new();
        let original = root.0.join("original");
        let moved = root.0.join("moved");
        std::fs::create_dir(&original).unwrap();
        std::fs::write(original.join("value"), b"original").unwrap();
        let mut state = test_state(&original);
        std::fs::rename(&original, &moved).unwrap();
        std::fs::create_dir(&original).unwrap();

        let mut memory = GuestMemory::new(0, 0x1000).unwrap();
        memory.write(PATH_ADDRESS, b"value\0").unwrap();
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_access,
                [PATH_ADDRESS, libc::F_OK as u64, 0, 0, 0, 0],
            ),
            0
        );
        let fd = syscall_result(
            &mut memory,
            &mut state,
            libc::SYS_openat,
            [
                libc::AT_FDCWD as u64,
                PATH_ADDRESS,
                libc::O_RDONLY as u64,
                0,
                0,
                0,
            ],
        );
        assert_eq!(fd, 3);
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_read,
                [fd as u64, READ_ADDRESS, 8, 0, 0, 0],
            ),
            8
        );
        let mut actual = [0; 8];
        memory.read(READ_ADDRESS, &mut actual).unwrap();
        assert_eq!(&actual, b"original");
    }

    #[test]
    fn creat_creates_and_truncates_like_open_o_creat() {
        const PATH_ADDRESS: u64 = 0x100;
        const WRITE_ADDRESS: u64 = 0x200;

        let root = TestDir::new();
        let target = root.0.join("archive");
        // A pre-existing longer file proves creat applies O_TRUNC.
        std::fs::write(&target, b"stale-and-longer-than-new").unwrap();

        let mut state = test_state(&root.0);
        let mut memory = GuestMemory::new(0, 0x1000).unwrap();
        memory.write(PATH_ADDRESS, b"archive\0").unwrap();
        memory.write(WRITE_ADDRESS, b"tar\n").unwrap();

        // creat(path, 0o644) must open the existing file, not fall through to
        // ENOSYS as it did before this handler existed.
        let fd = syscall_result(
            &mut memory,
            &mut state,
            libc::SYS_creat,
            [PATH_ADDRESS, 0o644, 0, 0, 0, 0],
        );
        assert_eq!(fd, 3, "creat should return the first free guest fd");

        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_write,
                [fd as u64, WRITE_ADDRESS, 4, 0, 0, 0],
            ),
            4
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_close,
                [fd as u64, 0, 0, 0, 0, 0]
            ),
            0
        );

        // O_TRUNC replaced the stale content entirely.
        assert_eq!(std::fs::read(&target).unwrap(), b"tar\n");

        // creat on a brand-new path creates it.
        memory.write(PATH_ADDRESS, b"fresh\0").unwrap();
        let fresh_fd = syscall_result(
            &mut memory,
            &mut state,
            libc::SYS_creat,
            [PATH_ADDRESS, 0o600, 0, 0, 0, 0],
        );
        assert!(fresh_fd >= 3, "creat on a new path should succeed");
        assert!(root.0.join("fresh").exists());
    }

    #[test]
    fn chdir_and_fchdir_update_working_directory() {
        const PATH_ADDRESS: u64 = 0x100;
        const CWD_ADDRESS: u64 = 0x200;

        let root = TestDir::new();
        let child = root.0.join("child");
        std::fs::create_dir(&child).unwrap();
        let mut state = test_state(&root.0);
        let mut memory = GuestMemory::new(0, 0x1000).unwrap();

        memory.write(PATH_ADDRESS, b".\0").unwrap();
        let root_fd = syscall_result(
            &mut memory,
            &mut state,
            libc::SYS_openat,
            [
                libc::AT_FDCWD as u64,
                PATH_ADDRESS,
                (libc::O_RDONLY | libc::O_DIRECTORY) as u64,
                0,
                0,
                0,
            ],
        );
        assert_eq!(root_fd, 3);

        memory.write(PATH_ADDRESS, b"child\0").unwrap();
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_chdir,
                [PATH_ADDRESS, 0, 0, 0, 0, 0],
            ),
            0
        );
        assert_eq!(state.cwd, child);

        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_fchdir,
                [root_fd as u64, 0, 0, 0, 0, 0],
            ),
            0
        );
        assert_eq!(state.cwd, root.0);

        let expected_len = root.0.as_os_str().as_bytes().len() + 1;
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_getcwd,
                [CWD_ADDRESS, expected_len as u64, 0, 0, 0, 0],
            ),
            expected_len as i64
        );
        let mut cwd = vec![0; expected_len];
        memory.read(CWD_ADDRESS, &mut cwd).unwrap();
        assert_eq!(&cwd[..expected_len - 1], root.0.as_os_str().as_bytes());
    }

    #[test]
    fn host_read_forwards_input_without_consuming_on_guest_fault() {
        let (reader, mut writer) = UnixStream::pair().unwrap();
        writer.write_all(b"hello\n").unwrap();
        drop(writer);
        let mut memory = GuestMemory::new(0, PAGE_SIZE as usize).unwrap();

        assert_eq!(
            host_read(&mut memory, reader.as_raw_fd(), u64::MAX, 1),
            negative_errno(libc::EFAULT)
        );
        assert_eq!(
            host_read(&mut memory, reader.as_raw_fd(), u64::MAX, 0),
            negative_errno(libc::EFAULT)
        );
        assert_eq!(host_read(&mut memory, reader.as_raw_fd(), 0x100, 32), 6);
        let mut actual = [0; 6];
        memory.read(0x100, &mut actual).unwrap();
        assert_eq!(&actual, b"hello\n");
        assert_eq!(host_read(&mut memory, reader.as_raw_fd(), 0x200, 32), 0);

        let (reader, mut writer) = UnixStream::pair().unwrap();
        let delayed_writer = std::thread::spawn(move || {
            std::thread::sleep(std::time::Duration::from_millis(20));
            writer.write_all(b"hi").unwrap();
        });
        assert_eq!(host_read(&mut memory, reader.as_raw_fd(), 0x300, 32), 2);
        delayed_writer.join().unwrap();
        let mut delayed = [0; 2];
        memory.read(0x300, &mut delayed).unwrap();
        assert_eq!(&delayed, b"hi");
    }

    #[test]
    fn read_limits_host_consumption_to_the_accessible_guest_prefix() {
        let root = TestDir::new();
        let path = root.0.join("input");
        std::fs::write(&path, b"abcdefgh").unwrap();
        let mut state = test_state(&root.0);
        state.files.insert(3, std::fs::File::open(&path).unwrap());
        state.files.insert(4, std::fs::File::open(&path).unwrap());
        let mut memory = GuestMemory::new(0, 2 * PAGE_SIZE as usize).unwrap();
        memory.map_user_range(0, PAGE_SIZE, false).unwrap();
        memory.map_user_range(PAGE_SIZE, PAGE_SIZE, true).unwrap();
        memory.enable_user_access();

        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_read,
                [3, PAGE_SIZE - 4, 8, 0, 0, 0],
            ),
            4
        );
        let mut first = [0; 4];
        memory.read(PAGE_SIZE - 4, &mut first).unwrap();
        assert_eq!(&first, b"abcd");
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_read,
                [3, 0x100, 4, 0, 0, 0],
            ),
            4
        );
        let mut second = [0; 4];
        memory.read(0x100, &mut second).unwrap();
        assert_eq!(&second, b"efgh");

        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_read,
                [4, PAGE_SIZE, 4, 0, 0, 0],
            ),
            negative_errno(libc::EFAULT)
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_read,
                [4, 0x200, 4, 0, 0, 0],
            ),
            4
        );
        let mut unconsumed = [0; 4];
        memory.read(0x200, &mut unconsumed).unwrap();
        assert_eq!(&unconsumed, b"abcd");
    }

    const READ_ZERO_BUFFER: u64 = 0x100;
    const READ_ZERO_PROTECTED: u64 = PAGE_SIZE;
    const READ_ZERO_HIGH_FD: u64 = 0x5a5a_5a5a_0000_0000;
    const READ_ZERO_ADDRESSES: [u64; 7] = [
        READ_ZERO_BUFFER,
        READ_ZERO_PROTECTED,
        0,
        1,
        3 * PAGE_SIZE,
        0x8000_0000_0000_0000,
        u64::MAX,
    ];

    include!("executor/read_zero_refusal_tests.rs");
    include!("executor/descriptor_check_order_tests.rs");

    fn read_zero_memory() -> GuestMemory {
        let mut memory = GuestMemory::new(0, 2 * PAGE_SIZE as usize).unwrap();
        for address in [READ_ZERO_BUFFER, READ_ZERO_PROTECTED] {
            memory.write(address, &[0x5a; 16]).unwrap();
        }
        memory
            .map_user_permissions(0, PAGE_SIZE, true, true)
            .unwrap();
        memory
            .map_user_permissions(PAGE_SIZE, PAGE_SIZE, false, false)
            .unwrap();
        memory.enable_user_access();
        memory
    }

    fn assert_read_zero_fixture_filesystem(file: &std::fs::File) {
        let mut filesystem = std::mem::MaybeUninit::<libc::statfs>::zeroed();
        // SAFETY: this fixture owns the descriptor and writable statfs storage.
        assert_eq!(
            unsafe { libc::fstatfs(file.as_raw_fd(), filesystem.as_mut_ptr()) },
            0
        );
        let filesystem = unsafe { filesystem.assume_init() };
        assert!(
            matches!(
                filesystem.f_type,
                libc::TMPFS_MAGIC | libc::EXT4_SUPER_MAGIC | libc::BTRFS_SUPER_MAGIC
            ),
            "zero-read native-result fixture requires a directory on tmpfs, ext4, or btrfs; filesystem type={:#x}",
            filesystem.f_type,
        );
    }

    fn assert_read_zero_canaries(memory: &GuestMemory) {
        for address in [READ_ZERO_BUFFER, READ_ZERO_PROTECTED] {
            let mut canary = [0; 16];
            memory.read_raw(address, &mut canary).unwrap();
            assert_eq!(canary, [0x5a; 16], "canary at {address:#x}");
        }
    }

    fn native_read_zero(fd: u64, address: u64) -> i64 {
        // SAFETY: the literal zero count forbids copying through this numeric
        // address, including null, unmapped, and noncanonical addresses. The
        // raw syscall also retains Linux's low-word descriptor conversion.
        let result = unsafe {
            libc::syscall(
                libc::SYS_read,
                fd,
                address as usize as *mut libc::c_void,
                0_usize,
            )
        };
        if result < 0 {
            io_error(std::io::Error::last_os_error())
        } else {
            result
        }
    }

    #[test]
    fn read_zero_count_eventfd_preserves_seed_for_translated_and_inherited_fds() {
        for inherited in [false, true] {
            // SAFETY: successful eventfd creates a new, uniquely owned fd.
            let host = unsafe { libc::eventfd(9, libc::EFD_CLOEXEC | libc::EFD_NONBLOCK) };
            assert!(host >= 0);
            let file = unsafe { std::fs::File::from_raw_fd(host) };
            let mut state = test_state(&std::env::current_dir().unwrap());
            let fd = if inherited {
                state.stdin = Some(file);
                0
            } else {
                state.files.insert(3, file);
                3
            };
            let mut memory = read_zero_memory();
            for high_word in [0, READ_ZERO_HIGH_FD] {
                for address in READ_ZERO_ADDRESSES {
                    let native = native_read_zero(high_word | host as u64, address);
                    assert_eq!(
                        native,
                        negative_errno(if address >= 0x8000_0000_0000_0000 {
                            libc::EFAULT
                        } else {
                            libc::EINVAL
                        }),
                        "native eventfd address={address:#x}"
                    );
                    assert_eq!(
                        syscall_result(
                            &mut memory,
                            &mut state,
                            libc::SYS_read,
                            [high_word | fd, address, 0, 0, 0, 0],
                        ),
                        native,
                        "eventfd inherited={inherited} fd={:#x} address={address:#x}",
                        high_word | fd
                    );
                    assert_read_zero_canaries(&memory);
                    assert_eq!(
                        syscall_result(
                            &mut memory,
                            &mut state,
                            libc::SYS_read,
                            [fd, READ_ZERO_BUFFER, 8, 0, 0, 0],
                        ),
                        8
                    );
                    assert_eq!(
                        read_guest_bytes::<8>(&ProviderMemory(&memory), READ_ZERO_BUFFER).unwrap(),
                        9_u64.to_ne_bytes()
                    );
                    assert_eq!(
                        read_guest_bytes::<8>(&ProviderMemory(&memory), READ_ZERO_BUFFER + 8)
                            .unwrap(),
                        [0x5a; 8]
                    );
                    assert_eq!(
                        syscall_result(
                            &mut memory,
                            &mut state,
                            libc::SYS_read,
                            [fd, READ_ZERO_BUFFER, 8, 0, 0, 0],
                        ),
                        negative_errno(libc::EAGAIN),
                        "following read must consume exactly the seeded counter"
                    );
                    let seed = 9_u64.to_ne_bytes();
                    // SAFETY: seed is an eight-byte host buffer; host remains owned.
                    assert_eq!(
                        unsafe { libc::write(host, seed.as_ptr().cast(), seed.len()) },
                        8
                    );
                    memory.write(READ_ZERO_BUFFER, &[0x5a; 16]).unwrap();
                }
            }
        }
    }

    #[test]
    fn read_zero_count_file_and_pipe_preserve_position_and_payload() {
        for inherited in [false, true] {
            for pipe in [false, true] {
                let (file, mut writer) = if pipe {
                    let mut fds = [-1; 2];
                    // SAFETY: fds has space for both newly created descriptors.
                    assert_eq!(
                        unsafe {
                            libc::pipe2(fds.as_mut_ptr(), libc::O_CLOEXEC | libc::O_NONBLOCK)
                        },
                        0
                    );
                    // SAFETY: each successful pipe descriptor is owned once.
                    unsafe {
                        (
                            std::fs::File::from_raw_fd(fds[0]),
                            Some(std::fs::File::from_raw_fd(fds[1])),
                        )
                    }
                } else {
                    // SAFETY: successful memfd_create returns a new owned fd.
                    let host =
                        unsafe { libc::memfd_create(c"read-zero".as_ptr(), libc::MFD_CLOEXEC) };
                    assert!(host >= 0);
                    let mut file = unsafe { std::fs::File::from_raw_fd(host) };
                    file.write_all(b"ABCDEFGH").unwrap();
                    (file, None)
                };
                let host = file.as_raw_fd();
                let mut state = test_state(&std::env::current_dir().unwrap());
                let fd = if inherited {
                    state.stdin = Some(file);
                    0
                } else {
                    state.files.insert(3, file);
                    3
                };
                let mut memory = read_zero_memory();
                for high_word in [0, READ_ZERO_HIGH_FD] {
                    for address in READ_ZERO_ADDRESSES {
                        if let Some(writer) = &mut writer {
                            writer.write_all(b"ABCDEFGH").unwrap();
                        } else {
                            // SAFETY: host is the owned seekable memfd.
                            assert_eq!(unsafe { libc::lseek(host, 3, libc::SEEK_SET) }, 3);
                        }
                        let native = native_read_zero(high_word | host as u64, address);
                        assert_eq!(
                            native,
                            if address >= 0x8000_0000_0000_0000 {
                                negative_errno(libc::EFAULT)
                            } else {
                                0
                            }
                        );
                        assert_eq!(
                            syscall_result(
                                &mut memory,
                                &mut state,
                                libc::SYS_read,
                                [high_word | fd, address, 0, 0, 0, 0],
                            ),
                            native,
                            "pipe={pipe} inherited={inherited} fd={:#x} address={address:#x}",
                            high_word | fd
                        );
                        assert_read_zero_canaries(&memory);
                        if !pipe {
                            assert_eq!(unsafe { libc::lseek(host, 0, libc::SEEK_CUR) }, 3);
                        }
                        let expected = if pipe {
                            b"ABCDEFGH".as_slice()
                        } else {
                            b"DEFGH".as_slice()
                        };
                        assert_eq!(
                            syscall_result(
                                &mut memory,
                                &mut state,
                                libc::SYS_read,
                                [fd, READ_ZERO_BUFFER, 8, 0, 0, 0],
                            ),
                            expected.len() as i64
                        );
                        let mut actual = [0x5a; 16];
                        actual[..expected.len()].copy_from_slice(expected);
                        assert_eq!(
                            read_guest_bytes::<16>(&ProviderMemory(&memory), READ_ZERO_BUFFER)
                                .unwrap(),
                            actual
                        );
                        if !pipe {
                            assert_eq!(unsafe { libc::lseek(host, 0, libc::SEEK_CUR) }, 8);
                        }
                        assert_eq!(
                            syscall_result(
                                &mut memory,
                                &mut state,
                                libc::SYS_read,
                                [fd, READ_ZERO_BUFFER, 8, 0, 0, 0],
                            ),
                            if pipe {
                                negative_errno(libc::EAGAIN)
                            } else {
                                0
                            }
                        );
                        memory.write(READ_ZERO_BUFFER, &[0x5a; 16]).unwrap();
                    }
                }
            }
        }
    }

    #[test]
    fn read_zero_count_descriptor_errors_match_native_ordering() {
        for inherited in [false, true] {
            for flags in [
                libc::O_RDONLY | libc::O_DIRECTORY,
                libc::O_PATH,
                libc::O_WRONLY,
            ] {
                let path = if flags == libc::O_WRONLY {
                    c"/dev/null"
                } else {
                    c"."
                };
                // SAFETY: path is terminated and successful open returns a new fd.
                let host = unsafe { libc::open(path.as_ptr(), flags | libc::O_CLOEXEC) };
                assert!(host >= 0);
                let file = unsafe { std::fs::File::from_raw_fd(host) };
                if flags & libc::O_DIRECTORY != 0 {
                    assert_read_zero_fixture_filesystem(&file);
                }
                let mut state = test_state(&std::env::current_dir().unwrap());
                let fd = if inherited {
                    state.stdin = Some(file);
                    0
                } else {
                    state.files.insert(3, file);
                    3
                };
                let mut memory = read_zero_memory();
                for high_word in [0, READ_ZERO_HIGH_FD] {
                    for address in READ_ZERO_ADDRESSES {
                        let native = native_read_zero(high_word | host as u64, address);
                        assert!(native < 0);
                        assert_eq!(
                            syscall_result(
                                &mut memory,
                                &mut state,
                                libc::SYS_read,
                                [high_word | fd, address, 0, 0, 0, 0],
                            ),
                            native,
                            "flags={flags:#x} inherited={inherited} address={address:#x}"
                        );
                        assert_read_zero_canaries(&memory);
                    }
                }
            }
        }
        let mut state = test_state(&std::env::current_dir().unwrap());
        let mut memory = read_zero_memory();
        for fd in [u64::MAX, READ_ZERO_HIGH_FD | 0x8000_0003] {
            for address in READ_ZERO_ADDRESSES {
                assert_eq!(native_read_zero(fd, address), negative_errno(libc::EBADF));
                assert_eq!(
                    syscall_result(
                        &mut memory,
                        &mut state,
                        libc::SYS_read,
                        [fd, address, 0, 0, 0, 0]
                    ),
                    negative_errno(libc::EBADF)
                );
                assert_read_zero_canaries(&memory);
            }
        }
    }

    #[test]
    fn read_zero_count_keeps_private_inherited_and_rebound_descriptors_distinct() {
        let mut state = test_state(&std::env::current_dir().unwrap());
        let mut memory = read_zero_memory();
        // SAFETY: each successful creation transfers one new descriptor to File.
        let event = unsafe { libc::eventfd(9, libc::EFD_CLOEXEC | libc::EFD_NONBLOCK) };
        assert!(event > 2);
        let mut private = unsafe { std::fs::File::from_raw_fd(event) };
        let regular =
            unsafe { libc::memfd_create(c"read-zero-routing".as_ptr(), libc::MFD_CLOEXEC) };
        assert!(regular > 2);
        let mut regular = unsafe { std::fs::File::from_raw_fd(regular) };
        regular.write_all(b"ABCDEFGH").unwrap();
        regular.seek(SeekFrom::Start(3)).unwrap();
        let read = |memory: &mut GuestMemory, state: &mut LoadedStaticElf, fd, address, count| {
            syscall_result(memory, state, libc::SYS_read, [fd, address, count, 0, 0, 0])
        };
        let addresses = [READ_ZERO_BUFFER, READ_ZERO_PROTECTED, u64::MAX];
        assert!(!state.files.contains_key(&event));
        for high in [0, READ_ZERO_HIGH_FD] {
            for address in addresses {
                let fd = high | event as u64;
                assert_eq!(
                    native_read_zero(fd, address),
                    negative_errno(if address == u64::MAX {
                        libc::EFAULT
                    } else {
                        libc::EINVAL
                    })
                );
                assert_eq!(
                    read(&mut memory, &mut state, fd, address, 0),
                    negative_errno(libc::EBADF)
                );
                assert_read_zero_canaries(&memory);
            }
        }

        // Distinct controlled results check owned-stdin routing without probing
        // the ambient process stdin, whose endpoint behavior is unknown.
        let mut controlled_results = Vec::new();
        for (file, expected) in [(&private, negative_errno(libc::EINVAL)), (&regular, 0)] {
            state.stdin = Some(file.try_clone().unwrap());
            assert_ne!(state.stdin.as_ref().unwrap().as_raw_fd(), 0);
            assert_eq!(
                native_read_zero(file.as_raw_fd() as u64, READ_ZERO_BUFFER),
                expected
            );
            let observed = read(&mut memory, &mut state, 0, READ_ZERO_BUFFER, 0);
            assert_eq!(observed, expected);
            controlled_results.push(observed);
            for high in [0, READ_ZERO_HIGH_FD] {
                for address in addresses {
                    assert_eq!(
                        read(&mut memory, &mut state, high, address, 0),
                        native_read_zero(high | file.as_raw_fd() as u64, address)
                    );
                    assert_read_zero_canaries(&memory);
                }
            }
        }
        assert_ne!(controlled_results[0], controlled_results[1]);
        assert_eq!(regular.stream_position().unwrap(), 3);

        state.files.insert(3, private.try_clone().unwrap());
        for target in 0..=2 {
            assert_eq!(
                syscall_result(
                    &mut memory,
                    &mut state,
                    libc::SYS_dup2,
                    [
                        READ_ZERO_HIGH_FD | 3,
                        READ_ZERO_HIGH_FD | target,
                        0,
                        0,
                        0,
                        0
                    ]
                ),
                target as i64
            );
            assert!(state.closed_standard_fds.contains(&(target as i32)));
            assert!(state.files.contains_key(&(target as i32)));
            for high in [0, READ_ZERO_HIGH_FD] {
                for address in addresses {
                    assert_eq!(
                        read(&mut memory, &mut state, high | target, address, 0),
                        native_read_zero(high | event as u64, address)
                    );
                    assert_read_zero_canaries(&memory);
                }
            }
            assert_eq!(
                read(&mut memory, &mut state, target, READ_ZERO_BUFFER, 8),
                8
            );
            assert_eq!(
                read_guest_bytes::<8>(&ProviderMemory(&memory), READ_ZERO_BUFFER).unwrap(),
                9_u64.to_ne_bytes()
            );
            assert_eq!(
                read_guest_bytes::<8>(&ProviderMemory(&memory), READ_ZERO_BUFFER + 8).unwrap(),
                [0x5a; 8]
            );
            assert_eq!(
                read(&mut memory, &mut state, target, READ_ZERO_BUFFER, 8),
                negative_errno(libc::EAGAIN)
            );
            private.write_all(&9_u64.to_ne_bytes()).unwrap();
            memory.write(READ_ZERO_BUFFER, &[0x5a; 16]).unwrap();
        }
        assert_eq!(
            regular.stream_position().unwrap(),
            3,
            "rebound stdin must leave the original owned stdin untouched"
        );
        assert_read_zero_canaries(&memory);
    }

    #[test]
    fn read_zero_count_proc_keeps_synthetic_routing_and_position() {
        let path = "/proc/self/status";
        let mut state = test_state(&std::env::current_dir().unwrap());
        let mut memory = read_zero_memory();
        let fd = open_readonly(&mut memory, &mut state, path);
        assert!(fd >= 0, "open {path}: {fd}");
        assert!(state.proc_files.contains_key(&(fd as i32)));
        // Process status is a live seq description with an empty metadata
        // carrier. Its independent literal prefix must come from the
        // description, never from that private host file.
        assert!(state.fdinfo_files.contains_key(&(fd as i32)));
        assert_eq!(state.files[&(fd as i32)].metadata().unwrap().len(), 0);
        let expected = b"Name:\ttest\nUmask".to_vec();
        memory.write(READ_ZERO_BUFFER, &[0x5a; 16]).unwrap();
        for address in READ_ZERO_ADDRESSES {
            // Live process seq reads admit a zero-length userspace interval
            // without touching a page, like the fdinfo control. The route
            // must preserve position and all canaries.
            let expected_result = if address >= 0x8000_0000_0000_0000 {
                negative_errno(libc::EFAULT)
            } else {
                0
            };
            assert_eq!(
                syscall_result(
                    &mut memory,
                    &mut state,
                    libc::SYS_read,
                    [READ_ZERO_HIGH_FD | fd as u64, address, 0, 0, 0, 0],
                ),
                expected_result,
                "synthetic {path} address={address:#x}"
            );
            assert_read_zero_canaries(&memory);
            assert_eq!(
                syscall_result(
                    &mut memory,
                    &mut state,
                    libc::SYS_lseek,
                    [fd as u64, 0, libc::SEEK_CUR as u64, 0, 0, 0],
                ),
                0
            );
        }
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_read,
                [fd as u64, READ_ZERO_BUFFER, 16, 0, 0, 0],
            ),
            16
        );
        assert_eq!(
            read_guest_bytes::<16>(&ProviderMemory(&memory), READ_ZERO_BUFFER)
                .unwrap()
                .as_slice(),
            expected
        );
    }

    #[test]
    fn read_zero_count_fdinfo_preserves_live_sequence_instead_of_reading_carrier() {
        let mut f = FdinfoFixture::new(false);
        f.memory = read_zero_memory();
        let target = f.open("a", libc::O_RDWR);
        assert_eq!(f.seek(target, 23, libc::SEEK_SET), 23);
        let info = f.info(target);
        f.memory.write(READ_ZERO_BUFFER, &[0x5a; 16]).unwrap();
        for address in READ_ZERO_ADDRESSES {
            assert_eq!(
                f.call(
                    libc::SYS_read,
                    [READ_ZERO_HIGH_FD | info as u64, address, 0, 0, 0, 0],
                ),
                if address >= 0x8000_0000_0000_0000 {
                    negative_errno(libc::EFAULT)
                } else {
                    0
                },
                "fdinfo address={address:#x}"
            );
            assert_read_zero_canaries(&f.memory);
            assert_eq!(f.seek(info, 0, libc::SEEK_CUR), 0);
            assert_eq!(f.seek(target, 0, libc::SEEK_CUR), 23);
        }
        assert_eq!(f.seek(target, 37, libc::SEEK_SET), 37);
        assert_eq!(
            f.call(libc::SYS_read, [info as u64, READ_ZERO_BUFFER, 8, 0, 0, 0]),
            8
        );
        assert_eq!(
            read_guest_bytes::<8>(&ProviderMemory(&f.memory), READ_ZERO_BUFFER).unwrap(),
            *b"pos:\t37\n"
        );
        assert_eq!(
            read_guest_bytes::<8>(&ProviderMemory(&f.memory), READ_ZERO_BUFFER + 8).unwrap(),
            [0x5a; 8]
        );
        assert_eq!(f.seek(info, 0, libc::SEEK_CUR), 8);
    }

    #[test]
    fn read_zero_count_signalfd_preserves_pending_record_and_private_carrier() {
        const MASK: u64 = 0x200;
        const OUTPUT: u64 = 0x300;
        let mut state = test_state(&std::env::current_dir().unwrap());
        let mut memory = read_zero_memory();
        test_block_signal(&mut state, libc::SIGUSR1);
        memory.write(MASK, &test_blocked_mask(&state)).unwrap();
        let fd = syscall_result(
            &mut memory,
            &mut state,
            libc::SYS_signalfd4,
            [
                u64::MAX,
                MASK,
                KERNEL_SIGSET_SIZE as u64,
                libc::SFD_NONBLOCK as u64,
                0,
                0,
            ],
        );
        assert!(fd >= 0);
        let pid = state.pid;
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_kill,
                [pid as u64, libc::SIGUSR1 as u64, 0, 0, 0, 0]
            ),
            0
        );
        // The live carrier must stay readable until a complete virtual record
        // is consumed. A zero-count read must neither dequeue nor drain it.
        let mut carrier = libc::pollfd {
            fd: state.files[&(fd as i32)].as_raw_fd(),
            events: libc::POLLIN,
            revents: 0,
        };
        // Preserve virtual EINVAL even at the two high/noncanonical addresses,
        // where native signalfd currently returns EFAULT. Those cases also
        // distinguish this route from an accidental read of its eventfd carrier.
        for address in READ_ZERO_ADDRESSES {
            assert_eq!(
                syscall_result(
                    &mut memory,
                    &mut state,
                    libc::SYS_read,
                    [READ_ZERO_HIGH_FD | fd as u64, address, 0, 0, 0, 0],
                ),
                negative_errno(libc::EINVAL),
                "virtual signalfd address={address:#x}"
            );
            assert_read_zero_canaries(&memory);
            // SAFETY: carrier is a live one-element pollfd array, timeout is zero.
            assert_eq!(unsafe { libc::poll(&mut carrier, 1, 0) }, 1);
            assert_eq!(carrier.revents, libc::POLLIN);
        }
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_read,
                [fd as u64, OUTPUT, SIGNALFD_RECORD_SIZE as u64, 0, 0, 0],
            ),
            SIGNALFD_RECORD_SIZE as i64
        );
        let info: libc::signalfd_siginfo = read_struct(&memory, OUTPUT);
        assert_eq!(info.ssi_signo, libc::SIGUSR1 as u32);
        assert_eq!(info.ssi_pid, pid as u32);
        assert_eq!(unsafe { libc::poll(&mut carrier, 1, 0) }, 0);
        assert_eq!(carrier.revents, 0);
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_read,
                [fd as u64, OUTPUT, SIGNALFD_RECORD_SIZE as u64, 0, 0, 0],
            ),
            negative_errno(libc::EAGAIN)
        );
        assert_read_zero_canaries(&memory);
    }

    fn read_zero_terminal_context(
        memory: &GuestMemory,
        registry: std::sync::Arc<crate::terminal_read::ReadRegistry>,
    ) -> crate::terminal_read::ReadContext {
        crate::terminal_read::ReadContext::new(
            registry,
            false,
            crate::entry::driver::EntryDriverWatch::for_memory(memory),
            None,
            std::sync::Arc::new(crate::failure::tool_panics::ToolPanics::default()),
            false,
        )
    }

    fn read_zero_task() -> reverie::SignalTaskIdentity {
        reverie::SignalTaskIdentity {
            process: reverie::SignalProcessId {
                tgid: reverie::Pid::from_raw(11),
                generation: 12,
            },
            tid: reverie::Pid::from_raw(11),
            task_generation: 14,
        }
    }

    #[test]
    fn read_zero_count_numeric_address_policy_preserves_endpoint_ordering() {
        // These are literal expectations for the existing four-level guest
        // model. A host may admit the higher addresses, so its raw result is
        // deliberately not the oracle for these guest calls. Even the valid
        // ceiling is outside this fixture's GuestMemory and remains unmapped.
        const ADDRESSES: [(u64, bool); 5] = [
            (0x0000_7fff_ffff_f000, true),
            (0x0000_7fff_ffff_f001, false),
            (0x0000_8000_0000_0000, false),
            (0x0080_0000_0000_0000, false),
            (u64::MAX, false),
        ];
        for inherited in [false, true] {
            for with_context in [false, true] {
                for kind in [
                    "file",
                    "eventfd",
                    "write-only",
                    "opath",
                    "directory",
                    "missing",
                ] {
                    let file = match kind {
                        "file" => {
                            // SAFETY: successful memfd_create returns one owned fd.
                            let raw = unsafe {
                                libc::memfd_create(c"read-zero-limit".as_ptr(), libc::MFD_CLOEXEC)
                            };
                            assert!(raw >= 0);
                            let mut file = unsafe { std::fs::File::from_raw_fd(raw) };
                            file.write_all(b"ABCDEFGH").unwrap();
                            assert_eq!(unsafe { libc::lseek(raw, 3, libc::SEEK_SET) }, 3);
                            Some(file)
                        }
                        "eventfd" => {
                            // SAFETY: successful eventfd returns one owned fd.
                            let raw =
                                unsafe { libc::eventfd(9, libc::EFD_CLOEXEC | libc::EFD_NONBLOCK) };
                            assert!(raw >= 0);
                            Some(unsafe { std::fs::File::from_raw_fd(raw) })
                        }
                        "write-only" => Some(
                            std::fs::OpenOptions::new()
                                .write(true)
                                .open("/dev/null")
                                .unwrap(),
                        ),
                        "opath" => {
                            // SAFETY: the literal path is terminated; a successful
                            // open returns a new fd owned by this fixture.
                            let raw = unsafe {
                                libc::open(c"/dev/null".as_ptr(), libc::O_PATH | libc::O_CLOEXEC)
                            };
                            assert!(raw >= 0);
                            Some(unsafe { std::fs::File::from_raw_fd(raw) })
                        }
                        "directory" => {
                            let file = std::fs::File::open(".").unwrap();
                            assert_read_zero_fixture_filesystem(&file);
                            Some(file)
                        }
                        "missing" => None,
                        _ => unreachable!(),
                    };
                    let raw = file.as_ref().map(AsRawFd::as_raw_fd);
                    let mut state = test_state(&std::env::current_dir().unwrap());
                    let fd = if inherited {
                        state.stdin = file;
                        0
                    } else {
                        if let Some(file) = file {
                            state.files.insert(3, file);
                        }
                        3
                    };
                    let entry_ids = state.fd_entry_ids.clone();
                    let mut memory = read_zero_memory();
                    let registry =
                        std::sync::Arc::new(crate::terminal_read::ReadRegistry::default());
                    for high_word in [0, READ_ZERO_HIGH_FD] {
                        for (address, valid) in ADDRESSES {
                            // Descriptor errors precede access_ok. Eventfd and
                            // directory errors come from the later endpoint call.
                            let expected = match kind {
                                "write-only" | "opath" | "missing" => negative_errno(libc::EBADF),
                                _ if !valid => negative_errno(libc::EFAULT),
                                "file" => 0,
                                "eventfd" => negative_errno(libc::EINVAL),
                                "directory" => negative_errno(libc::EISDIR),
                                _ => unreachable!(),
                            };
                            let mut context = read_zero_terminal_context(&memory, registry.clone());
                            let request = SyscallRequest::new(
                                libc::SYS_read as u64,
                                [high_word | fd, address, 0, 0, 0, 0],
                            );
                            let action = execute_basic_syscall_with_read_context(
                                &mut memory,
                                &mut state,
                                &request,
                                None,
                                None,
                                with_context.then_some((&mut context, read_zero_task())),
                            );
                            match action {
                                SyscallAction::Continue {
                                    result,
                                    segment: None,
                                } => assert_eq!(
                                    result,
                                    expected,
                                    "kind={kind} inherited={inherited} context={with_context} fd={:#x} address={address:#x}",
                                    high_word | fd,
                                ),
                                SyscallAction::Continue { .. } => {
                                    panic!("zero read changed segment")
                                }
                                SyscallAction::Exit(status) => {
                                    panic!("zero read exited: {status:?}")
                                }
                                SyscallAction::Failure(error) => {
                                    panic!("zero read failed: {error}")
                                }
                            }
                            let retained = if inherited {
                                state.stdin.as_ref()
                            } else {
                                state.files.get(&3)
                            };
                            assert_eq!(retained.map(AsRawFd::as_raw_fd), raw);
                            assert!(same_entries(&state.fd_entry_ids, &entry_ids));
                            assert_read_zero_canaries(&memory);
                            registry.teardown_result().unwrap();
                            registry.rearm_after_exec();
                        }
                    }
                    if kind == "file" {
                        let raw = raw.unwrap();
                        assert_eq!(unsafe { libc::lseek(raw, 0, libc::SEEK_CUR) }, 3);
                        let mut bytes = [0_u8; 8];
                        // SAFETY: bytes is writable for the requested eight bytes.
                        assert_eq!(
                            unsafe { libc::pread(raw, bytes.as_mut_ptr().cast(), 8, 0) },
                            8
                        );
                        assert_eq!(&bytes, b"ABCDEFGH");
                        assert_eq!(unsafe { libc::lseek(raw, 0, libc::SEEK_CUR) }, 3);
                    } else if kind == "eventfd" {
                        let raw = raw.unwrap();
                        let mut value = 0_u64;
                        // SAFETY: value is writable for the requested eight bytes.
                        assert_eq!(
                            unsafe { libc::read(raw, (&mut value as *mut u64).cast(), 8) },
                            8
                        );
                        assert_eq!(value, 9);
                        assert_eq!(
                            unsafe { libc::read(raw, (&mut value as *mut u64).cast(), 8) },
                            -1
                        );
                        assert_eq!(
                            std::io::Error::last_os_error().raw_os_error(),
                            Some(libc::EAGAIN)
                        );
                    }
                    assert_read_zero_canaries(&memory);
                }
            }
        }
    }

    #[test]
    fn read_zero_count_terminal_helper_preserves_address_counter_and_endpoint() {
        // A seeded eventfd distinguishes endpoint EINVAL from numeric-address
        // EFAULT. It also detects any accidental nonzero read or carrier swap.
        let raw = unsafe { libc::eventfd(9, libc::EFD_CLOEXEC | libc::EFD_NONBLOCK) };
        assert!(raw >= 0);
        let file = unsafe { std::fs::File::from_raw_fd(raw) };
        let mut state = test_state(&std::env::current_dir().unwrap());
        state.stdin = Some(file);
        let mut memory = read_zero_memory();
        let registry = std::sync::Arc::new(crate::terminal_read::ReadRegistry::default());
        for high_word in [0, READ_ZERO_HIGH_FD] {
            for address in READ_ZERO_ADDRESSES {
                let expected = native_read_zero(high_word | raw as u64, address);
                assert_eq!(
                    expected,
                    negative_errno(if address >= 0x8000_0000_0000_0000 {
                        libc::EFAULT
                    } else {
                        libc::EINVAL
                    })
                );
                let mut context = read_zero_terminal_context(&memory, registry.clone());
                let request =
                    SyscallRequest::new(libc::SYS_read as u64, [high_word, address, 0, 0, 0, 0]);
                let result = execute_basic_syscall_with_read_context(
                    &mut memory,
                    &mut state,
                    &request,
                    None,
                    None,
                    Some((&mut context, read_zero_task())),
                );
                match result {
                    SyscallAction::Continue {
                        result,
                        segment: None,
                    } => assert_eq!(result, expected),
                    SyscallAction::Continue { .. } => panic!("zero read changed segment"),
                    SyscallAction::Exit(status) => panic!("zero read exited: {status:?}"),
                    SyscallAction::Failure(error) => panic!("zero read failed: {error}"),
                }
                assert_eq!(state.stdin.as_ref().unwrap().as_raw_fd(), raw);
                assert_read_zero_canaries(&memory);
                registry.teardown_result().unwrap();
                // This existing API asserts that no helper remains registered.
                registry.rearm_after_exec();
            }
        }
        let mut value = 0_u64;
        assert_eq!(
            unsafe { libc::read(raw, (&mut value as *mut u64).cast(), 8) },
            8
        );
        assert_eq!(value, 9);
        assert_eq!(
            unsafe { libc::read(raw, (&mut value as *mut u64).cast(), 8) },
            -1
        );
        assert_eq!(
            std::io::Error::last_os_error().raw_os_error(),
            Some(libc::EAGAIN)
        );
        assert_read_zero_canaries(&memory);
    }

    #[test]
    fn read_zero_count_terminal_cancellation_keeps_original_endpoint() {
        for address in [READ_ZERO_BUFFER, u64::MAX] {
            let raw = unsafe { libc::eventfd(9, libc::EFD_CLOEXEC | libc::EFD_NONBLOCK) };
            assert!(raw >= 0);
            let file = unsafe { std::fs::File::from_raw_fd(raw) };
            let mut state = test_state(&std::env::current_dir().unwrap());
            state.stdin = Some(file);
            let mut memory = read_zero_memory();
            let registry = std::sync::Arc::new(crate::terminal_read::ReadRegistry::default());
            registry.request_exit_group(reverie::ExitStatus::Exited(37));
            let mut context = read_zero_terminal_context(&memory, registry.clone());
            let request = SyscallRequest::new(
                libc::SYS_read as u64,
                [READ_ZERO_HIGH_FD, address, 0, 0, 0, 0],
            );
            let action = execute_basic_syscall_with_read_context(
                &mut memory,
                &mut state,
                &request,
                None,
                None,
                Some((&mut context, read_zero_task())),
            );
            match action {
                SyscallAction::Failure(error) => assert!(
                    matches!(error, crate::Error::TerminalReadCancelled),
                    "{error}"
                ),
                SyscallAction::Continue { result, .. } => {
                    panic!("terminal zero read returned {result}")
                }
                SyscallAction::Exit(status) => panic!("terminal zero read exited: {status:?}"),
            }
            assert_eq!(state.stdin.as_ref().unwrap().as_raw_fd(), raw);
            assert_read_zero_canaries(&memory);
            registry.teardown_result().unwrap();
            registry.rearm_after_exec();
            let mut value = 0_u64;
            assert_eq!(
                unsafe { libc::read(raw, (&mut value as *mut u64).cast(), 8) },
                8
            );
            assert_eq!(value, 9);
        }
    }

    #[test]
    fn pread64_negative_offset_precedes_fd_count_and_buffer_checks() {
        const BUFFER: u64 = 0x100;
        const PROTECTED: u64 = PAGE_SIZE;
        let mut memory = GuestMemory::new(0, 2 * PAGE_SIZE as usize).unwrap();
        memory.write(BUFFER, &[0x5a; 8]).unwrap();
        memory.write(PROTECTED, &[0x5a; 8]).unwrap();
        memory.map_user_range(0, PAGE_SIZE, false).unwrap();
        memory.map_user_range(PROTECTED, PAGE_SIZE, true).unwrap();
        memory.enable_user_access();

        // SAFETY: successful memfd_create transfers a new descriptor to File.
        let fd =
            unsafe { libc::memfd_create(c"pread-offset-precedence".as_ptr(), libc::MFD_CLOEXEC) };
        assert!(fd >= 0);
        // SAFETY: fd is a valid, newly created descriptor owned by this test.
        let mut file = unsafe { std::fs::File::from_raw_fd(fd) };
        file.write_all(b"abcdefgh").unwrap();
        file.seek(SeekFrom::Start(3)).unwrap();
        let mut state = test_state(&std::env::current_dir().unwrap());
        state.files.insert(3, file);

        let cases = [
            (3, BUFFER, 0, 0),
            (3, PROTECTED, 7, negative_errno(libc::EFAULT)),
            (u64::MAX, PROTECTED, 7, negative_errno(libc::EBADF)),
        ];
        for offset in [-1_i64, i64::MIN, 0] {
            for (fd, address, count, valid_offset_result) in cases {
                let expected = if offset == 0 {
                    valid_offset_result
                } else {
                    negative_errno(libc::EINVAL)
                };
                assert_eq!(
                    syscall_result(
                        &mut memory,
                        &mut state,
                        libc::SYS_pread64,
                        [fd, address, count, offset as u64, 0, 0],
                    ),
                    expected,
                    "fd={fd:#x}, address={address:#x}, count={count}, offset={offset}"
                );
                // Inspect canaries without relaxing the guest's protection.
                for address in [BUFFER, PROTECTED] {
                    let mut canary = [0; 8];
                    memory.read_raw(address, &mut canary).unwrap();
                    assert_eq!(canary, [0x5a; 8], "pread64 changed canaries");
                }
                assert_eq!(
                    state.files.get_mut(&3).unwrap().stream_position().unwrap(),
                    3
                );
            }
        }

        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_pread64,
                [3, BUFFER, 2, 1, 0, 0],
            ),
            2
        );
        let mut bytes = [0; 8];
        memory.read(BUFFER, &mut bytes).unwrap();
        assert_eq!(&bytes, b"bcZZZZZZ");
        assert_eq!(
            state.files.get_mut(&3).unwrap().stream_position().unwrap(),
            3
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_read,
                [3, BUFFER, 2, 0, 0, 0],
            ),
            2
        );
        memory.read(BUFFER, &mut bytes).unwrap();
        assert_eq!(&bytes, b"deZZZZZZ");
        assert_eq!(
            state.files.get_mut(&3).unwrap().stream_position().unwrap(),
            5
        );
    }

    #[test]
    fn read_and_pread64_consume_low_descriptor_words() {
        const HIGH_WORD: u64 = 0x5a5a_5a5a_0000_0000;
        const BIT31_LOW_WORD: u64 = HIGH_WORD | (1 << 31);
        const READ_ADDRESS: u64 = 0x100;
        const PREAD_ADDRESS: u64 = 0x200;
        const NEXT_READ_ADDRESS: u64 = 0x300;

        let root = TestDir::new();
        let path = root.0.join("input");
        std::fs::write(&path, b"abcdef").unwrap();
        let mut state = test_state(&root.0);
        state.files.insert(3, std::fs::File::open(&path).unwrap());
        state.files.insert(4, std::fs::File::open(&path).unwrap());
        let mut memory = GuestMemory::new(0, PAGE_SIZE as usize).unwrap();

        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_read,
                [HIGH_WORD | 3, u64::MAX, 1, 0, 0, 0],
            ),
            negative_errno(libc::EFAULT),
            "buffer validation follows low-word descriptor decoding"
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_read,
                [HIGH_WORD | 3, READ_ADDRESS, 2, 0, 0, 0],
            ),
            2
        );
        let mut bytes = [0; 2];
        memory.read(READ_ADDRESS, &mut bytes).unwrap();
        assert_eq!(&bytes, b"ab");
        assert_eq!(
            state.files.get_mut(&3).unwrap().stream_position().unwrap(),
            2
        );

        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_pread64,
                [HIGH_WORD | 4, PREAD_ADDRESS, 2, 2, 0, 0],
            ),
            2
        );
        memory.read(PREAD_ADDRESS, &mut bytes).unwrap();
        assert_eq!(&bytes, b"cd");
        assert_eq!(
            state.files.get_mut(&4).unwrap().stream_position().unwrap(),
            0,
            "pread64 must not change the open-file position"
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_pread64,
                [HIGH_WORD | 4, u64::MAX, 1, 0, 0, 0],
            ),
            negative_errno(libc::EFAULT),
            "buffer validation follows low-word descriptor decoding"
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_pread64,
                [HIGH_WORD | 4, PREAD_ADDRESS, 1, u64::MAX, 0, 0],
            ),
            negative_errno(libc::EINVAL),
            "negative offsets remain invalid with high descriptor bits set"
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_read,
                [HIGH_WORD | 4, NEXT_READ_ADDRESS, 2, 0, 0, 0],
            ),
            2
        );
        memory.read(NEXT_READ_ADDRESS, &mut bytes).unwrap();
        assert_eq!(&bytes, b"ab", "pread64 and failed reads preserve position");

        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_read,
                [BIT31_LOW_WORD | 3, u64::MAX, 1, 0, 0, 0],
            ),
            negative_errno(libc::EBADF),
            "invalid low descriptor word precedes a bad read buffer"
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_pread64,
                [BIT31_LOW_WORD | 3, u64::MAX, 1, 0, 0, 0],
            ),
            negative_errno(libc::EBADF),
            "invalid low descriptor word precedes a bad pread64 buffer"
        );
    }

    #[test]
    fn inherited_special_stdin_matches_linux_read_precedence() {
        let root = TestDir::new();
        let mut state = test_state(&root.0);
        let mut memory = GuestMemory::new(0, PAGE_SIZE as usize).unwrap();

        let directory = std::fs::File::open(&root.0).unwrap();
        assert_read_zero_fixture_filesystem(&directory);
        state.stdin = Some(directory);
        for (address, length, expected) in [
            (u64::MAX, 1, negative_errno(libc::EFAULT)),
            (0x100, 1, negative_errno(libc::EISDIR)),
            (u64::MAX, 0, negative_errno(libc::EFAULT)),
        ] {
            assert_eq!(
                syscall_result(
                    &mut memory,
                    &mut state,
                    libc::SYS_read,
                    [libc::STDIN_FILENO as u64, address, length, 0, 0, 0],
                ),
                expected
            );
        }

        // SAFETY: successful descriptor creation transfers ownership to File.
        let epoll = unsafe { libc::epoll_create1(libc::EPOLL_CLOEXEC) };
        assert!(epoll >= 0);
        state.stdin = Some(unsafe { std::fs::File::from_raw_fd(epoll) });
        for length in [0, 1] {
            assert_eq!(
                syscall_result(
                    &mut memory,
                    &mut state,
                    libc::SYS_read,
                    [libc::STDIN_FILENO as u64, u64::MAX, length, 0, 0, 0],
                ),
                negative_errno(libc::EINVAL)
            );
        }

        // SAFETY: pidfd_open either returns a new descriptor or a negative error.
        let pidfd = unsafe { libc::syscall(libc::SYS_pidfd_open, libc::getpid(), 0) as i32 };
        if pidfd >= 0 {
            // SAFETY: successful pidfd_open transfers descriptor ownership to File.
            state.stdin = Some(unsafe { std::fs::File::from_raw_fd(pidfd) });
            assert_eq!(
                syscall_result(
                    &mut memory,
                    &mut state,
                    libc::SYS_read,
                    [libc::STDIN_FILENO as u64, u64::MAX, 1, 0, 0, 0],
                ),
                negative_errno(libc::EINVAL)
            );
        }

        // SAFETY: successful descriptor creation transfers ownership to File.
        let event = unsafe { libc::eventfd(0, libc::EFD_CLOEXEC) };
        assert!(event >= 0);
        state.stdin = Some(unsafe { std::fs::File::from_raw_fd(event) });
        for (address, length, expected) in [
            (u64::MAX, 1, negative_errno(libc::EFAULT)),
            (0x100, 1, negative_errno(libc::EINVAL)),
            (u64::MAX, 0, negative_errno(libc::EFAULT)),
        ] {
            assert_eq!(
                syscall_result(
                    &mut memory,
                    &mut state,
                    libc::SYS_read,
                    [libc::STDIN_FILENO as u64, address, length, 0, 0, 0],
                ),
                expected
            );
        }
    }

    #[test]
    fn pidfd_open_self_is_cloexec_and_not_ready() {
        const POLL_FD: u64 = 0x100;

        let root = TestDir::new();
        let mut state = test_state(&root.0);
        let pid = state.pid;
        let mut memory = GuestMemory::new(0, PAGE_SIZE as usize).unwrap();
        let pidfd = syscall_result(
            &mut memory,
            &mut state,
            libc::SYS_pidfd_open,
            [pid as u64, 0, 0, 0, 0, 0],
        );
        assert_eq!(pidfd, 3);
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_fcntl,
                [pidfd as u64, libc::F_GETFD as u64, 0, 0, 0, 0],
            ),
            i64::from(libc::FD_CLOEXEC)
        );

        let poll_fd = libc::pollfd {
            fd: pidfd as libc::c_int,
            events: libc::POLLIN,
            revents: 0,
        };
        assert_eq!(
            write_struct(&mut ProviderMemory(&memory), POLL_FD, &poll_fd),
            0
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_poll,
                [POLL_FD, 1, 0, 0, 0, 0],
            ),
            0
        );
        let poll_fd: libc::pollfd = read_struct(&memory, POLL_FD);
        assert_eq!(poll_fd.revents, 0);

        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_pidfd_open,
                [pid as u64, 1, 0, 0, 0, 0],
            ),
            negative_errno(libc::EINVAL)
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_pidfd_open,
                [(pid + 1) as u64, 0, 0, 0, 0, 0],
            ),
            negative_errno(libc::ESRCH)
        );
    }

    #[test]
    fn timerfd_round_trips_flags_and_expiration() {
        const TIMER: u64 = 0x100;
        const CURRENT: u64 = 0x140;
        const POLL_FD: u64 = 0x180;
        const EXPIRATIONS: u64 = 0x1c0;

        let root = TestDir::new();
        let mut state = test_state(&root.0);
        let mut memory = GuestMemory::new(0, PAGE_SIZE as usize).unwrap();
        let timerfd = syscall_result(
            &mut memory,
            &mut state,
            libc::SYS_timerfd_create,
            [
                libc::CLOCK_MONOTONIC as u64,
                (libc::TFD_CLOEXEC | libc::TFD_NONBLOCK) as u64,
                0,
                0,
                0,
                0,
            ],
        );
        assert_eq!(timerfd, 3);
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_fcntl,
                [timerfd as u64, libc::F_GETFD as u64, 0, 0, 0, 0],
            ),
            i64::from(libc::FD_CLOEXEC)
        );
        assert_ne!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_fcntl,
                [timerfd as u64, libc::F_GETFL as u64, 0, 0, 0, 0],
            ) & i64::from(libc::O_NONBLOCK),
            0
        );

        let timer = libc::itimerspec {
            it_interval: libc::timespec {
                tv_sec: 0,
                tv_nsec: 0,
            },
            // One nanosecond after boot is always in the past for the host
            // monotonic clock, so an absolute one-shot becomes ready now.
            it_value: libc::timespec {
                tv_sec: 0,
                tv_nsec: 1,
            },
        };
        assert_eq!(write_struct(&mut ProviderMemory(&memory), TIMER, &timer), 0);
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_timerfd_settime,
                [
                    timerfd as u64,
                    libc::TFD_TIMER_ABSTIME as u64,
                    TIMER,
                    0,
                    0,
                    0,
                ],
            ),
            0
        );

        let poll_fd = libc::pollfd {
            fd: timerfd as libc::c_int,
            events: libc::POLLIN,
            revents: 0,
        };
        assert_eq!(
            write_struct(&mut ProviderMemory(&memory), POLL_FD, &poll_fd),
            0
        );
        // The one-shot timerfd was armed with an absolute expiration in the past
        // (`it_value` one nanosecond after the monotonic epoch), so
        // `timerfd_settime` marks it expired and the timer *will* fire. The
        // guest's `SYS_poll` is deterministically non-blocking here (see
        // `poll_with_timeout`, timeout 0), so on a loaded host it can observe the
        // underlying real timerfd before the kernel has finished propagating the
        // expiration to a non-blocking poll — a timing race, not a logic error.
        //
        // Eliminate the race deterministically by synchronizing on the actual
        // kernel event instead of guessing at a delay: block on the *real* host
        // timerfd until the kernel reports it readable, then issue the guest's
        // non-blocking poll. The blocking wait returns exactly when the timer
        // has fired (promptly, since it was armed in the past) and no sooner, so
        // there is no sleep, no retry budget, and no timing assumption. Once the
        // real fd is readable the non-blocking guest poll is guaranteed to see
        // POLLIN. A large timeout bounds only a genuine kernel/logic bug so the
        // test fails loudly instead of hanging CI forever.
        let real_timerfd = host_fd(&state, timerfd as libc::c_int)
            .expect("guest timerfd must map to a live host descriptor");
        let mut host_poll = libc::pollfd {
            fd: real_timerfd,
            events: libc::POLLIN,
            revents: 0,
        };
        // SAFETY: host_poll points at a single initialized pollfd naming a live
        // host descriptor; the kernel only reads/writes that one entry.
        let host_ready = unsafe { libc::poll(&mut host_poll, 1, 60_000) };
        assert_eq!(
            host_ready, 1,
            "real host timerfd did not become readable within 60s (kernel/logic bug, not jitter)"
        );
        assert_ne!(host_poll.revents & libc::POLLIN, 0);
        let ready = syscall_result(
            &mut memory,
            &mut state,
            libc::SYS_poll,
            [POLL_FD, 1, 0, 0, 0, 0],
        );
        assert_eq!(ready, 1);
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_read,
                [
                    timerfd as u64,
                    EXPIRATIONS,
                    std::mem::size_of::<u64>() as u64,
                    0,
                    0,
                    0,
                ],
            ),
            std::mem::size_of::<u64>() as i64
        );
        let expirations: u64 = read_struct(&memory, EXPIRATIONS);
        assert!(expirations >= 1);

        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_timerfd_gettime,
                [timerfd as u64, CURRENT, 0, 0, 0, 0],
            ),
            0
        );
        let current: libc::itimerspec = read_struct(&memory, CURRENT);
        assert_eq!(current.it_interval.tv_sec, 0);
        assert_eq!(current.it_interval.tv_nsec, 0);
        assert_eq!(current.it_value.tv_sec, 0);
        assert_eq!(current.it_value.tv_nsec, 0);
    }

    #[test]
    fn signalfd_queues_blocked_self_signal_and_reports_readiness() {
        const MASK: u64 = 0x100;
        const POLL_FD: u64 = 0x140;
        const INFO: u64 = 0x180;

        let root = TestDir::new();
        let mut state = test_state(&root.0);
        let pid = state.pid;
        let mut memory = GuestMemory::new(0, PAGE_SIZE as usize).unwrap();
        let mut mask = [0u8; KERNEL_SIGSET_SIZE];
        let bit = (libc::SIGUSR1 - 1) as usize;
        mask[bit / 8] |= 1 << (bit % 8);
        memory.write(MASK, &mask).unwrap();
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_rt_sigprocmask,
                [
                    libc::SIG_BLOCK as u64,
                    MASK,
                    0,
                    KERNEL_SIGSET_SIZE as u64,
                    0,
                    0,
                ],
            ),
            0
        );

        let signal_fd = syscall_result(
            &mut memory,
            &mut state,
            libc::SYS_signalfd4,
            [
                u64::MAX,
                MASK,
                KERNEL_SIGSET_SIZE as u64,
                (libc::SFD_CLOEXEC | libc::SFD_NONBLOCK) as u64,
                0,
                0,
            ],
        );
        assert_eq!(signal_fd, 3);
        let mut poll_fd = libc::pollfd {
            fd: signal_fd as libc::c_int,
            events: libc::POLLIN,
            revents: 0,
        };
        assert_eq!(
            write_struct(&mut ProviderMemory(&memory), POLL_FD, &poll_fd),
            0
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_poll,
                [POLL_FD, 1, 0, 0, 0, 0],
            ),
            0
        );

        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_kill,
                [pid as u64, libc::SIGUSR1 as u64, 0, 0, 0, 0],
            ),
            0
        );
        assert_eq!(
            write_struct(&mut ProviderMemory(&memory), POLL_FD, &poll_fd),
            0
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_poll,
                [POLL_FD, 1, 0, 0, 0, 0],
            ),
            1
        );
        poll_fd = read_struct(&memory, POLL_FD);
        assert_eq!(poll_fd.revents, libc::POLLIN);

        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_read,
                [
                    signal_fd as u64,
                    INFO,
                    std::mem::size_of::<libc::signalfd_siginfo>() as u64,
                    0,
                    0,
                    0,
                ],
            ),
            std::mem::size_of::<libc::signalfd_siginfo>() as i64
        );
        let info: libc::signalfd_siginfo = read_struct(&memory, INFO);
        assert_eq!(info.ssi_signo, libc::SIGUSR1 as u32);
        assert_eq!(info.ssi_pid, pid as u32);

        let poll_fd = libc::pollfd {
            fd: signal_fd as libc::c_int,
            events: libc::POLLIN,
            revents: 0,
        };
        assert_eq!(
            write_struct(&mut ProviderMemory(&memory), POLL_FD, &poll_fd),
            0
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_poll,
                [POLL_FD, 1, 0, 0, 0, 0],
            ),
            0
        );
    }

    /// A write to a pipe whose reader is gone raises SIGPIPE in the writer, as
    /// Linux's pipe_write does: SI_USER from the caller's own process, for
    /// write and for the vectored writes, beside the EPIPE result. An
    /// ignored, unblocked SIGPIPE is discarded at generation.
    #[test]
    fn broken_pipe_writes_raise_sigpipe_in_the_writer() {
        const MASK: u64 = 0x100;
        const PIPE_FDS: u64 = 0x140;
        const DATA: u64 = 0x180;
        const IOV: u64 = 0x1c0;
        const INFO: u64 = 0x200;
        const ACTION: u64 = 0x300;
        let root = TestDir::new();
        let mut state = test_state(&root.0);
        let pid = state.pid;
        let mut memory = GuestMemory::new(0, PAGE_SIZE as usize).unwrap();
        let mut mask = KernelSigset::default();
        mask.insert(libc::SIGPIPE);
        memory.write(MASK, &mask.to_bytes()).unwrap();
        memory.write(DATA, b"x").unwrap();
        let iov = libc::iovec {
            iov_base: DATA as *mut libc::c_void,
            iov_len: 1,
        };
        assert_eq!(write_struct(&mut ProviderMemory(&memory), IOV, &iov), 0);
        test_block_signal(&mut state, libc::SIGPIPE);
        let signal_fd = syscall_result(
            &mut memory,
            &mut state,
            libc::SYS_signalfd4,
            [
                u64::MAX,
                MASK,
                KERNEL_SIGSET_SIZE as u64,
                libc::SFD_NONBLOCK as u64,
                0,
                0,
            ],
        );
        assert!(signal_fd >= 3);
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_pipe2,
                [PIPE_FDS, 0, 0, 0, 0, 0]
            ),
            0
        );
        let [read_fd, write_fd]: [libc::c_int; 2] = read_struct(&memory, PIPE_FDS);
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_close,
                [read_fd as u64, 0, 0, 0, 0, 0]
            ),
            0
        );
        let read_info = |memory: &mut GuestMemory, state: &mut LoadedStaticElf| {
            let result = syscall_result(
                memory,
                state,
                libc::SYS_read,
                [signal_fd as u64, INFO, 128, 0, 0, 0],
            );
            (result == 128).then(|| read_struct::<libc::signalfd_siginfo>(memory, INFO))
        };
        for (number, args) in [
            (libc::SYS_write, [write_fd as u64, DATA, 1, 0, 0, 0]),
            (libc::SYS_writev, [write_fd as u64, IOV, 1, 0, 0, 0]),
            (
                libc::SYS_pwritev2,
                [write_fd as u64, IOV, 1, u64::MAX, u64::MAX, 0],
            ),
        ] {
            assert_eq!(
                syscall_result(&mut memory, &mut state, number, args),
                -i64::from(libc::EPIPE),
                "syscall {number}",
            );
            let info = read_info(&mut memory, &mut state).expect("SIGPIPE was raised");
            assert_eq!(info.ssi_signo, libc::SIGPIPE as u32);
            assert_eq!(info.ssi_code, libc::SI_USER);
            assert_eq!(info.ssi_pid, pid as u32);
            assert_eq!(info.ssi_uid, 0);
            assert!(
                read_info(&mut memory, &mut state).is_none(),
                "one signal per write"
            );
        }

        // The writer's own SIGPIPE and a kill(2)'d process SIGPIPE are both
        // pending, on the thread and on the process, and a signalfd returns
        // both records.
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_write,
                [write_fd as u64, DATA, 1, 0, 0, 0]
            ),
            -i64::from(libc::EPIPE),
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_kill,
                [pid as u64, libc::SIGPIPE as u64, 0, 0, 0, 0]
            ),
            0
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_read,
                [signal_fd as u64, INFO, 256, 0, 0, 0],
            ),
            256
        );
        for index in 0..2_u64 {
            let info: libc::signalfd_siginfo = read_struct(&memory, INFO + 128 * index);
            assert_eq!(
                (info.ssi_signo, info.ssi_code, info.ssi_pid),
                (libc::SIGPIPE as u32, libc::SI_USER, pid as u32),
                "record {index}",
            );
        }
        assert!(read_info(&mut memory, &mut state).is_none());

        // Ignored and unblocked: discarded, the write still fails.
        let mut action = [0_u8; KERNEL_SIGACTION_SIZE];
        action[..8].copy_from_slice(&(libc::SIG_IGN as u64).to_ne_bytes());
        memory.write(ACTION, &action).unwrap();
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_rt_sigaction,
                [
                    libc::SIGPIPE as u64,
                    ACTION,
                    0,
                    KERNEL_SIGSET_SIZE as u64,
                    0,
                    0
                ],
            ),
            0
        );
        state.thread_signals.lock().blocked.remove(libc::SIGPIPE);
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_write,
                [write_fd as u64, DATA, 1, 0, 0, 0]
            ),
            -i64::from(libc::EPIPE),
        );
        assert!(read_info(&mut memory, &mut state).is_none());
    }

    /// rt_sigqueueinfo and rt_tgsigqueueinfo queue the caller's siginfo
    /// (https://man7.org/linux/man-pages/man2/rt_sigqueueinfo.2.html): a
    /// blocked SIGUSR1 reads back from a signalfd with the caller's SI_QUEUE
    /// code and value, and si_signo is the signal argument. Linux's argument
    /// checks come first and in its order.
    #[test]
    fn sigqueueinfo_queues_the_callers_siginfo() {
        const MASK: u64 = 0x100;
        const SENT: u64 = 0x200;
        const INFO: u64 = 0x300;
        let root = TestDir::new();
        let mut state = test_state(&root.0);
        let (pid, tid) = (state.pid, state.tid);
        test_block_signal(&mut state, libc::SIGUSR1);
        let mut memory = GuestMemory::new(0, PAGE_SIZE as usize).unwrap();
        let mut mask = KernelSigset::default();
        mask.insert(libc::SIGUSR1);
        memory.write(MASK, &mask.to_bytes()).unwrap();
        let signal_fd = syscall_result(
            &mut memory,
            &mut state,
            libc::SYS_signalfd4,
            [
                u64::MAX,
                MASK,
                KERNEL_SIGSET_SIZE as u64,
                (libc::SFD_CLOEXEC | libc::SFD_NONBLOCK) as u64,
                0,
                0,
            ],
        );
        assert_eq!(signal_fd, 3);
        let write_info = |memory: &mut GuestMemory, signo: i32, code: i32, value: i32| {
            let mut info = [0_u8; SIGINFO_SIZE];
            info[0..4].copy_from_slice(&signo.to_ne_bytes());
            info[8..12].copy_from_slice(&code.to_ne_bytes());
            info[16..20].copy_from_slice(&pid.to_ne_bytes());
            info[24..28].copy_from_slice(&value.to_ne_bytes());
            memory.write(SENT, &info).unwrap();
        };
        let read_info = |memory: &mut GuestMemory, state: &mut LoadedStaticElf| {
            assert_eq!(
                syscall_result(
                    memory,
                    state,
                    libc::SYS_read,
                    [signal_fd as u64, INFO, 128, 0, 0, 0],
                ),
                128,
            );
            read_struct::<libc::signalfd_siginfo>(memory, INFO)
        };
        let sigusr1 = libc::SIGUSR1 as u64;

        // The thread form; si_signo is overwritten with the argument.
        write_info(&mut memory, 0, libc::SI_QUEUE, 42);
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_rt_tgsigqueueinfo,
                [pid as u64, tid as u64, sigusr1, SENT, 0, 0],
            ),
            0,
        );
        let info = read_info(&mut memory, &mut state);
        assert_eq!(info.ssi_signo, libc::SIGUSR1 as u32);
        assert_eq!(info.ssi_code, libc::SI_QUEUE);
        assert_eq!(info.ssi_pid, pid as u32);
        assert_eq!(info.ssi_int, 42);

        // The process form.
        write_info(&mut memory, libc::SIGUSR1, libc::SI_QUEUE, 7);
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_rt_sigqueueinfo,
                [pid as u64, sigusr1, SENT, 0, 0, 0],
            ),
            0,
        );
        let info = read_info(&mut memory, &mut state);
        assert_eq!((info.ssi_code, info.ssi_int), (libc::SI_QUEUE, 7));

        // A kernel code (SI_USER is 0) only toward the caller's own tid.
        write_info(&mut memory, libc::SIGUSR1, libc::SI_USER, 0);
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_rt_tgsigqueueinfo,
                [pid as u64, (tid + 1000) as u64, sigusr1, SENT, 0, 0],
            ),
            -i64::from(libc::EPERM),
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_rt_tgsigqueueinfo,
                [0, tid as u64, sigusr1, SENT, 0, 0],
            ),
            -i64::from(libc::EINVAL),
        );
        write_info(&mut memory, libc::SIGUSR1, libc::SI_QUEUE, 0);
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_rt_sigqueueinfo,
                [0, sigusr1, SENT, 0, 0, 0],
            ),
            -i64::from(libc::ESRCH),
        );
        // The record is copied in before anything else is checked.
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_rt_tgsigqueueinfo,
                [0, 0, sigusr1, PAGE_SIZE - 8, 0, 0],
            ),
            -i64::from(libc::EFAULT),
        );
    }

    #[test]
    fn consuming_signal_refreshes_distinct_and_duplicated_signalfd_readiness() {
        const MASK: u64 = 0x100;
        const POLL_FDS: u64 = 0x180;
        const INFO: u64 = 0x240;
        let root = TestDir::new();
        let mut state = test_state(&root.0);
        let pid = state.pid;
        test_block_signal(&mut state, libc::SIGUSR1);
        let mut memory = GuestMemory::new(0, PAGE_SIZE as usize).unwrap();
        let mut mask = KernelSigset::default();
        mask.insert(libc::SIGUSR1);
        memory.write(MASK, &mask.to_bytes()).unwrap();
        let create = |memory: &mut GuestMemory, state: &mut LoadedStaticElf| {
            syscall_result(
                memory,
                state,
                libc::SYS_signalfd4,
                [
                    u64::MAX,
                    MASK,
                    KERNEL_SIGSET_SIZE as u64,
                    (libc::SFD_CLOEXEC | libc::SFD_NONBLOCK) as u64,
                    0,
                    0,
                ],
            ) as libc::c_int
        };
        let first = create(&mut memory, &mut state);
        let second = create(&mut memory, &mut state);
        assert_eq!((first, second), (3, 4));
        assert_eq!(
            result_of(kill_signal(
                &mut state,
                libc::SYS_kill as u64,
                &[pid as u64, libc::SIGUSR1 as u64, 0, 0, 0, 0],
            )),
            0,
        );
        let poll = |memory: &mut GuestMemory,
                    state: &mut LoadedStaticElf,
                    first: libc::c_int,
                    second: libc::c_int| {
            let first_poll = libc::pollfd {
                fd: first,
                events: libc::POLLIN,
                revents: 0,
            };
            let second_poll = libc::pollfd {
                fd: second,
                events: libc::POLLIN,
                revents: 0,
            };
            write_struct(&mut ProviderMemory(memory), POLL_FDS, &first_poll);
            write_struct(
                &mut ProviderMemory(memory),
                POLL_FDS + std::mem::size_of::<libc::pollfd>() as u64,
                &second_poll,
            );
            syscall_result(memory, state, libc::SYS_poll, [POLL_FDS, 2, 0, 0, 0, 0])
        };
        assert_eq!(poll(&mut memory, &mut state, first, second), 2);
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_read,
                [first as u64, INFO, 128, 0, 0, 0],
            ),
            128,
        );
        assert_eq!(poll(&mut memory, &mut state, first, second), 0);

        let duplicated = syscall_result(
            &mut memory,
            &mut state,
            libc::SYS_dup,
            [first as u64, 0, 0, 0, 0, 0],
        ) as libc::c_int;
        assert_eq!(duplicated, 5);

        test_block_signal(&mut state, libc::SIGUSR2);
        mask.remove(libc::SIGUSR1);
        mask.insert(libc::SIGUSR2);
        memory.write(MASK, &mask.to_bytes()).unwrap();
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_signalfd4,
                [first as u64, MASK, KERNEL_SIGSET_SIZE as u64, 0, 0, 0],
            ),
            i64::from(first),
            "updating one alias must update the shared signalfd description",
        );
        {
            let process_signals = state.process_signals.lock().unwrap();
            assert!(process_signals.signalfd_masks[&first].contains(libc::SIGUSR2));
            assert!(process_signals.signalfd_masks[&duplicated].contains(libc::SIGUSR2));
            assert!(!process_signals.signalfd_masks[&first].contains(libc::SIGUSR1));
            assert!(!process_signals.signalfd_masks[&duplicated].contains(libc::SIGUSR1));
            assert!(process_signals.signalfd_masks[&second].contains(libc::SIGUSR1));
            assert!(!process_signals.signalfd_masks[&second].contains(libc::SIGUSR2));
        }
        assert_eq!(
            result_of(kill_signal(
                &mut state,
                libc::SYS_kill as u64,
                &[pid as u64, libc::SIGUSR2 as u64, 0, 0, 0, 0],
            )),
            0,
        );
        assert_eq!(poll(&mut memory, &mut state, first, duplicated), 2);
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_read,
                [duplicated as u64, INFO, 128, 0, 0, 0],
            ),
            128,
        );
        assert_eq!(poll(&mut memory, &mut state, first, duplicated), 0);

        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_close,
                [first as u64, 0, 0, 0, 0, 0]
            ),
            0,
        );
        assert_eq!(
            result_of(kill_signal(
                &mut state,
                libc::SYS_kill as u64,
                &[pid as u64, libc::SIGUSR2 as u64, 0, 0, 0, 0],
            )),
            0,
        );
        assert_eq!(poll(&mut memory, &mut state, second, duplicated), 1);
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_read,
                [duplicated as u64, INFO, 128, 0, 0, 0],
            ),
            128,
        );
        assert_eq!(poll(&mut memory, &mut state, second, duplicated), 0);

        // The second independently-created description is CLOEXEC, while dup
        // cleared CLOEXEC on its alias of the first description. Exec must
        // remove exactly the closed description's mask and preserve the live
        // alias with its unchanged mask.
        let mut after_exec = test_state(&root.0);
        after_exec.inherit_process_state(state);
        assert!(!after_exec.files.contains_key(&second));
        assert!(after_exec.files.contains_key(&duplicated));
        let process_signals = after_exec.process_signals.lock().unwrap();
        assert_eq!(
            process_signals
                .signalfd_masks
                .keys()
                .copied()
                .collect::<Vec<_>>(),
            vec![duplicated],
        );
        assert!(process_signals.signalfd_masks[&duplicated].contains(libc::SIGUSR2));
        assert!(!process_signals.signalfd_masks[&duplicated].contains(libc::SIGUSR1));
    }

    #[test]
    fn delivery_selection_refreshes_every_signalfd_alias_before_filtering() {
        const MASK: u64 = 0x100;
        const POLL_FDS: u64 = 0x180;
        let root = TestDir::new();
        let mut executor = ElfExecutor::new(test_state(&root.0), false);
        let pid = executor.state.pid;
        let mut memory = GuestMemory::new(0, PAGE_SIZE as usize).unwrap();
        let mut mask = KernelSigset::default();
        mask.insert(libc::SIGUSR1);
        mask.insert(libc::SIGUSR2);
        memory.write(MASK, &mask.to_bytes()).unwrap();
        test_block_signal(&mut executor.state, libc::SIGUSR1);
        test_block_signal(&mut executor.state, libc::SIGUSR2);
        let original = syscall_result(
            &mut memory,
            &mut executor.state,
            libc::SYS_signalfd4,
            [
                u64::MAX,
                MASK,
                KERNEL_SIGSET_SIZE as u64,
                libc::SFD_NONBLOCK as u64,
                0,
                0,
            ],
        ) as libc::c_int;
        let alias = syscall_result(
            &mut memory,
            &mut executor.state,
            libc::SYS_dup,
            [original as u64, 0, 0, 0, 0, 0],
        ) as libc::c_int;
        let poll = |memory: &mut GuestMemory, state: &mut LoadedStaticElf| {
            for (index, fd) in [original, alias].into_iter().enumerate() {
                let descriptor = libc::pollfd {
                    fd,
                    events: libc::POLLIN,
                    revents: 0,
                };
                assert_eq!(
                    write_struct(
                        &mut ProviderMemory(memory),
                        POLL_FDS + index as u64 * std::mem::size_of::<libc::pollfd>() as u64,
                        &descriptor,
                    ),
                    0,
                );
            }
            syscall_result(memory, state, libc::SYS_poll, [POLL_FDS, 2, 0, 0, 0, 0])
        };
        let queue = |state: &mut LoadedStaticElf| {
            assert_eq!(
                result_of(kill_signal(
                    state,
                    libc::SYS_kill as u64,
                    &[pid as u64, libc::SIGUSR1 as u64, 0, 0, 0, 0],
                )),
                0,
            );
        };

        // Ordinary delivery removes an event that was readable while blocked.
        // The return-boundary helper must clear every alias before disposition
        // processing (and the same helper is used after rt_sigreturn).
        queue(&mut executor.state);
        assert_eq!(poll(&mut memory, &mut executor.state), 2);
        executor
            .state
            .thread_signals
            .lock()
            .blocked
            .remove(libc::SIGUSR1);
        let selected = executor
            .take_pending_signal_for_delivery()
            .unwrap()
            .unwrap();
        assert_eq!(selected.event.signal(), libc::SIGUSR1);
        assert_eq!(poll(&mut memory, &mut executor.state), 0);

        // Suppression has no requeue step, so selection itself must have
        // removed the stale readiness from every alias.
        test_block_signal(&mut executor.state, libc::SIGUSR1);
        queue(&mut executor.state);
        assert_eq!(poll(&mut memory, &mut executor.state), 2);
        executor
            .state
            .thread_signals
            .lock()
            .blocked
            .remove(libc::SIGUSR1);
        let suppressed = executor
            .take_pending_signal_for_delivery()
            .unwrap()
            .unwrap();
        assert_eq!(suppressed.event.signal(), libc::SIGUSR1);
        assert_eq!(poll(&mut memory, &mut executor.state), 0);

        // A Tool replacement that is blocked is requeued and makes every
        // alias ready again for the replacement signal.
        test_block_signal(&mut executor.state, libc::SIGUSR1);
        queue(&mut executor.state);
        executor
            .state
            .thread_signals
            .lock()
            .blocked
            .remove(libc::SIGUSR1);
        let selected = executor
            .take_pending_signal_for_delivery()
            .unwrap()
            .unwrap();
        assert_eq!(poll(&mut memory, &mut executor.state), 0);
        let mut info = selected.event.siginfo();
        info[..4].copy_from_slice(&libc::SIGUSR2.to_ne_bytes());
        let replacement = reverie::SignalEvent::new(
            libc::SIGUSR2,
            info,
            reverie::SignalTarget::Process {
                pid: reverie::Pid::from_raw(pid),
            },
        )
        .unwrap();
        assert_eq!(
            executor
                .prepare_filtered_signal_delivery(replacement, selected.domain)
                .unwrap(),
            None,
        );
        assert_eq!(poll(&mut memory, &mut executor.state), 2);
    }

    #[test]
    fn signalfd_readiness_and_reads_are_each_threads_own() {
        const MASK: u64 = 0x100;
        const POLL_FD: u64 = 0x140;
        const RECORDS: u64 = 0x200;

        let root = TestDir::new();
        let mut leader = ElfExecutor::new(test_state(&root.0), false);
        for signal in [libc::SIGUSR1, libc::SIGUSR2] {
            test_block_signal(&mut leader.state, signal);
        }
        // A second thread exists before the signalfd, and a third starts
        // while it is open.
        let mut worker = leader.thread_child(7).unwrap();
        let mut memory = GuestMemory::new(0, PAGE_SIZE as usize).unwrap();
        let mut mask = KernelSigset::default();
        mask.insert(libc::SIGUSR1);
        mask.insert(libc::SIGUSR2);
        memory.write(MASK, &mask.to_bytes()).unwrap();
        let signal_fd = leader.execute(
            &SyscallRequest::new(
                libc::SYS_signalfd4 as u64,
                [
                    u64::MAX,
                    MASK,
                    KERNEL_SIGSET_SIZE as u64,
                    (libc::SFD_CLOEXEC | libc::SFD_NONBLOCK) as u64,
                    0,
                    0,
                ],
            ),
            &memory,
        );
        assert_eq!(
            signal_fd, 3,
            "a process with a second thread gets a signalfd"
        );
        assert_eq!(leader.take_unsupported_refusal(), None);
        let mut late = leader.thread_child(8).unwrap();

        let poll = |executor: &mut ElfExecutor| {
            let poll_fd = libc::pollfd {
                fd: signal_fd as libc::c_int,
                events: libc::POLLIN,
                revents: 0,
            };
            assert_eq!(
                write_struct(&mut ProviderMemory(&memory), POLL_FD, &poll_fd),
                0
            );
            let ready = executor.execute(
                &SyscallRequest::new(libc::SYS_poll as u64, [POLL_FD, 1, 0, 0, 0, 0]),
                &memory,
            );
            let polled: libc::pollfd = read_struct(&memory, POLL_FD);
            assert_eq!(polled.revents, if ready == 1 { libc::POLLIN } else { 0 });
            ready
        };
        // Up to two records; the signal number of each one read.
        let read = |executor: &mut ElfExecutor| {
            let result = executor.execute(
                &SyscallRequest::new(
                    libc::SYS_read as u64,
                    [signal_fd as u64, RECORDS, 256, 0, 0, 0],
                ),
                &memory,
            );
            let signals = (0..result.max(0) as u64 / 128)
                .map(|record| {
                    let mut signo = [0_u8; 4];
                    memory.read(RECORDS + 128 * record, &mut signo).unwrap();
                    u32::from_ne_bytes(signo) as libc::c_int
                })
                .collect::<Vec<_>>();
            (result, signals)
        };
        let tkill = |executor: &mut ElfExecutor, tid: u64, signal: libc::c_int| {
            assert_eq!(
                executor.execute(
                    &SyscallRequest::new(libc::SYS_tkill as u64, [tid, signal as u64, 0, 0, 0, 0]),
                    &memory,
                ),
                0
            );
        };
        let pid = leader.state.pid;

        // A signal queued for the worker alone is readable by the worker
        // only, as Linux's signalfd_poll checks the polling task's queue.
        tkill(&mut leader, 7, libc::SIGUSR1);
        assert_eq!(poll(&mut leader), 0);
        assert_eq!(poll(&mut late), 0);
        assert_eq!(poll(&mut worker), 1);
        assert_eq!(read(&mut leader), (negative_errno(libc::EAGAIN), vec![]));
        assert_eq!(read(&mut worker), (128, vec![libc::SIGUSR1]));
        assert_eq!(poll(&mut worker), 0);

        // A signal queued for the process is readable by every thread, and
        // read once.
        queue_signal_event(
            &mut leader.state,
            event_for_process(libc::SIGUSR2, pid).unwrap(),
            true,
        )
        .unwrap();
        for executor in [&mut leader, &mut worker, &mut late] {
            assert_eq!(poll(executor), 1);
        }
        assert_eq!(read(&mut late), (128, vec![libc::SIGUSR2]));
        for executor in [&mut leader, &mut worker, &mut late] {
            assert_eq!(poll(executor), 0);
        }

        // A read takes the thread's own signal before the process's, as
        // Linux's dequeue_signal does, even where the process's has the lower
        // number.
        tkill(&mut late, 8, libc::SIGUSR2);
        queue_signal_event(
            &mut leader.state,
            event_for_process(libc::SIGUSR1, pid).unwrap(),
            true,
        )
        .unwrap();
        assert_eq!(read(&mut late), (256, vec![libc::SIGUSR2, libc::SIGUSR1]));
        for executor in [&mut leader, &mut worker, &mut late] {
            assert_eq!(poll(executor), 0);
        }
    }

    #[test]
    fn process_fork_with_inherited_signalfd_is_explicitly_unsupported() {
        const MASK: u64 = 0x100;
        let root = TestDir::new();
        let mut executor = ElfExecutor::new(test_state(&root.0), false);
        let mut memory = GuestMemory::new(0, PAGE_SIZE as usize).unwrap();
        let mut mask = KernelSigset::default();
        mask.insert(libc::SIGUSR1);
        memory.write(MASK, &mask.to_bytes()).unwrap();
        assert_eq!(
            executor.execute(
                &SyscallRequest::new(
                    libc::SYS_signalfd4 as u64,
                    [
                        u64::MAX,
                        MASK,
                        KERNEL_SIGSET_SIZE as u64,
                        (libc::SFD_CLOEXEC | libc::SFD_NONBLOCK) as u64,
                        0,
                        0,
                    ],
                ),
                &memory,
            ),
            3,
        );
        assert_eq!(
            executor.execute(&SyscallRequest::new(libc::SYS_fork as u64, [0; 6]), &memory,),
            negative_errno(libc::ENOSYS),
            "a shared host eventfd cannot represent per-process readiness after fork",
        );
        assert_eq!(
            executor
                .take_unsupported_refusal()
                .map(|refusal| (refusal.operation, refusal.diagnostic)),
            Some((
                reverie::UnsupportedOperation::Signalfd,
                SIGNALFD_FORK_REFUSAL
            )),
            "the refusal is named",
        );
        assert!(executor.take_process_action().is_none());
        assert!(
            executor.fork_child(7, false, false).is_err(),
            "the internal process-child path must enforce the same pre-mutation guard",
        );
    }

    #[test]
    fn signalfd_is_one_aggregate_record_stream_across_scalar_and_vectored_reads() {
        const MASK: u64 = 0x100;
        const IOVEC: u64 = 0x180;
        const OUTPUT: u64 = 0x400;
        const OUTPUT_A: u64 = 0x800;
        const OUTPUT_B: u64 = 0x900;
        const OUTPUT_C: u64 = 0xa00;

        let root = TestDir::new();
        let mut state = test_state(&root.0);
        let pid = state.pid;
        let mut memory = GuestMemory::new(0, PAGE_SIZE as usize).unwrap();
        let mut mask = KernelSigset::default();
        mask.insert(libc::SIGUSR1);
        mask.insert(libc::SIGUSR2);
        memory.write(MASK, &mask.to_bytes()).unwrap();
        test_block_signal(&mut state, libc::SIGUSR1);
        test_block_signal(&mut state, libc::SIGUSR2);
        let signal_fd = syscall_result(
            &mut memory,
            &mut state,
            libc::SYS_signalfd4,
            [
                u64::MAX,
                MASK,
                KERNEL_SIGSET_SIZE as u64,
                libc::SFD_NONBLOCK as u64,
                0,
                0,
            ],
        );
        assert_eq!(signal_fd, 3);
        let queue = |state: &mut LoadedStaticElf, signal| {
            assert_eq!(
                result_of(kill_signal(
                    state,
                    libc::SYS_kill as u64,
                    &[pid as u64, signal as u64, 0, 0, 0, 0],
                )),
                0,
            );
        };

        queue(&mut state, libc::SIGUSR2);
        queue(&mut state, libc::SIGUSR1);
        memory.write(OUTPUT, &[0xcc; 300]).unwrap();
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_read,
                [signal_fd as u64, OUTPUT, 300, 0, 0, 0],
            ),
            256,
        );
        let first: libc::signalfd_siginfo = read_struct(&memory, OUTPUT);
        let second: libc::signalfd_siginfo = read_struct(&memory, OUTPUT + 128);
        assert_eq!(
            (first.ssi_signo, second.ssi_signo),
            (libc::SIGUSR1 as u32, libc::SIGUSR2 as u32)
        );
        let mut trailing = [0; 44];
        memory.read(OUTPUT + 256, &mut trailing).unwrap();
        assert_eq!(trailing, [0xcc; 44]);

        queue(&mut state, libc::SIGUSR2);
        queue(&mut state, libc::SIGUSR1);
        memory.write(OUTPUT_A, &[0xdd; 64]).unwrap();
        memory.write(OUTPUT_B, &[0xdd; 65]).unwrap();
        memory.write(OUTPUT_C, &[0xdd; 128]).unwrap();
        for (index, vector) in [
            libc::iovec {
                iov_base: OUTPUT_A as *mut _,
                iov_len: 64,
            },
            libc::iovec {
                iov_base: OUTPUT_B as *mut _,
                iov_len: 65,
            },
            libc::iovec {
                iov_base: OUTPUT_C as *mut _,
                iov_len: 128,
            },
        ]
        .into_iter()
        .enumerate()
        {
            assert_eq!(
                write_struct(
                    &mut ProviderMemory(&memory),
                    IOVEC + index as u64 * 16,
                    &vector
                ),
                0
            );
        }
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_readv,
                [signal_fd as u64, IOVEC, 3, 0, 0, 0],
            ),
            256,
        );
        let mut gathered = [0; 256];
        memory.read(OUTPUT_A, &mut gathered[..64]).unwrap();
        memory.read(OUTPUT_B, &mut gathered[64..129]).unwrap();
        memory.read(OUTPUT_C, &mut gathered[129..]).unwrap();
        assert_eq!(
            u32::from_ne_bytes(gathered[..4].try_into().unwrap()),
            libc::SIGUSR1 as u32
        );
        assert_eq!(
            u32::from_ne_bytes(gathered[128..132].try_into().unwrap()),
            libc::SIGUSR2 as u32
        );
        let mut sentinel = [0; 1];
        memory.read(OUTPUT_C + 127, &mut sentinel).unwrap();
        assert_eq!(sentinel, [0xdd]);

        queue(&mut state, libc::SIGUSR1);
        let one = libc::iovec {
            iov_base: OUTPUT as *mut _,
            iov_len: 128,
        };
        assert_eq!(write_struct(&mut ProviderMemory(&memory), IOVEC, &one), 0);
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_preadv2,
                [signal_fd as u64, IOVEC, 1, (-2_i64) as u64, 0, 0,],
            ),
            negative_errno(libc::EINVAL),
        );
        assert!(
            state
                .process_signals
                .lock()
                .unwrap()
                .shared_pending
                .contains(libc::SIGUSR1),
            "an invalid signed 64-bit offset must not dequeue the signal",
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_preadv2,
                [
                    signal_fd as u64,
                    IOVEC,
                    1,
                    u32::MAX as u64,
                    u32::MAX as u64,
                    0,
                ],
            ),
            negative_errno(libc::ESPIPE),
            "args[4] is padding on x86-64; args[3]=0xffffffff is positive",
        );
        assert!(
            state
                .process_signals
                .lock()
                .unwrap()
                .shared_pending
                .contains(libc::SIGUSR1),
            "a positioned signalfd read must not dequeue the signal",
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_preadv2,
                [
                    signal_fd as u64,
                    IOVEC,
                    1,
                    u64::MAX,
                    0,
                    libc::RWF_NOWAIT as u64
                ],
            ),
            128,
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_preadv2,
                [signal_fd as u64, u64::MAX, 1, 0, 0, 0],
            ),
            negative_errno(libc::ESPIPE),
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_preadv2,
                [
                    signal_fd as u64,
                    IOVEC,
                    1,
                    u64::MAX,
                    0,
                    libc::RWF_NOWAIT as u64
                ],
            ),
            negative_errno(libc::EAGAIN),
        );

        // Standard instances coalesce within one pending domain, while the
        // same number in the caller-private and process-shared domains yields
        // two records in one aggregate read.
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_tkill,
                [pid as u64, libc::SIGUSR1 as u64, 0, 0, 0, 0],
            ),
            0,
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_tkill,
                [pid as u64, libc::SIGUSR1 as u64, 0, 0, 0, 0],
            ),
            0,
        );
        queue(&mut state, libc::SIGUSR1);
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_read,
                [signal_fd as u64, OUTPUT, 256, 0, 0, 0],
            ),
            256,
        );
    }

    #[test]
    fn signalfd_preadv_offsets_use_signed_arg3_and_ignore_arg4_padding() {
        const MASK: u64 = 0x100;
        const IOVEC: u64 = 0x180;
        const OUTPUT: u64 = 0x300;
        let root = TestDir::new();

        for number in [libc::SYS_preadv, libc::SYS_preadv2] {
            let mut state = test_state(&root.0);
            let mut memory = GuestMemory::new(0, PAGE_SIZE as usize).unwrap();
            let mut mask = KernelSigset::default();
            mask.insert(libc::SIGUSR1);
            memory.write(MASK, &mask.to_bytes()).unwrap();
            test_block_signal(&mut state, libc::SIGUSR1);
            let signal_fd = syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_signalfd4,
                [
                    u64::MAX,
                    MASK,
                    KERNEL_SIGSET_SIZE as u64,
                    libc::SFD_NONBLOCK as u64,
                    0,
                    0,
                ],
            );
            let vector = libc::iovec {
                iov_base: OUTPUT as *mut _,
                iov_len: SIGNALFD_RECORD_SIZE,
            };
            assert_eq!(
                write_struct(&mut ProviderMemory(&memory), IOVEC, &vector),
                0
            );
            let pid = state.pid;
            assert_eq!(
                result_of(kill_signal(
                    &mut state,
                    libc::SYS_kill as u64,
                    &[pid as u64, libc::SIGUSR1 as u64, 0, 0, 0, 0],
                )),
                0,
            );
            let flags = if number == libc::SYS_preadv2 {
                libc::RWF_NOWAIT as u64
            } else {
                0
            };
            for (low, high, expected) in [
                ((-2_i64) as u64, 0, negative_errno(libc::EINVAL)),
                (
                    u32::MAX as u64,
                    u32::MAX as u64,
                    negative_errno(libc::ESPIPE),
                ),
            ] {
                assert_eq!(
                    syscall_result(
                        &mut memory,
                        &mut state,
                        number,
                        [signal_fd as u64, IOVEC, 1, low, high, flags],
                    ),
                    expected,
                    "syscall={number}, arg3={low:#x}, arg4={high:#x}",
                );
                assert!(
                    state
                        .process_signals
                        .lock()
                        .unwrap()
                        .shared_pending
                        .contains(libc::SIGUSR1),
                    "offset failure must not consume pending state",
                );
            }
            assert_eq!(
                syscall_result(
                    &mut memory,
                    &mut state,
                    number,
                    [signal_fd as u64, IOVEC, 1, u64::MAX, 0, flags],
                ),
                if number == libc::SYS_preadv2 {
                    SIGNALFD_RECORD_SIZE as i64
                } else {
                    negative_errno(libc::EINVAL)
                },
                "only preadv2 accepts the current-position sentinel",
            );
            if number == libc::SYS_preadv {
                assert!(
                    state
                        .process_signals
                        .lock()
                        .unwrap()
                        .shared_pending
                        .contains(libc::SIGUSR1),
                    "preadv(-1) must not consume the pending record"
                );
                assert_eq!(
                    syscall_result(
                        &mut memory,
                        &mut state,
                        libc::SYS_preadv2,
                        [signal_fd as u64, IOVEC, 1, u64::MAX, 0, 0]
                    ),
                    SIGNALFD_RECORD_SIZE as i64
                );
            }
        }
    }

    #[test]
    fn signalfd_vector_validation_and_fault_consumption_match_linux_ordering() {
        const MASK: u64 = 0x100;
        const IOVEC: u64 = 0x180;
        const OUTPUT: u64 = 0x300;
        let boundary = PAGE_SIZE - 192;
        let root = TestDir::new();
        let mut state = test_state(&root.0);
        let pid = state.pid;
        let mut memory = GuestMemory::new(0, (3 * PAGE_SIZE) as usize).unwrap();
        let mut mask = KernelSigset::default();
        mask.insert(libc::SIGUSR1);
        mask.insert(libc::SIGUSR2);
        memory.write(MASK, &mask.to_bytes()).unwrap();
        test_block_signal(&mut state, libc::SIGUSR1);
        test_block_signal(&mut state, libc::SIGUSR2);
        let signal_fd = syscall_result(
            &mut memory,
            &mut state,
            libc::SYS_signalfd4,
            [
                u64::MAX,
                MASK,
                KERNEL_SIGSET_SIZE as u64,
                libc::SFD_NONBLOCK as u64,
                0,
                0,
            ],
        );
        let queue = |state: &mut LoadedStaticElf, signal| {
            assert_eq!(
                result_of(kill_signal(
                    state,
                    libc::SYS_kill as u64,
                    &[pid as u64, signal as u64, 0, 0, 0, 0],
                )),
                0,
            );
        };
        queue(&mut state, libc::SIGUSR1);

        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_read,
                [signal_fd as u64, OUTPUT, 0, 0, 0, 0]
            ),
            negative_errno(libc::EINVAL),
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_readv,
                [signal_fd as u64, IOVEC, 0, 0, 0, 0]
            ),
            0,
        );
        let short = libc::iovec {
            iov_base: OUTPUT as *mut _,
            iov_len: 127,
        };
        assert_eq!(write_struct(&mut ProviderMemory(&memory), IOVEC, &short), 0);
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_readv,
                [signal_fd as u64, IOVEC, 1, 0, 0, 0]
            ),
            negative_errno(libc::EINVAL),
        );
        assert!(
            state
                .process_signals
                .lock()
                .unwrap()
                .shared_pending
                .contains(libc::SIGUSR1)
        );

        let invalid_table = libc::iovec {
            iov_base: OUTPUT as *mut _,
            iov_len: 128,
        };
        memory
            .write_raw(PAGE_SIZE - 8, unsafe {
                std::slice::from_raw_parts(
                    std::ptr::from_ref(&invalid_table).cast::<u8>(),
                    std::mem::size_of::<libc::iovec>(),
                )
            })
            .unwrap();
        memory.map_user_range(0, PAGE_SIZE, false).unwrap();
        memory.map_user_range(PAGE_SIZE, PAGE_SIZE, true).unwrap();
        memory.enable_user_access();
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_readv,
                [signal_fd as u64, PAGE_SIZE - 8, 1, 0, 0, 0]
            ),
            negative_errno(libc::EFAULT),
        );
        assert!(
            state
                .process_signals
                .lock()
                .unwrap()
                .shared_pending
                .contains(libc::SIGUSR1)
        );

        queue(&mut state, libc::SIGUSR2);
        let crossing = libc::iovec {
            iov_base: boundary as *mut _,
            iov_len: 256,
        };
        assert_eq!(
            write_struct(&mut ProviderMemory(&memory), IOVEC, &crossing),
            0
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_readv,
                [signal_fd as u64, IOVEC, 1, 0, 0, 0]
            ),
            128,
            "the faulting second record is consumed after its accessible prefix is copied",
        );
        assert!(
            state
                .process_signals
                .lock()
                .unwrap()
                .shared_pending
                .is_empty()
        );

        queue(&mut state, libc::SIGUSR1);
        let outside_guest_mapping = libc::iovec {
            iov_base: (memory.guest_end() + PAGE_SIZE) as *mut libc::c_void,
            iov_len: SIGNALFD_RECORD_SIZE,
        };
        assert_eq!(
            write_struct(&mut ProviderMemory(&memory), IOVEC, &outside_guest_mapping),
            0
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_readv,
                [signal_fd as u64, IOVEC, 1, 0, 0, 0],
            ),
            negative_errno(libc::EFAULT),
        );
        assert!(
            !state
                .process_signals
                .lock()
                .unwrap()
                .shared_pending
                .contains(libc::SIGUSR1),
            "a canonical but unmapped destination faults only after dequeue",
        );

        queue(&mut state, libc::SIGUSR1);
        let outside_user_range = libc::iovec {
            iov_base: (1_u64 << 47) as *mut libc::c_void,
            iov_len: SIGNALFD_RECORD_SIZE,
        };
        assert_eq!(
            write_struct(&mut ProviderMemory(&memory), IOVEC, &outside_user_range),
            0
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_readv,
                [signal_fd as u64, IOVEC, 1, 0, 0, 0],
            ),
            negative_errno(libc::EFAULT),
        );
        assert!(
            state
                .process_signals
                .lock()
                .unwrap()
                .shared_pending
                .contains(libc::SIGUSR1),
            "an address rejected by access_ok fails before dequeue",
        );
    }
    /// A blocking signalfd is the guest description's mode, shared by every
    /// alias as Linux shares O_NONBLOCK on the open file description, while
    /// the host keeper stays nonblocking. A read returns pending signals in
    /// either mode; only a blocking read with nothing pending, which would
    /// wait, is refused.
    #[test]
    fn blocking_signalfd_mode_is_shared_by_aliases_and_only_a_waiting_read_is_refused() {
        const MASK: u64 = 0x100;
        const INFO: u64 = 0x200;
        const VALUE: u64 = 0x380;
        let root = TestDir::new();
        let mut state = test_state(&root.0);
        let pid = state.pid;
        let mut memory = GuestMemory::new(0, PAGE_SIZE as usize).unwrap();
        let mut mask = KernelSigset::default();
        mask.insert(libc::SIGUSR1);
        memory.write(MASK, &mask.to_bytes()).unwrap();
        test_block_signal(&mut state, libc::SIGUSR1);
        let getfl = |memory: &mut GuestMemory, state: &mut LoadedStaticElf, fd: i64| {
            syscall_result(
                memory,
                state,
                libc::SYS_fcntl,
                [fd as u64, libc::F_GETFL as u64, 0, 0, 0, 0],
            ) & i64::from(libc::O_NONBLOCK)
        };
        let read = |memory: &mut GuestMemory, state: &mut LoadedStaticElf, fd: i64| {
            syscall_result(
                memory,
                state,
                libc::SYS_read,
                [fd as u64, INFO, 128, 0, 0, 0],
            )
        };
        let raise = |state: &mut LoadedStaticElf| {
            assert_eq!(
                result_of(kill_signal(
                    state,
                    libc::SYS_kill as u64,
                    &[pid as u64, libc::SIGUSR1 as u64, 0, 0, 0, 0],
                )),
                0,
            );
        };
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_signalfd4,
                [u64::MAX, MASK, KERNEL_SIGSET_SIZE as u64, 0x4000, 0, 0],
            ),
            negative_errno(libc::EINVAL),
        );
        for (expected_fd, (number, flags)) in [
            (libc::SYS_signalfd, 0),
            (libc::SYS_signalfd4, 0),
            (libc::SYS_signalfd4, libc::SFD_CLOEXEC as u64),
        ]
        .into_iter()
        .enumerate()
        {
            let fd = syscall_result(
                &mut memory,
                &mut state,
                number,
                [u64::MAX, MASK, KERNEL_SIGSET_SIZE as u64, flags, 0, 0],
            );
            assert_eq!(fd, 3 + expected_fd as i64);
            assert_eq!(
                getfl(&mut memory, &mut state, fd),
                0,
                "blocking mode is reported"
            );
            let host = host_fd(&state, fd as libc::c_int).unwrap();
            assert_ne!(
                fd_status_flags(host).unwrap() & libc::O_NONBLOCK,
                0,
                "the host keeper stays nonblocking",
            );
            // Nothing pending: a blocking read would wait, and is refused.
            assert_eq!(
                read(&mut memory, &mut state, fd),
                negative_errno(libc::ENOSYS)
            );
            // A pending signal is read in blocking mode too.
            raise(&mut state);
            assert_eq!(read(&mut memory, &mut state, fd), 128);
            let info: libc::signalfd_siginfo = read_struct(&memory, INFO);
            assert_eq!(info.ssi_signo, libc::SIGUSR1 as u32);
        }

        let signal_fd = syscall_result(
            &mut memory,
            &mut state,
            libc::SYS_signalfd4,
            [
                u64::MAX,
                MASK,
                KERNEL_SIGSET_SIZE as u64,
                libc::SFD_NONBLOCK as u64,
                0,
                0,
            ],
        );
        assert_eq!(signal_fd, 6);
        let alias = syscall_result(
            &mut memory,
            &mut state,
            libc::SYS_dup,
            [signal_fd as u64, 0, 0, 0, 0, 0],
        );
        let fixed_alias = syscall_result(
            &mut memory,
            &mut state,
            libc::SYS_dup2,
            [signal_fd as u64, 10, 0, 0, 0, 0],
        );
        assert_eq!(fixed_alias, 10);
        let fcntl_alias = syscall_result(
            &mut memory,
            &mut state,
            libc::SYS_fcntl,
            [signal_fd as u64, libc::F_DUPFD as u64, 20, 0, 0, 0],
        );
        assert_eq!(fcntl_alias, 20);
        let aliases = [signal_fd, alias, fixed_alias, fcntl_alias];
        for fd in aliases {
            assert_ne!(getfl(&mut memory, &mut state, fd), 0);
        }
        // Clearing O_NONBLOCK through one alias makes every alias blocking.
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_fcntl,
                [alias as u64, libc::F_SETFL as u64, 0, 0, 0, 0],
            ),
            0,
        );
        for fd in aliases {
            assert_eq!(getfl(&mut memory, &mut state, fd), 0, "alias {fd}");
        }
        assert_eq!(
            read(&mut memory, &mut state, fcntl_alias),
            negative_errno(libc::ENOSYS)
        );
        let host = host_fd(&state, signal_fd as libc::c_int).unwrap();
        assert_ne!(fd_status_flags(host).unwrap() & libc::O_NONBLOCK, 0);
        // FIONBIO through another alias makes every alias nonblocking again.
        assert_eq!(write_struct(&mut ProviderMemory(&memory), VALUE, &1_i32), 0);
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_ioctl,
                [fixed_alias as u64, libc::FIONBIO, VALUE, 0, 0, 0],
            ),
            0,
        );
        for fd in aliases {
            assert_ne!(getfl(&mut memory, &mut state, fd), 0, "alias {fd}");
        }
        assert_eq!(
            read(&mut memory, &mut state, signal_fd),
            negative_errno(libc::EAGAIN)
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_signalfd4,
                [signal_fd as u64, MASK, KERNEL_SIGSET_SIZE as u64, 0, 0, 0],
            ),
            signal_fd,
            "mask updates on an existing description remain supported",
        );
        let masks = &state.process_signals.lock().unwrap().signalfd_masks;
        for fd in aliases {
            assert!(masks[&(fd as i32)].contains(libc::SIGUSR1));
            assert!(
                Arc::ptr_eq(&masks[&(signal_fd as i32)], &masks[&(fd as i32)]),
                "alias {fd} must retain the shared signalfd description",
            );
        }
    }

    #[test]
    fn ppoll_waits_on_a_virtual_signalfd_and_epoll_refuses_one() {
        const MASK: u64 = 0x100;
        const POLL_FD: u64 = 0x180;
        const TIMEOUT: u64 = 0x200;
        const EPOLL_EVENT: u64 = 0x280;
        const EPOLL_OUTPUT: u64 = 0x300;
        let root = TestDir::new();
        let mut state = test_state(&root.0);
        let mut memory = GuestMemory::new(0, PAGE_SIZE as usize).unwrap();
        let mut mask = KernelSigset::default();
        mask.insert(libc::SIGUSR1);
        memory.write(MASK, &mask.to_bytes()).unwrap();
        test_block_signal(&mut state, libc::SIGUSR1);
        let signal_fd = syscall_result(
            &mut memory,
            &mut state,
            libc::SYS_signalfd4,
            [
                u64::MAX,
                MASK,
                KERNEL_SIGSET_SIZE as u64,
                libc::SFD_NONBLOCK as u64,
                0,
                0,
            ],
        );
        let alias = syscall_result(
            &mut memory,
            &mut state,
            libc::SYS_dup,
            [signal_fd as u64, 0, 0, 0, 0, 0],
        );

        let untouched = libc::pollfd {
            fd: alias as libc::c_int,
            events: libc::POLLIN,
            revents: libc::POLLPRI,
        };
        // With nothing pending, a ppoll with a timeout waits it out, and
        // reports nothing ready (see
        // ppoll_on_a_virtual_signalfd_wakes_for_a_covered_signal for a wait a
        // signal ends).
        let short = libc::timespec {
            tv_sec: 0,
            tv_nsec: 30_000_000,
        };
        assert_eq!(
            write_struct(&mut ProviderMemory(&memory), POLL_FD, &untouched),
            0
        );
        assert_eq!(
            write_struct(&mut ProviderMemory(&memory), TIMEOUT, &short),
            0
        );
        let started = std::time::Instant::now();
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_ppoll,
                [POLL_FD, 1, TIMEOUT, 0, 0, 0],
            ),
            0,
        );
        assert!(started.elapsed() >= std::time::Duration::from_millis(30));
        let observed: libc::pollfd = read_struct(&memory, POLL_FD);
        assert_eq!(observed.fd, untouched.fd);
        assert_eq!(observed.events, untouched.events);
        assert_eq!(observed.revents, 0);

        let zero_timeout = libc::timespec {
            tv_sec: 0,
            tv_nsec: 0,
        };
        assert_eq!(
            write_struct(&mut ProviderMemory(&memory), TIMEOUT, &zero_timeout),
            0
        );
        let empty = libc::pollfd {
            revents: 0,
            ..untouched
        };
        assert_eq!(
            write_struct(&mut ProviderMemory(&memory), POLL_FD, &empty),
            0
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_ppoll,
                [POLL_FD, 1, TIMEOUT, 0, 0, 0],
            ),
            0,
            "zero-timeout ppoll remains a supported readiness probe",
        );

        let pid = state.pid;
        assert_eq!(
            result_of(kill_signal(
                &mut state,
                libc::SYS_kill as u64,
                &[pid as u64, libc::SIGUSR1 as u64, 0, 0, 0, 0],
            )),
            0,
        );
        assert_eq!(
            write_struct(&mut ProviderMemory(&memory), POLL_FD, &empty),
            0
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_ppoll,
                [POLL_FD, 1, TIMEOUT, 0, 0, 0],
            ),
            1,
        );
        let ready: libc::pollfd = read_struct(&memory, POLL_FD);
        assert_eq!(ready.fd, alias as libc::c_int);
        assert_ne!(ready.revents & libc::POLLIN, 0);
        assert_eq!(
            write_struct(&mut ProviderMemory(&memory), POLL_FD, &empty),
            0
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_ppoll,
                [POLL_FD, 1, 0, 0, 0, 0],
            ),
            1,
            "an unbounded ppoll may return already-published readiness",
        );
        let ready: libc::pollfd = read_struct(&memory, POLL_FD);
        assert_ne!(ready.revents & libc::POLLIN, 0);

        let epoll_fd = syscall_result(
            &mut memory,
            &mut state,
            libc::SYS_epoll_create1,
            [0, 0, 0, 0, 0, 0],
        );
        let event = libc::epoll_event {
            events: libc::EPOLLIN as u32,
            u64: 0x1234,
        };
        assert_eq!(
            write_struct(&mut ProviderMemory(&memory), EPOLL_EVENT, &event),
            0
        );
        for target in [signal_fd, alias] {
            assert_eq!(
                syscall_result(
                    &mut memory,
                    &mut state,
                    libc::SYS_epoll_ctl,
                    [
                        epoll_fd as u64,
                        libc::EPOLL_CTL_ADD as u64,
                        target as u64,
                        EPOLL_EVENT,
                        0,
                        0,
                    ],
                ),
                negative_errno(libc::ENOSYS),
                "a signalfd alias must not hide behind epoll before ppoll",
            );
        }
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_epoll_wait,
                [epoll_fd as u64, EPOLL_OUTPUT, 1, 0, 0, 0],
            ),
            0,
            "the refused epoll_ctl calls did not mutate the host epoll set",
        );
    }
    /// A ppoll that waits in the host on a signalfd ends when a signal the
    /// signalfd covers is queued for the waiting thread or for its process,
    /// and not for one it does not cover. The signalfd's eventfd keeper shows
    /// the process's queue; a signal for the waiting thread alone reaches it
    /// through its waiter.
    #[test]
    fn ppoll_on_a_virtual_signalfd_wakes_for_a_covered_signal() {
        const MASK: u64 = 0x100;
        const POLL_FD: u64 = 0x180;
        const TIMEOUT: u64 = 0x200;
        let root = TestDir::new();
        let mut leader = ElfExecutor::new(test_state(&root.0), false);
        for signal in [libc::SIGUSR1, libc::SIGUSR2] {
            test_block_signal(&mut leader.state, signal);
        }
        let mut worker = leader.thread_child(7).unwrap();
        let mut memory = GuestMemory::new(0, PAGE_SIZE as usize).unwrap();
        let mut mask = KernelSigset::default();
        mask.insert(libc::SIGUSR1);
        memory.write(MASK, &mask.to_bytes()).unwrap();
        let signal_fd = leader.execute(
            &SyscallRequest::new(
                libc::SYS_signalfd4 as u64,
                [
                    u64::MAX,
                    MASK,
                    KERNEL_SIGSET_SIZE as u64,
                    libc::SFD_NONBLOCK as u64,
                    0,
                    0,
                ],
            ),
            &memory,
        );
        assert_eq!(signal_fd, 3);
        let waiting = GuestMemory::new(0, PAGE_SIZE as usize).unwrap();
        let wait = |worker: &mut ElfExecutor| {
            let poll_fd = libc::pollfd {
                fd: signal_fd as libc::c_int,
                events: libc::POLLIN,
                revents: 0,
            };
            assert_eq!(
                write_struct(&mut ProviderMemory(&waiting), POLL_FD, &poll_fd),
                0
            );
            let long = libc::timespec {
                tv_sec: 20,
                tv_nsec: 0,
            };
            assert_eq!(
                write_struct(&mut ProviderMemory(&waiting), TIMEOUT, &long),
                0
            );
            let started = std::time::Instant::now();
            let ready = worker.execute(
                &SyscallRequest::new(libc::SYS_ppoll as u64, [POLL_FD, 1, TIMEOUT, 0, 0, 0]),
                &waiting,
            );
            let polled: libc::pollfd = read_struct(&waiting, POLL_FD);
            (ready, polled.revents, started.elapsed())
        };
        let settle = || std::thread::sleep(std::time::Duration::from_millis(100));
        let pid = leader.state.pid;

        // A signal for the waiting thread alone: one it does not cover leaves
        // it waiting, one it covers ends the wait.
        std::thread::scope(|scope| {
            let waiter = scope.spawn(|| wait(&mut worker));
            settle();
            for signal in [libc::SIGUSR2, libc::SIGUSR1] {
                assert_eq!(
                    leader.execute(
                        &SyscallRequest::new(
                            libc::SYS_tkill as u64,
                            [7, signal as u64, 0, 0, 0, 0]
                        ),
                        &memory,
                    ),
                    0
                );
                if signal == libc::SIGUSR2 {
                    settle();
                    assert!(!waiter.is_finished(), "an uncovered signal ends no wait");
                }
            }
            let (ready, revents, waited) = waiter.join().unwrap();
            assert_eq!((ready, revents), (1, libc::POLLIN));
            assert!(waited < std::time::Duration::from_secs(10));
        });
        assert_eq!(
            worker.execute(
                &SyscallRequest::new(
                    libc::SYS_read as u64,
                    [signal_fd as u64, 0x400, 128, 0, 0, 0]
                ),
                &memory,
            ),
            128
        );

        // A covered signal for the process ends the wait too.
        std::thread::scope(|scope| {
            let waiter = scope.spawn(|| wait(&mut worker));
            settle();
            queue_signal_event(
                &mut leader.state,
                event_for_process(libc::SIGUSR1, pid).unwrap(),
                true,
            )
            .unwrap();
            let (ready, revents, waited) = waiter.join().unwrap();
            assert_eq!((ready, revents), (1, libc::POLLIN));
            assert!(waited < std::time::Duration::from_secs(10));
        });
        assert_eq!(worker.state.thread_signals.lock().signalfd_waiter, None);
    }

    /// The signalfd operations this backend does not model fail with ENOSYS
    /// and a typed refusal that names them.
    #[test]
    fn unmodelled_signalfd_operations_are_refused_by_name() {
        const MASK: u64 = 0x100;
        const EVENT: u64 = 0x180;
        let root = TestDir::new();
        let mut executor = ElfExecutor::new(test_state(&root.0), false);
        test_block_signal(&mut executor.state, libc::SIGUSR1);
        let mut memory = GuestMemory::new(0, PAGE_SIZE as usize).unwrap();
        let mut mask = KernelSigset::default();
        mask.insert(libc::SIGUSR1);
        memory.write(MASK, &mask.to_bytes()).unwrap();
        let blocking = executor.execute(
            &SyscallRequest::new(
                libc::SYS_signalfd4 as u64,
                [u64::MAX, MASK, KERNEL_SIGSET_SIZE as u64, 0, 0, 0],
            ),
            &memory,
        );
        assert_eq!(blocking, 3);
        let mut refused = |number: libc::c_long, args: [u64; 6]| {
            let result = executor.execute(&SyscallRequest::new(number as u64, args), &memory);
            (
                result,
                executor
                    .take_unsupported_refusal()
                    .map(|refusal| (refusal.operation, refusal.diagnostic)),
            )
        };
        let named = |diagnostic| {
            (
                negative_errno(libc::ENOSYS),
                Some((reverie::UnsupportedOperation::Signalfd, diagnostic)),
            )
        };
        assert_eq!(
            refused(libc::SYS_read, [blocking as u64, 0x200, 128, 0, 0, 0]),
            named(SIGNALFD_WAITING_READ_REFUSAL),
        );
        let epoll = refused(libc::SYS_epoll_create1, [0; 6]).0;
        assert!(epoll >= 0);
        let event = libc::epoll_event {
            events: libc::EPOLLIN as u32,
            u64: 1,
        };
        assert_eq!(write_struct(&mut ProviderMemory(&memory), EVENT, &event), 0);
        assert_eq!(
            refused(
                libc::SYS_epoll_ctl,
                [
                    epoll as u64,
                    libc::EPOLL_CTL_ADD as u64,
                    blocking as u64,
                    EVENT,
                    0,
                    0
                ],
            ),
            named(SIGNALFD_EPOLL_REFUSAL),
        );
        // Answers Linux itself gives carry no refusal.
        assert_eq!(
            refused(libc::SYS_read, [blocking as u64, 0x200, 64, 0, 0, 0]),
            (negative_errno(libc::EINVAL), None),
        );
    }

    #[test]
    fn signalfd_backing_is_not_writable_seekable_or_pollout_visible() {
        const MASK: u64 = 0x100;
        const DATA: u64 = 0x180;
        const IOVEC: u64 = 0x200;
        const POLL_FD: u64 = 0x280;
        const FD_SET: u64 = 0x300;
        const TIMEVAL: u64 = 0x380;
        const TIMESPEC: u64 = 0x400;
        const PATH: u64 = 0x480;
        const LINK: u64 = 0x580;
        const INFO: u64 = 0x680;

        let root = TestDir::new();
        let mut state = test_state(&root.0);
        let mut memory = GuestMemory::new(0, (2 * PAGE_SIZE) as usize).unwrap();
        let mut mask = KernelSigset::default();
        mask.insert(libc::SIGUSR1);
        memory.write(MASK, &mask.to_bytes()).unwrap();
        test_block_signal(&mut state, libc::SIGUSR1);
        let signal_fd = syscall_result(
            &mut memory,
            &mut state,
            libc::SYS_signalfd4,
            [
                u64::MAX,
                MASK,
                KERNEL_SIGSET_SIZE as u64,
                libc::SFD_NONBLOCK as u64,
                0,
                0,
            ],
        );
        assert_eq!(signal_fd, 3);
        let alias = syscall_result(
            &mut memory,
            &mut state,
            libc::SYS_dup,
            [signal_fd as u64, 0, 0, 0, 0, 0],
        );
        assert_eq!(alias, 4);

        memory.write(DATA, &1_u64.to_ne_bytes()).unwrap();
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_write,
                [signal_fd as u64, DATA, 8, 0, 0, 0],
            ),
            negative_errno(libc::EINVAL),
        );
        for fd in [signal_fd, alias] {
            assert_eq!(
                syscall_result(
                    &mut memory,
                    &mut state,
                    libc::SYS_write,
                    [(1_u64 << 32) | fd as u64, DATA, 8, 0, 0, 0],
                ),
                negative_errno(libc::EINVAL),
                "upper descriptor bits must not expose the signalfd carrier",
            );
        }
        memory.write(DATA + 8, &2_u64.to_ne_bytes()).unwrap();
        let vectors = [
            libc::iovec {
                iov_base: DATA as usize as *mut libc::c_void,
                iov_len: 8,
            },
            libc::iovec {
                iov_base: (DATA + 8) as usize as *mut libc::c_void,
                iov_len: 8,
            },
        ];
        for (index, vector) in vectors.iter().enumerate() {
            assert_eq!(
                write_struct(
                    &mut ProviderMemory(&memory),
                    IOVEC + (index * std::mem::size_of::<libc::iovec>()) as u64,
                    vector,
                ),
                0,
            );
        }
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_writev,
                [alias as u64, IOVEC, 2, 0, 0, 0],
            ),
            negative_errno(libc::EINVAL),
        );
        // Linux validates the target type before copying socket payload
        // metadata. Do not expose the eventfd carrier through a bad pointer.
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_sendto,
                [alias as u64, u64::MAX, 8, 0, 0, 0],
            ),
            negative_errno(libc::ENOTSOCK),
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_sendmsg,
                [alias as u64, u64::MAX, 0, 0, 0, 0],
            ),
            negative_errno(libc::ENOTSOCK),
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_pwrite64,
                [alias as u64, DATA, 8, 0, 0, 0],
            ),
            negative_errno(libc::ESPIPE),
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_pwrite64,
                [alias as u64, DATA, 8, u64::MAX, 0, 0],
            ),
            negative_errno(libc::EINVAL),
        );

        let pollin = libc::pollfd {
            fd: alias as libc::c_int,
            events: libc::POLLIN,
            revents: libc::POLLPRI,
        };
        assert_eq!(
            write_struct(&mut ProviderMemory(&memory), POLL_FD, &pollin),
            0
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_poll,
                [POLL_FD, 1, 0, 0, 0, 0],
            ),
            0,
            "refused writes must not fabricate signalfd readability",
        );
        let observed: libc::pollfd = read_struct(&memory, POLL_FD);
        assert_eq!(observed.events, libc::POLLIN);
        assert_eq!(observed.revents, 0);
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_read,
                [alias as u64, INFO, 128, 0, 0, 0],
            ),
            negative_errno(libc::EAGAIN),
        );

        let pollout = libc::pollfd {
            fd: signal_fd as libc::c_int,
            events: libc::POLLOUT,
            revents: libc::POLLPRI,
        };
        assert_eq!(
            write_struct(&mut ProviderMemory(&memory), POLL_FD, &pollout),
            0
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_poll,
                [POLL_FD, 1, 0, 0, 0, 0],
            ),
            0,
        );
        let observed: libc::pollfd = read_struct(&memory, POLL_FD);
        assert_eq!(observed.events, libc::POLLOUT);
        assert_eq!(observed.revents, 0);

        let fd_bit = 1_u64 << signal_fd;
        memory.write(FD_SET, &fd_bit.to_ne_bytes()).unwrap();
        let zero_timeval = libc::timeval {
            tv_sec: 0,
            tv_usec: 0,
        };
        assert_eq!(
            write_struct(&mut ProviderMemory(&memory), TIMEVAL, &zero_timeval),
            0
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_select,
                [signal_fd as u64 + 1, 0, FD_SET, 0, TIMEVAL, 0],
            ),
            0,
        );
        assert_eq!(read_struct::<u64>(&memory, FD_SET), 0);

        // A signalfd never reports POLLOUT, so a ppoll that asks only for it
        // waits out its timeout, as on Linux, and reports nothing.
        let short_timeout = libc::timespec {
            tv_sec: 0,
            tv_nsec: 30_000_000,
        };
        assert_eq!(
            write_struct(&mut ProviderMemory(&memory), TIMESPEC, &short_timeout),
            0
        );
        assert_eq!(
            write_struct(&mut ProviderMemory(&memory), POLL_FD, &pollout),
            0
        );
        let started = std::time::Instant::now();
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_ppoll,
                [POLL_FD, 1, TIMESPEC, 0, 0, 0],
            ),
            0,
        );
        assert!(started.elapsed() >= std::time::Duration::from_millis(30));
        let observed: libc::pollfd = read_struct(&memory, POLL_FD);
        assert_eq!(observed.fd, pollout.fd);
        assert_eq!(observed.events, pollout.events);
        assert_eq!(observed.revents, 0);

        let pid = state.pid;
        assert_eq!(
            result_of(kill_signal(
                &mut state,
                libc::SYS_kill as u64,
                &[pid as u64, libc::SIGUSR1 as u64, 0, 0, 0, 0],
            )),
            0,
        );
        // A pending signal does not end a wait that asks only for POLLOUT.
        assert_eq!(
            write_struct(&mut ProviderMemory(&memory), POLL_FD, &pollout),
            0
        );
        let started = std::time::Instant::now();
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_ppoll,
                [POLL_FD, 1, TIMESPEC, 0, 0, 0],
            ),
            0,
        );
        assert!(started.elapsed() >= std::time::Duration::from_millis(30));
        let readable = libc::pollfd {
            fd: alias as libc::c_int,
            events: libc::POLLIN | libc::POLLOUT,
            revents: 0,
        };
        assert_eq!(
            write_struct(&mut ProviderMemory(&memory), POLL_FD, &readable),
            0
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_ppoll,
                [POLL_FD, 1, 0, 0, 0, 0],
            ),
            1,
        );
        let observed: libc::pollfd = read_struct(&memory, POLL_FD);
        assert_eq!(observed.events, readable.events);
        assert_eq!(observed.revents, libc::POLLIN);

        let event_fd = syscall_result(
            &mut memory,
            &mut state,
            libc::SYS_eventfd2,
            [0, libc::EFD_NONBLOCK as u64, 0, 0, 0, 0],
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_write,
                [event_fd as u64, DATA, 8, 0, 0, 0],
            ),
            8,
        );
        let event_pollout = libc::pollfd {
            fd: event_fd as libc::c_int,
            events: libc::POLLOUT,
            revents: 0,
        };
        assert_eq!(
            write_struct(&mut ProviderMemory(&memory), POLL_FD, &event_pollout),
            0
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_poll,
                [POLL_FD, 1, 0, 0, 0, 0],
            ),
            1,
        );
        let observed: libc::pollfd = read_struct(&memory, POLL_FD);
        assert_ne!(observed.revents & libc::POLLOUT, 0);

        let mmap_next = state.mmap_next;
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_mmap,
                [
                    0,
                    PAGE_SIZE,
                    libc::PROT_READ as u64,
                    libc::MAP_PRIVATE as u64,
                    alias as u64,
                    0,
                ],
            ),
            negative_errno(libc::ENODEV),
        );
        assert_eq!(state.mmap_next, mmap_next);

        let path = format!("/proc/self/fd/{alias}\0");
        memory.write(PATH, path.as_bytes()).unwrap();
        let target = b"anon_inode:[signalfd]";
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_readlink,
                [PATH, LINK, 64, 0, 0, 0],
            ),
            target.len() as i64,
        );
        let mut observed_target = vec![0; target.len()];
        memory.read(LINK, &mut observed_target).unwrap();
        assert_eq!(observed_target, target);
        let file_count = state.files.len();
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_openat,
                [libc::AT_FDCWD as u64, PATH, libc::O_PATH as u64, 0, 0, 0],
            ),
            negative_errno(libc::ENOSYS),
        );
        assert_eq!(state.files.len(), file_count);
    }

    #[test]
    fn signalfd_record_preserves_supported_posix_timer_metadata() {
        let signal = libc::SIGALRM;
        let timer_id = 17_i32;
        let overrun = 3_i32;
        let value = 0x1234_5678_9abc_def0_u64;
        let mut raw = [0_u8; reverie::SIGNAL_INFO_SIZE];
        raw[..4].copy_from_slice(&signal.to_ne_bytes());
        raw[8..12].copy_from_slice(&libc::SI_TIMER.to_ne_bytes());
        raw[16..20].copy_from_slice(&timer_id.to_ne_bytes());
        raw[20..24].copy_from_slice(&overrun.to_ne_bytes());
        raw[24..32].copy_from_slice(&value.to_ne_bytes());
        let event = reverie::SignalEvent::new(
            signal,
            raw,
            reverie::SignalTarget::Process {
                pid: reverie::Pid::from_raw(1),
            },
        )
        .unwrap();
        let bytes = encode_signalfd_siginfo(event);
        // SAFETY: encode_signalfd_siginfo returns one aligned-independent,
        // fully initialized ABI record and read_unaligned copies it by value.
        let info =
            unsafe { std::ptr::read_unaligned(bytes.as_ptr().cast::<libc::signalfd_siginfo>()) };
        assert_eq!(info.ssi_signo, signal as u32);
        assert_eq!(info.ssi_code, libc::SI_TIMER);
        assert_eq!(info.ssi_tid, timer_id as u32);
        assert_eq!(info.ssi_overrun, overrun as u32);
        assert_eq!(info.ssi_ptr, value);
        assert_eq!(info.ssi_int, value as i32);
    }

    #[test]
    fn signalfd_fault_consumes_but_short_record_preserves_pending_signal() {
        const MASK: u64 = 0x100;
        const IOVEC: u64 = 0x180;
        const VALID_INFO: u64 = 0x200;
        let boundary = PAGE_SIZE - 64;

        let root = TestDir::new();
        let mut state = test_state(&root.0);
        let pid = state.pid;
        test_block_signal(&mut state, libc::SIGUSR1);
        let mut memory = GuestMemory::new(0, (3 * PAGE_SIZE) as usize).unwrap();
        let mut mask = KernelSigset::default();
        mask.insert(libc::SIGUSR1);
        memory.write(MASK, &mask.to_bytes()).unwrap();
        let signal_fd = syscall_result(
            &mut memory,
            &mut state,
            libc::SYS_signalfd4,
            [
                u64::MAX,
                MASK,
                KERNEL_SIGSET_SIZE as u64,
                (libc::SFD_CLOEXEC | libc::SFD_NONBLOCK) as u64,
                0,
                0,
            ],
        );
        assert_eq!(signal_fd, 3);
        memory.map_user_range(0, PAGE_SIZE, false).unwrap();
        memory.map_user_range(PAGE_SIZE, PAGE_SIZE, true).unwrap();
        memory.enable_user_access();

        let queue = |state: &mut LoadedStaticElf| {
            assert_eq!(
                result_of(kill_signal(
                    state,
                    libc::SYS_kill as u64,
                    &[pid as u64, libc::SIGUSR1 as u64, 0, 0, 0, 0],
                )),
                0,
            );
        };
        queue(&mut state);
        let crossing = libc::iovec {
            iov_base: boundary as *mut libc::c_void,
            iov_len: 128,
        };
        assert_eq!(
            write_struct(&mut ProviderMemory(&memory), IOVEC, &crossing),
            0
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_readv,
                [signal_fd as u64, IOVEC, 1, 0, 0, 0],
            ),
            negative_errno(libc::EFAULT),
        );
        assert!(
            !state
                .process_signals
                .lock()
                .unwrap()
                .shared_pending
                .contains(libc::SIGUSR1)
        );

        queue(&mut state);
        let truncated = libc::iovec {
            iov_base: VALID_INFO as *mut libc::c_void,
            iov_len: 64,
        };
        assert_eq!(
            write_struct(&mut ProviderMemory(&memory), IOVEC, &truncated),
            0
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_readv,
                [signal_fd as u64, IOVEC, 1, 0, 0, 0],
            ),
            negative_errno(libc::EINVAL),
        );
        assert!(
            state
                .process_signals
                .lock()
                .unwrap()
                .shared_pending
                .contains(libc::SIGUSR1)
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_read,
                [signal_fd as u64, VALID_INFO, 128, 0, 0, 0],
            ),
            128,
        );
    }

    #[test]
    fn signalfd_vectored_io_uses_virtual_records_and_linux_error_ordering() {
        const MASK: u64 = 0x100;
        const IOV: u64 = 0x180;
        const FIRST: u64 = 0x300;
        const SECOND: u64 = 0x500;
        const CONTIGUOUS: u64 = 0x800;

        let root = TestDir::new();
        let mut state = test_state(&root.0);
        let pid = state.pid;
        let mut memory = GuestMemory::new(0, PAGE_SIZE as usize).unwrap();
        let mut mask = [0u8; KERNEL_SIGSET_SIZE];
        for signal in [libc::SIGUSR1, libc::SIGUSR2] {
            let bit = (signal - 1) as usize;
            mask[bit / 8] |= 1 << (bit % 8);
        }
        memory.write(MASK, &mask).unwrap();
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_rt_sigprocmask,
                [
                    libc::SIG_BLOCK as u64,
                    MASK,
                    0,
                    KERNEL_SIGSET_SIZE as u64,
                    0,
                    0,
                ],
            ),
            0
        );
        let signal_fd = syscall_result(
            &mut memory,
            &mut state,
            libc::SYS_signalfd4,
            [
                u64::MAX,
                MASK,
                KERNEL_SIGSET_SIZE as u64,
                (libc::SFD_CLOEXEC | libc::SFD_NONBLOCK) as u64,
                0,
                0,
            ],
        );
        assert_eq!(signal_fd, 3);

        // Explicit positioned calls reject this nonseekable descriptor before
        // importing an invalid iovec array. Current-position writes reject the
        // signalfd operation itself before importing that array.
        for number in [libc::SYS_preadv, libc::SYS_pwritev] {
            assert_eq!(
                syscall_result(
                    &mut memory,
                    &mut state,
                    number,
                    [signal_fd as u64, u64::MAX, 1, 0, 0, 0],
                ),
                negative_errno(libc::ESPIPE)
            );
        }
        for number in [libc::SYS_writev, libc::SYS_pwritev2] {
            assert_eq!(
                syscall_result(
                    &mut memory,
                    &mut state,
                    number,
                    [signal_fd as u64, u64::MAX, 1, u64::MAX, 0, 0],
                ),
                negative_errno(libc::EINVAL)
            );
        }
        write_guest_iovecs(&mut memory, IOV, &[(X86_64_GUEST_USER_LIMIT, 0)]);
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_preadv2,
                [signal_fd as u64, IOV, 1, u64::MAX, 0, 0],
            ),
            0
        );

        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_kill,
                [pid as u64, libc::SIGUSR1 as u64, 0, 0, 0, 0],
            ),
            0
        );
        memory.write(FIRST, &[0xa5; 64]).unwrap();
        memory.write(SECOND, &[0xa5; 64]).unwrap();
        write_guest_iovecs(&mut memory, IOV, &[(FIRST, 64), (SECOND, 64)]);
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_preadv2,
                [signal_fd as u64, IOV, 2, u64::MAX, 0, 0],
            ),
            std::mem::size_of::<libc::signalfd_siginfo>() as i64
        );
        let mut first = [0u8; 64];
        let mut second = [0u8; 64];
        memory.read(FIRST, &mut first).unwrap();
        memory.read(SECOND, &mut second).unwrap();
        assert_eq!(
            u32::from_ne_bytes(first[..4].try_into().unwrap()),
            libc::SIGUSR1 as u32
        );
        assert_eq!(second, [0; 64]);

        for signal in [libc::SIGUSR1, libc::SIGUSR2] {
            assert_eq!(
                syscall_result(
                    &mut memory,
                    &mut state,
                    libc::SYS_kill,
                    [pid as u64, signal as u64, 0, 0, 0, 0],
                ),
                0
            );
        }
        write_guest_iovecs(&mut memory, IOV, &[(CONTIGUOUS, 256)]);
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_readv,
                [signal_fd as u64, IOV, 1, 0, 0, 0],
            ),
            256
        );
        let first_info: libc::signalfd_siginfo = read_struct(&memory, CONTIGUOUS);
        let second_info: libc::signalfd_siginfo = read_struct(&memory, CONTIGUOUS + 128);
        assert_eq!(first_info.ssi_signo, libc::SIGUSR1 as u32);
        assert_eq!(second_info.ssi_signo, libc::SIGUSR2 as u32);
    }

    // AUTONOMOUS-BOT-IMPLEMENTED
    // TODO-HUMAN-REVIEW(rrnewton/reverie#315): regression for the rt_sigtimedwait
    // dispatch arm (was ENOSYS). Detcore injects the zero-timeout non-blocking
    // form, so the executor is a pure poll of the guest kernel's pending set.
    #[test]
    fn rt_sigpending_unions_both_domains_and_intersects_the_thread_mask() {
        const OUTPUT: u64 = 0x100;
        let root = TestDir::new();
        let mut state = test_state(&root.0);
        let pid = state.pid;
        let tid = state.tid;
        let mut memory = GuestMemory::new(0, PAGE_SIZE as usize).unwrap();
        test_block_signal(&mut state, libc::SIGUSR1);
        test_block_signal(&mut state, libc::SIGUSR2);
        queue_signal_event(
            &mut state,
            event_for_thread(libc::SIGUSR1, pid, tid).unwrap(),
            false,
        )
        .unwrap();
        queue_signal_event(
            &mut state,
            event_for_process(libc::SIGUSR2, pid).unwrap(),
            true,
        )
        .unwrap();

        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_rt_sigpending,
                [u64::MAX, (KERNEL_SIGSET_SIZE + 1) as u64, 0, 0, 0, 0],
            ),
            negative_errno(libc::EINVAL),
            "sigset width is validated before copyout",
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_rt_sigpending,
                [OUTPUT, KERNEL_SIGSET_SIZE as u64, 0, 0, 0, 0],
            ),
            0,
        );
        let pending =
            KernelSigset::from_bytes(read_guest_bytes(&ProviderMemory(&memory), OUTPUT).unwrap());
        assert!(pending.contains(libc::SIGUSR1));
        assert!(pending.contains(libc::SIGUSR2));

        state.thread_signals.lock().blocked.remove(libc::SIGUSR2);
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_rt_sigpending,
                [OUTPUT, KERNEL_SIGSET_SIZE as u64, 0, 0, 0, 0],
            ),
            0,
        );
        let pending =
            KernelSigset::from_bytes(read_guest_bytes(&ProviderMemory(&memory), OUTPUT).unwrap());
        assert!(pending.contains(libc::SIGUSR1));
        assert!(!pending.contains(libc::SIGUSR2));
    }

    #[test]
    fn ignored_disposition_discards_single_thread_pending_domains_and_readiness() {
        const ACTION: u64 = 0x100;
        const MASK: u64 = 0x140;
        const POLL_FD: u64 = 0x180;
        let root = TestDir::new();
        let mut state = test_state(&root.0);
        let pid = state.pid;
        let tid = state.tid;
        let mut memory = GuestMemory::new(0, PAGE_SIZE as usize).unwrap();
        let ignored = KernelSigaction {
            handler: libc::SIG_IGN as u64,
            ..KernelSigaction::default()
        };
        memory.write(ACTION, &ignored.encode()).unwrap();

        queue_signal_event(
            &mut state,
            event_for_thread(libc::SIGUSR1, pid, tid).unwrap(),
            false,
        )
        .unwrap();
        queue_signal_event(
            &mut state,
            event_for_process(libc::SIGUSR1, pid).unwrap(),
            true,
        )
        .unwrap();
        assert_eq!(
            rt_sigaction(
                &mut memory,
                &mut state,
                &[
                    libc::SIGUSR1 as u64,
                    ACTION,
                    0,
                    KERNEL_SIGSET_SIZE as u64,
                    0,
                    0,
                ],
            ),
            0,
        );
        assert!(state.thread_signals.lock().pending.is_empty());
        assert!(
            state
                .process_signals
                .lock()
                .unwrap()
                .shared_pending
                .is_empty()
        );

        let mut ready_state = test_state(&root.0);
        test_block_signal(&mut ready_state, libc::SIGUSR1);
        let mut mask = KernelSigset::default();
        mask.insert(libc::SIGUSR1);
        memory.write(MASK, &mask.to_bytes()).unwrap();
        let signal_fd = syscall_result(
            &mut memory,
            &mut ready_state,
            libc::SYS_signalfd4,
            [
                u64::MAX,
                MASK,
                KERNEL_SIGSET_SIZE as u64,
                (libc::SFD_CLOEXEC | libc::SFD_NONBLOCK) as u64,
                0,
                0,
            ],
        );
        let ready_pid = ready_state.pid;
        queue_signal_event(
            &mut ready_state,
            event_for_process(libc::SIGUSR1, ready_pid).unwrap(),
            true,
        )
        .unwrap();
        let poll_fd = libc::pollfd {
            fd: signal_fd as libc::c_int,
            events: libc::POLLIN,
            revents: 0,
        };
        assert_eq!(
            write_struct(&mut ProviderMemory(&memory), POLL_FD, &poll_fd),
            0
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut ready_state,
                libc::SYS_poll,
                [POLL_FD, 1, 0, 0, 0, 0],
            ),
            1,
        );
        assert_eq!(
            rt_sigaction(
                &mut memory,
                &mut ready_state,
                &[
                    libc::SIGUSR1 as u64,
                    ACTION,
                    0,
                    KERNEL_SIGSET_SIZE as u64,
                    0,
                    0,
                ],
            ),
            0,
        );
        assert_eq!(
            write_struct(&mut ProviderMemory(&memory), POLL_FD, &poll_fd),
            0
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut ready_state,
                libc::SYS_poll,
                [POLL_FD, 1, 0, 0, 0, 0],
            ),
            0,
            "discarding shared pending state must clear signalfd readiness",
        );
    }

    #[test]
    fn ignored_disposition_with_live_sibling_invalidates_only_older_pending_events() {
        const ACTION: u64 = 0x100;
        const SET: u64 = 0x140;
        const PENDING: u64 = 0x180;
        let root = TestDir::new();
        let mut leader = ElfExecutor::new(test_state(&root.0), false);
        let mut worker = leader.thread_child(7).unwrap();
        let pid = leader.state.pid;
        let signal = libc::SIGUSR1;
        test_install_signal_action(&leader.state, signal, custom_action(0x4000));
        test_block_signal(&mut worker.state, signal);

        let marked_event = |marker| {
            let event = event_for_thread(signal, pid, 7).unwrap();
            let mut info = event.siginfo();
            info[127] = marker;
            reverie::SignalEvent::new(signal, info, event.target()).unwrap()
        };
        queue_signal_event(&mut worker.state, marked_event(0x11), false).unwrap();
        queue_signal_event(
            &mut leader.state,
            event_for_process(signal, pid).unwrap(),
            true,
        )
        .unwrap();

        let mut memory = GuestMemory::new(0, PAGE_SIZE as usize).unwrap();
        let mut selected = KernelSigset::default();
        selected.insert(signal);
        memory.write(SET, &selected.to_bytes()).unwrap();
        memory
            .write(
                ACTION,
                &KernelSigaction {
                    handler: libc::SIG_IGN as u64,
                    ..KernelSigaction::default()
                }
                .encode(),
            )
            .unwrap();
        assert_eq!(
            rt_sigaction(
                &mut memory,
                &mut leader.state,
                &[signal as u64, ACTION, 0, KERNEL_SIGSET_SIZE as u64, 0, 0,],
            ),
            0,
        );
        assert_eq!(leader.signal_disposition(signal), SignalDisposition::Ignore);
        assert!(
            worker.state.thread_signals.lock().pending.contains(signal),
            "a sibling's old row remains physically private",
        );
        assert!(
            !leader
                .state
                .process_signals
                .lock()
                .unwrap()
                .shared_pending
                .contains(signal),
            "the reachable shared row is removed eagerly",
        );
        assert_eq!(
            rt_sigpending(
                &mut memory,
                &worker.state,
                &[PENDING, KERNEL_SIGSET_SIZE as u64, 0, 0, 0, 0],
            ),
            0,
        );
        assert!(
            !KernelSigset::from_bytes(read_guest_bytes(&ProviderMemory(&memory), PENDING).unwrap())
                .contains(signal),
            "the sibling's stale row must not be observable through rt_sigpending",
        );
        assert_eq!(
            rt_sigtimedwait(
                &mut memory,
                &mut worker.state,
                &[SET, 0, 0, KERNEL_SIGSET_SIZE as u64, 0, 0],
            ),
            negative_errno(libc::EAGAIN),
            "the sibling's stale row must not be selectable by rt_sigtimedwait",
        );
        worker.state.thread_signals.lock().blocked.remove(signal);
        assert!(!worker.has_eligible_pending_signal());
        assert_eq!(worker.take_pending_signal(), None);

        // Linux retains a blocked signal generated while its disposition is
        // ignored because that disposition may change before the signal is
        // unblocked. This new event replaces the stale coalesced row.
        test_block_signal(&mut worker.state, signal);
        queue_signal_event(&mut worker.state, marked_event(0x22), false).unwrap();
        assert_eq!(
            rt_sigpending(
                &mut memory,
                &worker.state,
                &[PENDING, KERNEL_SIGSET_SIZE as u64, 0, 0, 0, 0],
            ),
            0,
        );
        assert!(
            KernelSigset::from_bytes(read_guest_bytes(&ProviderMemory(&memory), PENDING).unwrap())
                .contains(signal)
        );

        memory.write(ACTION, &custom_action(0x5000)).unwrap();
        assert_eq!(
            rt_sigaction(
                &mut memory,
                &mut leader.state,
                &[signal as u64, ACTION, 0, KERNEL_SIGSET_SIZE as u64, 0, 0,],
            ),
            0,
        );
        worker.state.thread_signals.lock().blocked.remove(signal);
        let delivered = worker
            .take_pending_signal()
            .expect("the post-ignore blocked event was lost on handler reinstall");
        assert_eq!(delivered.event.siginfo()[127], 0x22);
        assert_eq!(worker.take_pending_signal(), None);
    }

    #[test]
    fn default_ignored_sigaction_with_live_sibling_invalidates_older_pending() {
        const ACTION: u64 = 0x100;
        let root = TestDir::new();
        let mut leader = ElfExecutor::new(test_state(&root.0), false);
        let mut worker = leader.thread_child(7).unwrap();
        let signal = libc::SIGWINCH;
        test_block_signal(&mut worker.state, signal);
        queue_signal_event(
            &mut worker.state,
            event_for_thread(signal, leader.state.pid, 7).unwrap(),
            false,
        )
        .unwrap();
        let mut memory = GuestMemory::new(0, PAGE_SIZE as usize).unwrap();
        memory
            .write(ACTION, &KernelSigaction::default().encode())
            .unwrap();

        for ignored in [libc::SIGCHLD, libc::SIGURG, libc::SIGWINCH, libc::SIGCONT] {
            assert_eq!(
                default_signal_disposition(ignored),
                SignalDisposition::Ignore,
            );
        }
        assert_eq!(
            rt_sigaction(
                &mut memory,
                &mut leader.state,
                &[signal as u64, ACTION, 0, KERNEL_SIGSET_SIZE as u64, 0, 0,],
            ),
            0,
        );
        worker.state.thread_signals.lock().blocked.remove(signal);
        assert_eq!(worker.take_pending_signal(), None);
    }

    #[test]
    fn pending_generation_overflow_fails_before_sigaction_mutation() {
        const ACTION: u64 = 0x100;
        let root = TestDir::new();
        let mut state = test_state(&root.0);
        let signal = libc::SIGUSR1;
        let pid = state.pid;
        let tid = state.tid;
        test_install_signal_action(&state, signal, custom_action(0x4000));
        state.process_signals.lock().unwrap().pending_generations[signal as usize] = u64::MAX;
        queue_signal_event(
            &mut state,
            event_for_thread(signal, pid, tid).unwrap(),
            false,
        )
        .unwrap();
        let mut memory = GuestMemory::new(0, PAGE_SIZE as usize).unwrap();
        memory
            .write(
                ACTION,
                &KernelSigaction {
                    handler: libc::SIG_IGN as u64,
                    ..KernelSigaction::default()
                }
                .encode(),
            )
            .unwrap();
        assert_eq!(
            rt_sigaction(
                &mut memory,
                &mut state,
                &[signal as u64, ACTION, 0, KERNEL_SIGSET_SIZE as u64, 0, 0,],
            ),
            negative_errno(libc::EOVERFLOW),
        );
        assert_eq!(
            signal_disposition(&state, signal),
            SignalDisposition::Handled
        );
        assert_eq!(
            state
                .process_signals
                .lock()
                .unwrap()
                .pending_generation(signal),
            u64::MAX,
        );
        assert!(
            state.thread_signals.lock().pending.contains(signal),
            "overflow must not discard the existing pending event",
        );
        assert!(ElfExecutor::new(state, false).has_eligible_pending_signal());
    }

    #[test]
    fn rt_sigtimedwait_polls_pending_and_reports_eagain_when_empty() {
        const SET: u64 = 0x100;
        const INFO: u64 = 0x180;

        let root = TestDir::new();
        let mut state = test_state(&root.0);
        let pid = state.pid;
        let mut memory = GuestMemory::new(0, PAGE_SIZE as usize).unwrap();

        // Wait set selecting SIGUSR1.
        let mut set = [0u8; KERNEL_SIGSET_SIZE];
        let bit = (libc::SIGUSR1 - 1) as usize;
        set[bit / 8] |= 1 << (bit % 8);
        memory.write(SET, &set).unwrap();

        // A wrong sigsetsize is rejected before touching guest memory, matching
        // the kernel's EINVAL for a mismatched kernel sigset width.
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_rt_sigtimedwait,
                [SET, INFO, 0, (KERNEL_SIGSET_SIZE + 1) as u64, 0, 0],
            ),
            negative_errno(libc::EINVAL)
        );

        // With nothing pending, a zero-timeout wait returns EAGAIN. This is the
        // exact divergence the change fixes: the KVM executor previously fell
        // through to ENOSYS while the golden ptrace backend returns EAGAIN.
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_rt_sigtimedwait,
                [SET, INFO, 0, KERNEL_SIGSET_SIZE as u64, 0, 0],
            ),
            negative_errno(libc::EAGAIN)
        );

        // Block SIGUSR1 and self-queue it, then the wait consumes it, returns the
        // signal number, and fills the kill(2) siginfo union (si_signo, si_pid).
        test_block_signal(&mut state, libc::SIGUSR1);
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_kill,
                [pid as u64, libc::SIGUSR1 as u64, 0, 0, 0, 0],
            ),
            0
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_rt_sigtimedwait,
                [SET, INFO, 0, KERNEL_SIGSET_SIZE as u64, 0, 0],
            ),
            i64::from(libc::SIGUSR1)
        );
        let signo = i32::from_ne_bytes(read_struct::<[u8; 4]>(&memory, INFO));
        let si_pid = i32::from_ne_bytes(read_struct::<[u8; 4]>(&memory, INFO + 16));
        assert_eq!(signo, libc::SIGUSR1);
        assert_eq!(si_pid, state.pid);

        // The signal was dequeued: a second poll drains to EAGAIN again.
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_rt_sigtimedwait,
                [SET, INFO, 0, KERNEL_SIGSET_SIZE as u64, 0, 0],
            ),
            negative_errno(libc::EAGAIN)
        );
    }

    fn test_sigset(signals: &[libc::c_int]) -> KernelSigset {
        let mut set = KernelSigset::default();
        for &signal in signals {
            set.insert(signal);
        }
        set
    }

    fn test_catch_signal(state: &LoadedStaticElf, signal: libc::c_int) {
        test_install_signal_action(
            state,
            signal,
            KernelSigaction {
                handler: 0x1000,
                flags: crate::signal::SA_RESTORER,
                restorer: 0x2000,
                mask: KernelSigset::default(),
            }
            .encode(),
        );
    }

    #[test]
    fn rt_sigsuspend_ends_at_once_for_a_pending_signal_its_mask_admits() {
        const MASK: u64 = 0x100;
        const BAD: u64 = 0x00f0_0000;

        let root = TestDir::new();
        let mut state = test_state(&root.0);
        let (pid, tid) = (state.pid, state.tid);
        let mut memory = GuestMemory::new(0, PAGE_SIZE as usize).unwrap();
        let own = test_sigset(&[libc::SIGUSR1, libc::SIGUSR2]);
        state.thread_signals.lock().blocked = own;
        test_catch_signal(&state, libc::SIGUSR1);
        // The temporary mask names SIGKILL; Linux removes it before installing.
        memory
            .write(
                MASK,
                &test_sigset(&[libc::SIGTERM, libc::SIGKILL]).to_bytes(),
            )
            .unwrap();
        let suspend = |memory: &mut GuestMemory, state: &mut LoadedStaticElf, args| {
            syscall_result(memory, state, libc::SYS_rt_sigsuspend, args)
        };

        // Size before the mask pointer, as Linux validates them.
        assert_eq!(
            suspend(&mut memory, &mut state, [BAD, 4, 0, 0, 0, 0]),
            negative_errno(libc::EINVAL)
        );
        assert_eq!(
            suspend(&mut memory, &mut state, [BAD, 8, 0, 0, 0, 0]),
            negative_errno(libc::EFAULT)
        );
        // Nothing pending: the wait itself stays refused, mask untouched.
        assert_eq!(
            suspend(&mut memory, &mut state, [MASK, 8, 0, 0, 0, 0]),
            negative_errno(libc::ENOSYS)
        );
        assert_eq!(state.thread_signals.lock().blocked, own);
        assert_eq!(state.thread_signals.lock().saved_sigmask, None);

        // A caught signal the own mask blocks and the temporary mask admits.
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_tgkill,
                [pid as u64, tid as u64, libc::SIGUSR1 as u64, 0, 0, 0],
            ),
            0
        );
        assert_eq!(
            suspend(&mut memory, &mut state, [MASK, 8, 0, 0, 0, 0]),
            negative_errno(libc::EINTR)
        );
        {
            let thread_signals = state.thread_signals.lock();
            assert_eq!(thread_signals.blocked, test_sigset(&[libc::SIGTERM]));
            assert_eq!(thread_signals.saved_sigmask, Some(own));
            // Left for the return boundary to deliver.
            assert!(thread_signals.pending.contains(libc::SIGUSR1));
        }

        // The frame saves the own mask, the handler runs under the temporary
        // mask plus its signal, and nothing remains saved.
        let mut executor = ElfExecutor::new(state, false);
        assert_eq!(executor.frame_signal_mask(), own);
        let pending = executor
            .take_pending_signal_for_delivery()
            .unwrap()
            .expect("the admitted signal is selected under the temporary mask");
        assert_eq!(pending.event.signal(), libc::SIGUSR1);
        let action = executor.signal_action(libc::SIGUSR1);
        executor.enter_signal_handler(pending, action, false);
        {
            let thread_signals = executor.state.thread_signals.lock();
            assert_eq!(
                thread_signals.blocked,
                test_sigset(&[libc::SIGTERM, libc::SIGUSR1])
            );
            assert_eq!(thread_signals.saved_sigmask, None);
        }
        assert_eq!(
            executor.frame_signal_mask(),
            test_sigset(&[libc::SIGTERM, libc::SIGUSR1])
        );
    }

    #[test]
    fn rt_sigsuspend_refuses_a_pending_signal_linux_would_discard() {
        const MASK: u64 = 0x100;

        let root = TestDir::new();
        let mut state = test_state(&root.0);
        let pid = state.pid;
        let mut memory = GuestMemory::new(0, PAGE_SIZE as usize).unwrap();
        let own = test_sigset(&[libc::SIGURG]);
        state.thread_signals.lock().blocked = own;
        memory.write(MASK, &[0; KERNEL_SIGSET_SIZE]).unwrap();
        // SIGURG's default action discards it; Linux would restart the wait.
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_kill,
                [pid as u64, libc::SIGURG as u64, 0, 0, 0, 0],
            ),
            0
        );
        let before = state.thread_signals.lock().clone();
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_rt_sigsuspend,
                [MASK, 8, 0, 0, 0, 0],
            ),
            negative_errno(libc::ENOSYS)
        );
        assert_eq!(*state.thread_signals.lock(), before);
    }

    #[test]
    fn a_boundary_without_a_handler_restores_the_saved_mask() {
        let root = TestDir::new();
        let state = test_state(&root.0);
        let own = test_sigset(&[libc::SIGUSR1]);
        let temporary = test_sigset(&[libc::SIGTERM]);
        {
            let mut thread_signals = state.thread_signals.lock();
            thread_signals.blocked = own;
        }
        install_temporary_mask_for_delivery(&state, temporary);
        // A second install keeps the first saved mask, as Linux's saved_sigmask.
        install_temporary_mask_for_delivery(&state, temporary);
        assert_eq!(state.thread_signals.lock().saved_sigmask, Some(own));
        let mut executor = ElfExecutor::new(state, false);
        assert_eq!(executor.signal_mask(), temporary);
        assert_eq!(executor.frame_signal_mask(), own);
        executor.restore_saved_signal_mask();
        assert_eq!(executor.signal_mask(), own);
        assert_eq!(executor.state.thread_signals.lock().saved_sigmask, None);
        executor.restore_saved_signal_mask();
        assert_eq!(executor.signal_mask(), own);
    }

    #[test]
    fn masked_pselect6_probe_delivers_under_its_temporary_mask() {
        const TIMEOUT: u64 = 0x100;
        const OUTER: u64 = 0x140;
        const MASK: u64 = 0x180;

        let root = TestDir::new();
        let mut state = test_state(&root.0);
        let (pid, tid) = (state.pid, state.tid);
        let mut memory = GuestMemory::new(0, PAGE_SIZE as usize).unwrap();
        let own = test_sigset(&[libc::SIGUSR1]);
        state.thread_signals.lock().blocked = own;
        test_catch_signal(&state, libc::SIGUSR1);
        assert_eq!(
            write_struct(
                &mut ProviderMemory(&memory),
                TIMEOUT,
                &libc::timespec {
                    tv_sec: 0,
                    tv_nsec: 0
                }
            ),
            0
        );
        assert_eq!(
            write_struct(
                &mut ProviderMemory(&memory),
                OUTER,
                &Pselect6SigmaskArg {
                    sigmask: MASK,
                    sigsetsize: KERNEL_SIGSET_SIZE as u64,
                }
            ),
            0
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_tgkill,
                [pid as u64, tid as u64, libc::SIGUSR1 as u64, 0, 0, 0],
            ),
            0
        );

        // A temporary mask that also blocks it: a zero result, own mask kept.
        memory.write(MASK, &own.to_bytes()).unwrap();
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_pselect6,
                [0, 0, 0, 0, TIMEOUT, OUTER],
            ),
            0
        );
        assert_eq!(state.thread_signals.lock().blocked, own);
        assert_eq!(state.thread_signals.lock().saved_sigmask, None);

        // One that admits it: EINTR, delivered under the temporary mask.
        let temporary = test_sigset(&[libc::SIGTERM]);
        memory.write(MASK, &temporary.to_bytes()).unwrap();
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_pselect6,
                [0, 0, 0, 0, TIMEOUT, OUTER],
            ),
            negative_errno(libc::EINTR)
        );
        let thread_signals = state.thread_signals.lock();
        assert_eq!(thread_signals.blocked, temporary);
        assert_eq!(thread_signals.saved_sigmask, Some(own));
        assert!(thread_signals.pending.contains(libc::SIGUSR1));
    }

    #[test]
    fn standard_input_access_checks_precede_memory_validation() {
        const PAYLOAD: u64 = 0x100;

        let root = TestDir::new();
        let path = root.0.join("stdin");
        let mut state = test_state(&root.0);
        let mut memory = GuestMemory::new(0, PAGE_SIZE as usize).unwrap();
        memory.write(PAYLOAD, b"x").unwrap();

        state.stdin = Some(std::fs::File::create(&path).unwrap());
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_read,
                [libc::STDIN_FILENO as u64, u64::MAX, 0, 0, 0, 0],
            ),
            negative_errno(libc::EBADF)
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_read,
                [libc::STDIN_FILENO as u64, u64::MAX, 1, 0, 0, 0],
            ),
            negative_errno(libc::EBADF)
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_write,
                [libc::STDIN_FILENO as u64, PAYLOAD, 1, 0, 0, 0],
            ),
            1
        );
        drop(state);
        assert_eq!(std::fs::read(&path).unwrap(), b"x");

        let mut state = test_state(&root.0);
        state.stdin = Some(std::fs::File::open(&path).unwrap());
        for length in [0, 1] {
            assert_eq!(
                syscall_result(
                    &mut memory,
                    &mut state,
                    libc::SYS_write,
                    [libc::STDIN_FILENO as u64, u64::MAX, length, 0, 0, 0],
                ),
                negative_errno(libc::EBADF)
            );
        }
    }

    #[test]
    fn positioned_write_seek_truncate_and_sync_round_trip() {
        const HIGH_WORD: u64 = 0x5a5a_5a5a_0000_0000;
        const SIGNED_LOW_WORD: u64 = HIGH_WORD | (1 << 31);
        const PATH_ADDRESS: u64 = 0x100;
        const PAYLOAD_ADDRESS: u64 = 0x200;
        const PATCH_ADDRESS: u64 = 0x300;
        const READ_ADDRESS: u64 = 0x400;

        let root = TestDir::new();
        let mut state = test_state(&root.0);
        let mut memory = GuestMemory::new(0, PAGE_SIZE as usize).unwrap();
        memory.write(PATH_ADDRESS, b"positioned\0").unwrap();
        memory.write(PAYLOAD_ADDRESS, b"abcdef").unwrap();
        memory.write(PATCH_ADDRESS, b"XY").unwrap();

        let fd = syscall_result(
            &mut memory,
            &mut state,
            libc::SYS_open,
            [
                PATH_ADDRESS,
                (libc::O_CREAT | libc::O_TRUNC | libc::O_RDWR) as u64,
                0o600,
                0,
                0,
                0,
            ],
        );
        assert_eq!(fd, 3);
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_write,
                [fd as u64, PAYLOAD_ADDRESS, 6, 0, 0, 0],
            ),
            6
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_pwrite64,
                [fd as u64, PATCH_ADDRESS, 2, 2, 0, 0],
            ),
            2
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_lseek,
                [fd as u64, 0, libc::SEEK_CUR as u64, 0, 0, 0],
            ),
            6,
            "pwrite64 must not change the shared file position"
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_lseek,
                [fd as u64, 0, libc::SEEK_SET as u64, 0, 0, 0],
            ),
            0
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_read,
                [fd as u64, READ_ADDRESS, 6, 0, 0, 0],
            ),
            6
        );
        let mut actual = [0; 6];
        memory.read(READ_ADDRESS, &mut actual).unwrap();
        assert_eq!(&actual, b"abXYef");
        for syscall in [libc::SYS_fdatasync, libc::SYS_fsync] {
            assert_eq!(
                syscall_result(
                    &mut memory,
                    &mut state,
                    syscall,
                    [HIGH_WORD | fd as u64, 0, 0, 0, 0, 0],
                ),
                0
            );
            assert_eq!(
                syscall_result(
                    &mut memory,
                    &mut state,
                    syscall,
                    [SIGNED_LOW_WORD | fd as u64, 0, 0, 0, 0, 0],
                ),
                negative_errno(libc::EBADF),
                "a set low-word sign bit must not alias a live descriptor"
            );
        }
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_readahead,
                [HIGH_WORD | fd as u64, 0, 4096, 0, 0, 0],
            ),
            0
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_readahead,
                [HIGH_WORD | fd as u64, u64::MAX, 1, 0, 0, 0],
            ),
            negative_errno(libc::EINVAL),
            "offset validation follows low-word descriptor decoding"
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_readahead,
                [SIGNED_LOW_WORD | fd as u64, 0, 1, 0, 0, 0],
            ),
            negative_errno(libc::EBADF)
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_sync_file_range,
                [
                    HIGH_WORD | fd as u64,
                    0,
                    4096,
                    libc::SYNC_FILE_RANGE_WRITE as u64,
                    0,
                    0,
                ],
            ),
            0
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_readahead,
                [u64::MAX, 0, 1, 0, 0, 0],
            ),
            negative_errno(libc::EBADF)
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_sync_file_range,
                [
                    HIGH_WORD | fd as u64,
                    0,
                    1,
                    (libc::SYNC_FILE_RANGE_WAIT_BEFORE
                        | libc::SYNC_FILE_RANGE_WRITE
                        | libc::SYNC_FILE_RANGE_WAIT_AFTER
                        | 8) as u64,
                    0,
                    0,
                ],
            ),
            negative_errno(libc::EINVAL)
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_sync_file_range,
                [
                    SIGNED_LOW_WORD | fd as u64,
                    0,
                    1,
                    libc::SYNC_FILE_RANGE_WRITE as u64,
                    0,
                    0,
                ],
            ),
            negative_errno(libc::EBADF)
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_ftruncate,
                [fd as u64, 4, 0, 0, 0, 0],
            ),
            0
        );
        assert_eq!(std::fs::read(root.0.join("positioned")).unwrap(), b"abXY");

        let fallocate_result = syscall_result(
            &mut memory,
            &mut state,
            libc::SYS_fallocate,
            [HIGH_WORD | fd as u64, 0, 0, 8192, 0, 0],
        );
        assert!(
            fallocate_result == 0 || fallocate_result == negative_errno(libc::EOPNOTSUPP),
            "fallocate returned {fallocate_result}"
        );
        if fallocate_result == 0 {
            assert_eq!(
                std::fs::metadata(root.0.join("positioned")).unwrap().len(),
                8192
            );
        }
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_truncate,
                [PATH_ADDRESS, 2, 0, 0, 0, 0],
            ),
            0
        );
        assert_eq!(std::fs::read(root.0.join("positioned")).unwrap(), b"ab");
        assert_eq!(
            state.files.len(),
            1,
            "truncate must not change the guest fd table"
        );

        state
            .files
            .insert(9, std::fs::File::open(root.0.join("positioned")).unwrap());
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_fallocate,
                [HIGH_WORD | 9, 0, 0, 0, 0, 0],
            ),
            negative_errno(libc::EINVAL),
            "range validation precedes writable-access validation"
        );
        for mode in [
            libc::FALLOC_FL_PUNCH_HOLE,
            libc::FALLOC_FL_COLLAPSE_RANGE | libc::FALLOC_FL_KEEP_SIZE,
            libc::FALLOC_FL_INSERT_RANGE | libc::FALLOC_FL_KEEP_SIZE,
            FALLOC_FL_WRITE_ZEROES | libc::FALLOC_FL_KEEP_SIZE,
        ] {
            assert_eq!(
                syscall_result(
                    &mut memory,
                    &mut state,
                    libc::SYS_fallocate,
                    [HIGH_WORD | 9, mode as u64, 0, 1, 0, 0],
                ),
                negative_errno(libc::EOPNOTSUPP),
                "invalid mode combination validation precedes writable access"
            );
        }
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_fallocate,
                [HIGH_WORD | 9, FALLOC_FL_WRITE_ZEROES as u64, 0, 1, 0, 0],
            ),
            negative_errno(libc::EBADF),
            "valid write-zeroes mode reaches writable-access validation"
        );

        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_fallocate,
                [HIGH_WORD | 9, 1_u64 << 30, 0, 1, 0, 0],
            ),
            negative_errno(libc::EOPNOTSUPP),
            "unknown mode validation precedes writable-access validation"
        );
        state.files.remove(&9);

        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_fallocate,
                [SIGNED_LOW_WORD | fd as u64, 0, 0, 1, 0, 0],
            ),
            negative_errno(libc::EBADF)
        );

        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_truncate,
                [u64::MAX, u64::MAX, 0, 0, 0, 0],
            ),
            negative_errno(libc::EINVAL),
            "negative length validation precedes path access"
        );
        write_c_string(&mut memory, PATH_ADDRESS, "");
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_truncate,
                [PATH_ADDRESS, u64::MAX, 0, 0, 0, 0],
            ),
            negative_errno(libc::EINVAL)
        );

        let fifo = root.0.join("fifo");
        let fifo_c = CString::new(fifo.as_os_str().as_bytes()).unwrap();
        // SAFETY: fifo_c is NUL-terminated and names a path in the test directory.
        assert_eq!(unsafe { libc::mkfifo(fifo_c.as_ptr(), 0o600) }, 0);
        write_c_string(&mut memory, PATH_ADDRESS, "fifo");
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_truncate,
                [PATH_ADDRESS, 0, 0, 0, 0, 0],
            ),
            negative_errno(libc::EINVAL),
            "path truncate must not open a FIFO and block"
        );

        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_fallocate,
                [99, 0, 0, 1, 0, 0],
            ),
            negative_errno(libc::EBADF)
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_fallocate,
                [fd as u64, 0, u64::MAX, 1, 0, 0],
            ),
            negative_errno(libc::EINVAL)
        );

        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_pwrite64,
                [99, u64::MAX, 1, 0, 0, 0],
            ),
            negative_errno(libc::EBADF)
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_ftruncate,
                [fd as u64, u64::MAX, 0, 0, 0, 0],
            ),
            negative_errno(libc::EINVAL)
        );
    }

    #[test]
    fn mremap_grows_moves_and_shrinks_guest_ranges() {
        let root = TestDir::new();
        let mut state = test_state(&root.0);
        let memory_size = BOOT_RESERVED_END + 16 * PAGE_SIZE;
        let mut memory = GuestMemory::new(0, memory_size as usize).unwrap();
        state.mmap_next = BOOT_RESERVED_END + PAGE_SIZE;
        state.mmap_limit = memory_size;
        let mmap_args = [
            0,
            PAGE_SIZE,
            (libc::PROT_READ | libc::PROT_WRITE) as u64,
            (libc::MAP_PRIVATE | libc::MAP_ANONYMOUS) as u64,
            -1_i32 as u64,
            0,
        ];

        let first = syscall_result(&mut memory, &mut state, libc::SYS_mmap, mmap_args) as u64;
        memory.write(first, b"mremap-data").unwrap();
        let blocker = syscall_result(&mut memory, &mut state, libc::SYS_mmap, mmap_args) as u64;
        assert_eq!(blocker, first + PAGE_SIZE);

        let moved = syscall_result(
            &mut memory,
            &mut state,
            libc::SYS_mremap,
            [
                first,
                PAGE_SIZE,
                2 * PAGE_SIZE,
                libc::MREMAP_MAYMOVE as u64,
                0,
                0,
            ],
        ) as u64;
        assert_eq!(moved, blocker + PAGE_SIZE);
        let mut payload = [0; 11];
        memory.read(moved, &mut payload).unwrap();
        assert_eq!(&payload, b"mremap-data");
        let mut old = [1; 11];
        memory.read(first, &mut old).unwrap();
        assert_eq!(old, [0; 11]);

        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_mremap,
                [moved, 2 * PAGE_SIZE, PAGE_SIZE, 0, 0, 0],
            ),
            moved as i64
        );
        let mut released = [1; 16];
        memory.read(moved + PAGE_SIZE, &mut released).unwrap();
        assert_eq!(released, [0; 16]);
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_mremap,
                [
                    moved,
                    PAGE_SIZE,
                    2 * PAGE_SIZE,
                    libc::MREMAP_FIXED as u64,
                    0,
                    0
                ],
            ),
            negative_errno(libc::EINVAL)
        );
    }

    #[test]
    fn mmap_reuses_unmapped_holes_after_cursor_exhaustion() {
        let root = TestDir::new();
        let mut state = test_state(&root.0);
        let memory_size = BOOT_RESERVED_END + 8 * PAGE_SIZE;
        let mut memory = GuestMemory::new(0, memory_size as usize).unwrap();
        state.mmap_base = BOOT_RESERVED_END + PAGE_SIZE;
        state.mmap_next = state.mmap_base;
        state.mmap_limit = state.mmap_base + 3 * PAGE_SIZE;
        let mmap_args = [
            0,
            PAGE_SIZE,
            (libc::PROT_READ | libc::PROT_WRITE) as u64,
            (libc::MAP_PRIVATE | libc::MAP_ANONYMOUS) as u64,
            -1_i32 as u64,
            0,
        ];

        let first = syscall_result(&mut memory, &mut state, libc::SYS_mmap, mmap_args) as u64;
        let second = syscall_result(&mut memory, &mut state, libc::SYS_mmap, mmap_args) as u64;
        let third = syscall_result(&mut memory, &mut state, libc::SYS_mmap, mmap_args) as u64;
        assert_eq!(second, first + PAGE_SIZE);
        assert_eq!(third, second + PAGE_SIZE);
        assert_eq!(state.mmap_next, state.mmap_limit);
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_munmap,
                [first, PAGE_SIZE, 0, 0, 0, 0],
            ),
            0
        );

        let reused = syscall_result(&mut memory, &mut state, libc::SYS_mmap, mmap_args) as u64;
        assert_eq!(reused, first);
        assert_eq!(state.mmap_next, state.mmap_limit);
        assert_eq!(
            syscall_result(&mut memory, &mut state, libc::SYS_mmap, mmap_args),
            negative_errno(libc::ENOMEM)
        );
    }

    #[test]
    fn mmap_reuses_unmapped_holes_before_cursor_exhaustion() {
        let root = TestDir::new();
        let mut state = test_state(&root.0);
        let memory_size = BOOT_RESERVED_END + 8 * PAGE_SIZE;
        let mut memory = GuestMemory::new(0, memory_size as usize).unwrap();
        state.mmap_base = BOOT_RESERVED_END + PAGE_SIZE;
        state.mmap_next = state.mmap_base;
        state.mmap_limit = state.mmap_base + 4 * PAGE_SIZE;
        let mmap_args = [
            0,
            PAGE_SIZE,
            (libc::PROT_READ | libc::PROT_WRITE) as u64,
            (libc::MAP_PRIVATE | libc::MAP_ANONYMOUS) as u64,
            -1_i32 as u64,
            0,
        ];

        let first = syscall_result(&mut memory, &mut state, libc::SYS_mmap, mmap_args) as u64;
        let second = syscall_result(&mut memory, &mut state, libc::SYS_mmap, mmap_args) as u64;
        assert_eq!(second, first + PAGE_SIZE);
        assert_eq!(state.mmap_next, first + 2 * PAGE_SIZE);
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_munmap,
                [first, PAGE_SIZE, 0, 0, 0, 0],
            ),
            0
        );

        assert_eq!(
            syscall_result(&mut memory, &mut state, libc::SYS_mmap, mmap_args),
            first as i64
        );
        assert_eq!(state.mmap_next, first + 2 * PAGE_SIZE);
    }

    fn madvise_memory(pages: u64) -> (TestDir, LoadedStaticElf, GuestMemory) {
        let root = TestDir::new();
        let mut state = test_state(&root.0);
        let memory_size = BOOT_RESERVED_END + (pages + 1) * PAGE_SIZE;
        let memory = GuestMemory::new(0, memory_size as usize).unwrap();
        state.mmap_next = BOOT_RESERVED_END + PAGE_SIZE;
        state.mmap_limit = memory_size;
        (root, state, memory)
    }

    fn madvise_map(
        memory: &mut GuestMemory,
        state: &mut LoadedStaticElf,
        flags: libc::c_int,
        fd: libc::c_int,
        pages: u64,
    ) -> u64 {
        let address = syscall_result(
            memory,
            state,
            libc::SYS_mmap,
            [
                0,
                pages * PAGE_SIZE,
                (libc::PROT_READ | libc::PROT_WRITE) as u64,
                flags as u64,
                fd as u64,
                0,
            ],
        );
        assert!(address > 0, "mmap failed with {address}");
        address as u64
    }

    fn dontneed(
        memory: &mut GuestMemory,
        state: &mut LoadedStaticElf,
        address: u64,
        length: u64,
    ) -> i64 {
        syscall_result(
            memory,
            state,
            libc::SYS_madvise,
            [address, length, libc::MADV_DONTNEED as u64, 0, 0, 0],
        )
    }

    fn page_bytes(memory: &GuestMemory, address: u64) -> [u8; 8] {
        let mut bytes = [0; 8];
        memory.read(address, &mut bytes).unwrap();
        bytes
    }

    /// MADV_DONTNEED holds the allocation guard that every layout change holds,
    /// from its classification through its last zeroed page, so a concurrent
    /// executor (a host-owned worker) cannot replace a page between the two.
    #[test]
    fn madvise_dontneed_waits_for_the_allocation_guard() {
        let (root, mut state, mut memory) = madvise_memory(8);
        let private = madvise_map(
            &mut memory,
            &mut state,
            libc::MAP_PRIVATE | libc::MAP_ANONYMOUS,
            -1,
            1,
        );
        memory.write(private, b"guarded!").unwrap();
        let mut worker_memory = memory.clone();
        let mut worker_state = test_state(&root.0);
        worker_state.mmap_limit = state.mmap_limit;
        let (done, finished) = std::sync::mpsc::channel();
        std::thread::scope(|scope| {
            let guard = memory.allocation_guard();
            let worker = scope.spawn(move || {
                let result = syscall_result(
                    &mut worker_memory,
                    &mut worker_state,
                    libc::SYS_madvise,
                    [private, PAGE_SIZE, libc::MADV_DONTNEED as u64, 0, 0, 0],
                );
                done.send(()).unwrap();
                result
            });
            assert!(
                finished
                    .recv_timeout(std::time::Duration::from_millis(300))
                    .is_err(),
                "madvise ran while another layout change held the allocation guard"
            );
            assert_eq!(&page_bytes(&memory, private), b"guarded!");
            drop(guard);
            assert_eq!(worker.join().unwrap(), 0);
        });
        assert_eq!(page_bytes(&memory, private), [0; 8]);
    }

    #[test]
    fn madvise_dontneed_zeroes_private_anonymous_pages_and_keeps_shared_ones() {
        let (_root, mut state, mut memory) = madvise_memory(8);
        let private = madvise_map(
            &mut memory,
            &mut state,
            libc::MAP_PRIVATE | libc::MAP_ANONYMOUS,
            -1,
            2,
        );
        let shared = madvise_map(
            &mut memory,
            &mut state,
            libc::MAP_SHARED | libc::MAP_ANONYMOUS,
            -1,
            1,
        );
        memory.write(private, b"private0").unwrap();
        memory.write(private + PAGE_SIZE, b"private1").unwrap();
        memory.write(shared, b"shared!!").unwrap();

        assert_eq!(dontneed(&mut memory, &mut state, private, 2 * PAGE_SIZE), 0);
        assert_eq!(page_bytes(&memory, private), [0; 8]);
        assert_eq!(page_bytes(&memory, private + PAGE_SIZE), [0; 8]);
        // Linux keeps shared anonymous contents (shmem) through MADV_DONTNEED.
        assert_eq!(dontneed(&mut memory, &mut state, shared, PAGE_SIZE), 0);
        assert_eq!(&page_bytes(&memory, shared), b"shared!!");
    }

    #[test]
    fn madvise_dontneed_refuses_a_private_file_copy_before_changing_any_page() {
        let (root, mut state, mut memory) = madvise_memory(8);
        std::fs::write(root.0.join("file"), b"contents").unwrap();
        state
            .files
            .insert(5, std::fs::File::open(root.0.join("file")).unwrap());
        let anonymous = madvise_map(
            &mut memory,
            &mut state,
            libc::MAP_PRIVATE | libc::MAP_ANONYMOUS,
            -1,
            1,
        );
        let file = madvise_map(&mut memory, &mut state, libc::MAP_PRIVATE, 5, 1);
        assert_eq!(file, anonymous + PAGE_SIZE);
        memory.write(anonymous, b"anon-new").unwrap();
        memory.write(file, b"file-new").unwrap();

        // Linux would read the file's page again; this backend cannot, so it
        // refuses the whole call and changes nothing, the anonymous page included.
        assert_eq!(
            dontneed(&mut memory, &mut state, anonymous, 2 * PAGE_SIZE),
            negative_errno(libc::ENOSYS)
        );
        assert_eq!(&page_bytes(&memory, anonymous), b"anon-new");
        assert_eq!(&page_bytes(&memory, file), b"file-new");
    }

    #[test]
    fn madvise_dontneed_applies_to_mapped_parts_then_reports_a_hole() {
        let (_root, mut state, mut memory) = madvise_memory(8);
        let first = madvise_map(
            &mut memory,
            &mut state,
            libc::MAP_PRIVATE | libc::MAP_ANONYMOUS,
            -1,
            3,
        );
        for page in 0..3 {
            memory.write(first + page * PAGE_SIZE, b"occupied").unwrap();
        }
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_munmap,
                [first + PAGE_SIZE, PAGE_SIZE, 0, 0, 0, 0],
            ),
            0
        );
        assert_eq!(
            dontneed(&mut memory, &mut state, first, 3 * PAGE_SIZE),
            negative_errno(libc::ENOMEM)
        );
        assert_eq!(page_bytes(&memory, first), [0; 8]);
        assert_eq!(page_bytes(&memory, first + 2 * PAGE_SIZE), [0; 8]);
    }

    #[test]
    fn madvise_dontneed_validates_and_rounds_its_arguments_as_linux_does() {
        let (_root, mut state, mut memory) = madvise_memory(8);
        let first = madvise_map(
            &mut memory,
            &mut state,
            libc::MAP_PRIVATE | libc::MAP_ANONYMOUS,
            -1,
            2,
        );
        memory.write(first, b"rounded!").unwrap();
        memory.write(first + PAGE_SIZE, b"untouchd").unwrap();
        let top_page = !(PAGE_SIZE - 1);
        for (address, length, expected) in [
            (first + 1, PAGE_SIZE, negative_errno(libc::EINVAL)),
            (first, 0, 0),
            // The length rounds up to zero pages: EINVAL, as Linux.
            (first, u64::MAX, negative_errno(libc::EINVAL)),
            (top_page, 2 * PAGE_SIZE, negative_errno(libc::EINVAL)),
        ] {
            assert_eq!(
                dontneed(&mut memory, &mut state, address, length),
                expected,
                "madvise({address:#x}, {length:#x}, MADV_DONTNEED)"
            );
        }
        assert_eq!(&page_bytes(&memory, first), b"rounded!");
        // A one-byte length covers the whole first page and nothing more.
        assert_eq!(dontneed(&mut memory, &mut state, first, 1), 0);
        assert_eq!(page_bytes(&memory, first), [0; 8]);
        assert_eq!(&page_bytes(&memory, first + PAGE_SIZE), b"untouchd");
    }

    /// A hint (the access-pattern advice, and the reclaim, KSM and huge-page
    /// advice this backend does not act on) gets Linux's answers
    /// (mm/madvise.c): success over a mapped range, ENOMEM over a range with a
    /// hole or no mapping at all, EINVAL for an unaligned start and success for
    /// a zero length. No page changes.
    #[test]
    fn madvise_hints_get_linux_answers_and_change_no_page() {
        let (_root, mut state, mut memory) = madvise_memory(8);
        let first = madvise_map(
            &mut memory,
            &mut state,
            libc::MAP_PRIVATE | libc::MAP_ANONYMOUS,
            -1,
            3,
        );
        for page in 0..3 {
            memory.write(first + page * PAGE_SIZE, b"occupied").unwrap();
        }
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_munmap,
                [first + 2 * PAGE_SIZE, PAGE_SIZE, 0, 0, 0, 0],
            ),
            0
        );
        let unmapped = first + 2 * PAGE_SIZE;
        for advice in [
            libc::MADV_NORMAL,
            libc::MADV_RANDOM,
            libc::MADV_SEQUENTIAL,
            libc::MADV_WILLNEED,
            libc::MADV_FREE,
            libc::MADV_MERGEABLE,
            libc::MADV_UNMERGEABLE,
            libc::MADV_HUGEPAGE,
            libc::MADV_NOHUGEPAGE,
            libc::MADV_COLD,
            libc::MADV_PAGEOUT,
        ] {
            for (address, length, expected) in [
                (first, 2 * PAGE_SIZE, 0),
                (first, 3 * PAGE_SIZE, negative_errno(libc::ENOMEM)),
                (unmapped, PAGE_SIZE, negative_errno(libc::ENOMEM)),
                (first + 1, PAGE_SIZE, negative_errno(libc::EINVAL)),
                (unmapped, 0, 0),
            ] {
                assert_eq!(
                    syscall_result(
                        &mut memory,
                        &mut state,
                        libc::SYS_madvise,
                        [address, length, advice as u64, 0, 0, 0],
                    ),
                    expected,
                    "madvise({address:#x}, {length:#x}, {advice})"
                );
            }
        }
        assert_eq!(&page_bytes(&memory, first), b"occupied");
        assert_eq!(&page_bytes(&memory, first + PAGE_SIZE), b"occupied");
    }

    /// Advice in `MADVISE_UNIMPLEMENTED` answers ENOSYS with the typed refusal
    /// `UnsupportedOperation::MemoryAdvice`, whose diagnostic names the advice,
    /// after the argument checks Linux makes first. A hint, a call the
    /// argument checks answer, and an advice Linux does not know (EINVAL)
    /// carry no refusal.
    #[test]
    fn madvise_refuses_unimplemented_advice_with_a_typed_refusal() {
        let (root, mut state, mut memory) = madvise_memory(2);
        let mapped = madvise_map(
            &mut memory,
            &mut state,
            libc::MAP_PRIVATE | libc::MAP_ANONYMOUS,
            -1,
            1,
        );
        memory.write(mapped, b"occupied").unwrap();
        let mut executor = ElfExecutor::new(state, false);
        let mut madvise = |address: u64, length: u64, advice: libc::c_int| {
            let result = executor.execute(
                &SyscallRequest::new(
                    libc::SYS_madvise as u64,
                    [address, length, advice as u64, 0, 0, 0],
                ),
                &memory,
            );
            (result, executor.take_unsupported_refusal())
        };
        for advice in MADVISE_UNIMPLEMENTED {
            let (result, refusal) = madvise(mapped, PAGE_SIZE, advice);
            assert_eq!(result, negative_errno(libc::ENOSYS), "advice {advice}");
            let refusal = refusal.unwrap_or_else(|| panic!("advice {advice} carried no refusal"));
            assert_eq!(
                (refusal.operation, refusal.errno),
                (
                    reverie::UnsupportedOperation::MemoryAdvice,
                    reverie::Errno::ENOSYS
                ),
                "advice {advice}"
            );
            assert_eq!(
                refusal.diagnostic,
                madvise_refusal_diagnostic(advice),
                "advice {advice}"
            );
            assert!(
                refusal.diagnostic.contains("MADV_"),
                "advice {advice}: {}",
                refusal.diagnostic
            );
            assert_eq!(
                madvise(mapped + 1, PAGE_SIZE, advice),
                (negative_errno(libc::EINVAL), None)
            );
            assert_eq!(madvise(mapped, 0, advice), (0, None));
        }
        assert_eq!(madvise(mapped, PAGE_SIZE, libc::MADV_WILLNEED), (0, None));
        // An advice Linux does not know is EINVAL before any other check, a
        // zero length included.
        for advice in [-1, 5, 26, 99, 104] {
            assert_eq!(
                madvise(mapped, PAGE_SIZE, advice),
                (negative_errno(libc::EINVAL), None),
                "advice {advice}"
            );
            assert_eq!(
                madvise(mapped, 0, advice),
                (negative_errno(libc::EINVAL), None),
                "advice {advice}"
            );
        }
        assert_eq!(&page_bytes(&memory, mapped), b"occupied");
        drop(root);
    }

    /// A madvise ENOSYS carries the typed refusal naming its advice,
    /// `MADV_DONTNEED` over a private file mapping included; any other result,
    /// and any other syscall's ENOSYS, carries none.
    #[test]
    fn madvise_refusal_names_the_advice_of_every_enosys() {
        let request = |number: libc::c_long, advice: libc::c_int| {
            SyscallRequest::new(number as u64, [0, PAGE_SIZE, advice as u64, 0, 0, 0])
        };
        let refusal = madvise_refusal(
            &request(libc::SYS_madvise, libc::MADV_DONTNEED),
            negative_errno(libc::ENOSYS),
        )
        .unwrap();
        assert_eq!(
            refusal.operation,
            reverie::UnsupportedOperation::MemoryAdvice
        );
        assert!(
            refusal
                .diagnostic
                .contains("MADV_DONTNEED on a private file mapping")
        );
        for result in [
            0,
            negative_errno(libc::ENOMEM),
            negative_errno(libc::EINVAL),
        ] {
            assert_eq!(
                madvise_refusal(&request(libc::SYS_madvise, libc::MADV_DONTFORK), result),
                None
            );
        }
        assert_eq!(
            madvise_refusal(
                &request(libc::SYS_mprotect, libc::MADV_DONTFORK),
                negative_errno(libc::ENOSYS)
            ),
            None
        );
    }

    #[test]
    fn madvise_dontneed_follows_shared_anonymous_memory_through_mremap_fork_and_replacement() {
        let (_root, mut state, mut memory) = madvise_memory(12);
        let shared = madvise_map(
            &mut memory,
            &mut state,
            libc::MAP_SHARED | libc::MAP_ANONYMOUS,
            -1,
            1,
        );
        let blocker = madvise_map(
            &mut memory,
            &mut state,
            libc::MAP_PRIVATE | libc::MAP_ANONYMOUS,
            -1,
            1,
        );
        assert_eq!(blocker, shared + PAGE_SIZE);
        memory.write(shared, b"carried!").unwrap();
        let moved = syscall_result(
            &mut memory,
            &mut state,
            libc::SYS_mremap,
            [
                shared,
                PAGE_SIZE,
                2 * PAGE_SIZE,
                libc::MREMAP_MAYMOVE as u64,
                0,
                0,
            ],
        ) as u64;
        assert_ne!(moved, shared);
        memory.write(moved + PAGE_SIZE, b"grownpg!").unwrap();
        // The moved page and the grown page are both still shared.
        assert_eq!(dontneed(&mut memory, &mut state, moved, 2 * PAGE_SIZE), 0);
        assert_eq!(&page_bytes(&memory, moved), b"carried!");
        assert_eq!(&page_bytes(&memory, moved + PAGE_SIZE), b"grownpg!");

        // A fork's copy of the address space keeps the mark.
        let mut child = memory.snapshot().unwrap();
        assert_eq!(dontneed(&mut child, &mut state, moved, PAGE_SIZE), 0);
        assert_eq!(&page_bytes(&child, moved), b"carried!");

        // A private mapping placed over it is private anonymous memory.
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_mmap,
                [
                    moved,
                    PAGE_SIZE,
                    (libc::PROT_READ | libc::PROT_WRITE) as u64,
                    (libc::MAP_PRIVATE | libc::MAP_ANONYMOUS | libc::MAP_FIXED) as u64,
                    -1_i32 as u64,
                    0,
                ],
            ),
            moved as i64
        );
        memory.write(moved, b"replaced").unwrap();
        assert_eq!(dontneed(&mut memory, &mut state, moved, PAGE_SIZE), 0);
        assert_eq!(page_bytes(&memory, moved), [0; 8]);
    }

    /// MAP_FIXED_NOREPLACE maps exactly at a vacant address and fails with
    /// EEXIST over any mapped page, keeping that mapping, as Linux's do_mmap
    /// does (https://github.com/rrnewton/hermit/issues/4428). It was taken as
    /// a hint, and an occupied range got a mapping elsewhere.
    #[test]
    fn map_fixed_noreplace_refuses_an_occupied_range_and_maps_a_vacant_one() {
        let (_root, mut state, mut memory) = madvise_memory(12);
        let noreplace =
            (libc::MAP_PRIVATE | libc::MAP_ANONYMOUS | libc::MAP_FIXED_NOREPLACE) as u64;
        let map_at = |memory: &mut GuestMemory, state: &mut LoadedStaticElf, address, pages| {
            syscall_result(
                memory,
                state,
                libc::SYS_mmap,
                [
                    address,
                    pages * PAGE_SIZE,
                    (libc::PROT_READ | libc::PROT_WRITE) as u64,
                    noreplace,
                    -1_i32 as u64,
                    0,
                ],
            )
        };
        let mapped = madvise_map(
            &mut memory,
            &mut state,
            libc::MAP_PRIVATE | libc::MAP_ANONYMOUS,
            -1,
            2,
        );
        memory.write(mapped, b"occupied").unwrap();
        // The whole range, and a range that only overlaps its second page.
        assert_eq!(
            map_at(&mut memory, &mut state, mapped, 2),
            negative_errno(libc::EEXIST)
        );
        assert_eq!(
            map_at(&mut memory, &mut state, mapped + PAGE_SIZE, 2),
            negative_errno(libc::EEXIST)
        );
        assert_eq!(&page_bytes(&memory, mapped), b"occupied");
        // Past TASK_SIZE is ENOMEM before an unaligned address's EINVAL.
        assert_eq!(
            map_at(&mut memory, &mut state, 0x4000_0000_0000_0001, 1),
            negative_errno(libc::ENOMEM)
        );
        // A file mapping with a bad descriptor is EBADF before the overlap.
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_mmap,
                [
                    mapped,
                    PAGE_SIZE,
                    libc::PROT_READ as u64,
                    (libc::MAP_PRIVATE | libc::MAP_FIXED_NOREPLACE) as u64,
                    999,
                    0,
                ],
            ),
            negative_errno(libc::EBADF)
        );
        // Unaligned, as for MAP_FIXED.
        assert_eq!(
            map_at(&mut memory, &mut state, mapped + 1, 1),
            negative_errno(libc::EINVAL)
        );
        // Vacant: mapped exactly there.
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_munmap,
                [mapped, 2 * PAGE_SIZE, 0, 0, 0, 0]
            ),
            0
        );
        assert_eq!(map_at(&mut memory, &mut state, mapped, 2), mapped as i64);
        assert_eq!(page_bytes(&memory, mapped), [0; 8]);
    }

    /// Linux backs `MAP_SHARED | MAP_ANONYMOUS` with one shmem object that a
    /// forked child shares with its parent: a store by either process after
    /// the fork is visible to the other. Private anonymous memory is copied.
    #[test]
    fn shared_anonymous_memory_stays_shared_with_a_forked_child() {
        let (_root, mut state, mut memory) = madvise_memory(12);
        let shared = madvise_map(
            &mut memory,
            &mut state,
            libc::MAP_SHARED | libc::MAP_ANONYMOUS,
            -1,
            2,
        );
        let private = madvise_map(
            &mut memory,
            &mut state,
            libc::MAP_PRIVATE | libc::MAP_ANONYMOUS,
            -1,
            1,
        );
        memory.write(shared, b"prefork!").unwrap();
        memory.write(private, b"private!").unwrap();

        let mut child = memory.snapshot().unwrap();
        assert_eq!(&page_bytes(&child, shared), b"prefork!");
        assert_eq!(&page_bytes(&child, private), b"private!");

        // Parent to child, and child to parent, on both pages of the mapping.
        memory.write(shared, b"parent!!").unwrap();
        assert_eq!(&page_bytes(&child, shared), b"parent!!");
        child.write(shared + PAGE_SIZE, b"child!!!").unwrap();
        assert_eq!(&page_bytes(&memory, shared + PAGE_SIZE), b"child!!!");

        // Private anonymous memory stays a private copy in each direction.
        memory.write(private, b"parentpv").unwrap();
        child.write(private, b"childpv!").unwrap();
        assert_eq!(&page_bytes(&memory, private), b"parentpv");
        assert_eq!(&page_bytes(&child, private), b"childpv!");

        // A grandchild joins the same object.
        let grandchild = child.snapshot().unwrap();
        memory.write(shared, b"third!!!").unwrap();
        assert_eq!(&page_bytes(&grandchild, shared), b"third!!!");
        assert_eq!(&page_bytes(&child, shared), b"third!!!");

        // Unmapping in one process leaves the object intact for the others,
        // and the freed parent page no longer aliases it.
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_munmap,
                [shared, 2 * PAGE_SIZE, 0, 0, 0, 0],
            ),
            0
        );
        assert_eq!(&page_bytes(&child, shared), b"third!!!");
        assert_eq!(&page_bytes(&grandchild, shared + PAGE_SIZE), b"child!!!");
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_mmap,
                [
                    shared,
                    PAGE_SIZE,
                    (libc::PROT_READ | libc::PROT_WRITE) as u64,
                    (libc::MAP_PRIVATE | libc::MAP_ANONYMOUS | libc::MAP_FIXED) as u64,
                    -1_i32 as u64,
                    0,
                ],
            ),
            shared as i64
        );
        assert_eq!(page_bytes(&memory, shared), [0; 8]);
        memory.write(shared, b"reused!!").unwrap();
        assert_eq!(&page_bytes(&child, shared), b"third!!!");
        assert_eq!(&page_bytes(&grandchild, shared), b"third!!!");

        // A new shared anonymous mapping over an inherited one is a new object:
        // the child's later fork shares it, and the grandchild keeps the old.
        assert_eq!(
            syscall_result(
                &mut child,
                &mut state,
                libc::SYS_mmap,
                [
                    shared,
                    PAGE_SIZE,
                    (libc::PROT_READ | libc::PROT_WRITE) as u64,
                    (libc::MAP_SHARED | libc::MAP_ANONYMOUS | libc::MAP_FIXED) as u64,
                    -1_i32 as u64,
                    0,
                ],
            ),
            shared as i64
        );
        assert_eq!(page_bytes(&child, shared), [0; 8]);
        assert_eq!(&page_bytes(&grandchild, shared), b"third!!!");
        child.write(shared, b"newobj!!").unwrap();
        let second = child.snapshot().unwrap();
        child.write(shared, b"newobj2!").unwrap();
        assert_eq!(&page_bytes(&second, shared), b"newobj2!");
        assert_eq!(&page_bytes(&grandchild, shared), b"third!!!");
        assert_eq!(&page_bytes(&memory, shared), b"reused!!");
    }

    /// Sharing the object needs the forking address space quiescent. With
    /// another live participant, the fork refuses by name instead of handing
    /// the child a private copy, and the parent's memory is unchanged.
    #[test]
    fn shared_anonymous_fork_refuses_with_another_live_participant() {
        let (_root, mut state, mut memory) = madvise_memory(4);
        let shared = madvise_map(
            &mut memory,
            &mut state,
            libc::MAP_SHARED | libc::MAP_ANONYMOUS,
            -1,
            1,
        );
        memory.write(shared, b"prefork!").unwrap();
        let _forking = memory.entry_gate().register().unwrap();
        let _sibling = memory.entry_gate().register().unwrap();
        match memory.snapshot() {
            Err(crate::Error::SharedFileCapability { operation, .. }) => {
                assert_eq!(operation, "fork with shared anonymous memory");
            }
            Err(other) => panic!("expected the shared anonymous fork refusal, got {other}"),
            Ok(_) => panic!("fork with a live sibling copied shared anonymous memory"),
        }
        assert_eq!(memory.separately_backed_pages(), 0);
        assert_eq!(&page_bytes(&memory, shared), b"prefork!");
    }

    #[test]
    fn msync_validates_mapped_ranges_and_flags() {
        let root = TestDir::new();
        let mut state = test_state(&root.0);
        let memory_size = BOOT_RESERVED_END + 8 * PAGE_SIZE;
        let mut memory = GuestMemory::new(0, memory_size as usize).unwrap();
        state.mmap_next = BOOT_RESERVED_END + PAGE_SIZE;
        state.mmap_limit = memory_size;
        let mapping = syscall_result(
            &mut memory,
            &mut state,
            libc::SYS_mmap,
            [
                0,
                PAGE_SIZE,
                (libc::PROT_READ | libc::PROT_WRITE) as u64,
                (libc::MAP_SHARED | libc::MAP_ANONYMOUS) as u64,
                -1_i32 as u64,
                0,
            ],
        ) as u64;

        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_msync,
                [mapping, PAGE_SIZE, libc::MS_SYNC as u64, 0, 0, 0],
            ),
            0
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_msync,
                [mapping + 1, PAGE_SIZE, libc::MS_SYNC as u64, 0, 0, 0],
            ),
            negative_errno(libc::EINVAL)
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_msync,
                [
                    mapping,
                    PAGE_SIZE,
                    (libc::MS_ASYNC | libc::MS_SYNC) as u64,
                    0,
                    0,
                    0,
                ],
            ),
            negative_errno(libc::EINVAL)
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_msync,
                [
                    mapping + PAGE_SIZE,
                    PAGE_SIZE,
                    libc::MS_SYNC as u64,
                    0,
                    0,
                    0,
                ],
            ),
            negative_errno(libc::ENOMEM)
        );
    }

    #[test]
    fn msync_length_rounding_and_address_overflow_match_native() {
        let root = TestDir::new();
        let mut state = test_state(&root.0);
        let mut memory = GuestMemory::new(0, (BOOT_RESERVED_END + 8 * PAGE_SIZE) as usize).unwrap();
        let aligned = BOOT_RESERVED_END;
        let top_page = !(PAGE_SIZE - 1);
        for (address, length, flags, expected) in [
            (aligned, 0, libc::MS_SYNC, 0),
            (aligned, u64::MAX, libc::MS_SYNC, 0),
            (aligned, u64::MAX - (PAGE_SIZE - 2), libc::MS_SYNC, 0),
            (
                aligned,
                u64::MAX - (PAGE_SIZE - 1),
                libc::MS_SYNC,
                negative_errno(libc::ENOMEM),
            ),
            (top_page, u64::MAX, libc::MS_SYNC, 0),
            (
                top_page,
                PAGE_SIZE,
                libc::MS_SYNC,
                negative_errno(libc::ENOMEM),
            ),
            (
                aligned + 1,
                u64::MAX,
                libc::MS_SYNC,
                negative_errno(libc::EINVAL),
            ),
            (
                aligned,
                u64::MAX,
                libc::MS_SYNC | libc::MS_ASYNC,
                negative_errno(libc::EINVAL),
            ),
        ] {
            // These cases either round to zero or fail argument/range validation;
            // the native syscall cannot access a nonempty mapped interval.
            let rc =
                unsafe { libc::syscall(libc::SYS_msync, address as usize, length as usize, flags) };
            let native = if rc == -1 {
                negative_errno(std::io::Error::last_os_error().raw_os_error().unwrap())
            } else {
                rc as i64
            };
            assert_eq!(
                native, expected,
                "native address={address:#x} length={length:#x} flags={flags}"
            );
            let guest = syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_msync,
                [address, length, flags as u64, 0, 0, 0],
            );
            assert_eq!(
                guest, native,
                "KVM address={address:#x} length={length:#x} flags={flags}"
            );
        }
    }

    #[test]
    fn mremap_grows_a_reused_hole_into_adjacent_space() {
        let root = TestDir::new();
        let mut state = test_state(&root.0);
        let memory_size = BOOT_RESERVED_END + 8 * PAGE_SIZE;
        let mut memory = GuestMemory::new(0, memory_size as usize).unwrap();
        state.mmap_base = BOOT_RESERVED_END + PAGE_SIZE;
        state.mmap_next = state.mmap_base;
        state.mmap_limit = state.mmap_base + 3 * PAGE_SIZE;
        let mmap_args = [
            0,
            PAGE_SIZE,
            (libc::PROT_READ | libc::PROT_WRITE) as u64,
            (libc::MAP_PRIVATE | libc::MAP_ANONYMOUS) as u64,
            -1_i32 as u64,
            0,
        ];

        let first = syscall_result(&mut memory, &mut state, libc::SYS_mmap, mmap_args) as u64;
        assert_eq!(
            syscall_result(&mut memory, &mut state, libc::SYS_mmap, mmap_args),
            (first + PAGE_SIZE) as i64
        );
        assert_eq!(
            syscall_result(&mut memory, &mut state, libc::SYS_mmap, mmap_args),
            (first + 2 * PAGE_SIZE) as i64
        );
        assert_eq!(state.mmap_next, state.mmap_limit);
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_munmap,
                [first, 2 * PAGE_SIZE, 0, 0, 0, 0],
            ),
            0
        );
        assert_eq!(
            syscall_result(&mut memory, &mut state, libc::SYS_mmap, mmap_args),
            first as i64
        );

        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_mremap,
                [
                    first,
                    PAGE_SIZE,
                    2 * PAGE_SIZE,
                    libc::MREMAP_MAYMOVE as u64,
                    0,
                    0,
                ],
            ),
            first as i64
        );
        assert_eq!(state.mmap_next, state.mmap_limit);
        assert!(memory.user_range_is_mapped(first, 2 * PAGE_SIZE));
    }

    // Regression: a root guest renumbered by `KvmBackend::set_root_pid` gets a
    // synthetic container-init `getppid()` of 1 for ptrace parity. If that
    // guest-visible value also drove `Guest::ppid`, `Guest::is_root_process`
    // would be false for the root guest and Detcore would never register the
    // root thread with its scheduler, hanging every KVM run before the first
    // syscall. The traced-tree answer must stay independent of `getppid()`.
    #[test]
    fn renumbered_root_guest_has_no_traced_parent_but_keeps_getppid() {
        let root = TestDir::new();
        let mut state = test_state(&root.0);
        // What `KvmBackend::set_root_pid(ROOT_DETPID)` produces.
        state.pid = 3;
        state.pgid = 3;
        state.tid = 3;
        state.ppid = 1;
        state.task_lifecycle = Arc::new(std::sync::Mutex::new(
            crate::elf::TaskLifecycleTable::with_root(3, 3, 3, true),
        ));
        let memory = GuestMemory::new(0, PAGE_SIZE as usize).unwrap();
        let mut executor = ElfExecutor::new(state, false);

        assert!(executor.parent_pid().is_none());
        // The guest-visible value is unchanged: `getppid()` still returns 1.
        assert_eq!(
            executor.execute(
                &SyscallRequest::new(libc::SYS_getppid as u64, [0, 0, 0, 0, 0, 0]),
                &memory,
            ),
            1
        );

        // A CLONE_THREAD worker stays in the root process, so it is also root.
        let thread = executor.thread_child(4).unwrap();
        assert!(thread.parent_pid().is_none());

        // A forked child does have a traced parent.
        let child = executor.fork_child(5, false, false).unwrap();
        assert_eq!(child.parent_pid(), Some(reverie::Pid::from_raw(3)));
    }

    #[test]
    fn thread_executors_share_mmap_allocation_cursor() {
        let root = TestDir::new();
        let memory_size = BOOT_RESERVED_END + 8 * PAGE_SIZE;
        let mut state = test_state(&root.0);
        state.mmap_next = BOOT_RESERVED_END + PAGE_SIZE;
        state.mmap_limit = memory_size;
        let memory = GuestMemory::new(0, memory_size as usize).unwrap();
        let mut parent = ElfExecutor::new(state, false);
        let mut child = parent.thread_child(2).unwrap();
        let request = SyscallRequest::new(
            libc::SYS_mmap as u64,
            [
                0,
                PAGE_SIZE,
                (libc::PROT_READ | libc::PROT_WRITE) as u64,
                (libc::MAP_PRIVATE | libc::MAP_ANONYMOUS) as u64,
                -1_i32 as u64,
                0,
            ],
        );

        let first = parent.execute(&request, &memory) as u64;
        let second = child.execute(&request, &memory) as u64;
        assert_eq!(first, BOOT_RESERVED_END + PAGE_SIZE);
        assert_eq!(second, first + PAGE_SIZE);
    }

    #[test]
    fn thread_executors_share_descriptor_replacement() {
        let root = TestDir::new();
        let old_path = root.0.join("old");
        let new_path = root.0.join("new");
        std::fs::write(&old_path, b"old").unwrap();
        std::fs::write(&new_path, b"new").unwrap();

        let mut state = test_state(&root.0);
        state
            .files
            .insert(3, std::fs::File::open(old_path).unwrap());
        let mut memory = GuestMemory::new(0, PAGE_SIZE as usize).unwrap();
        let mut parent = ElfExecutor::new(state, false);
        let mut child = parent.thread_child(2).unwrap();

        assert_eq!(
            parent.execute(
                &SyscallRequest::new(libc::SYS_close as u64, [3, 0, 0, 0, 0, 0]),
                &memory,
            ),
            0
        );
        write_c_string(&mut memory, 0x100, new_path.to_str().unwrap());
        assert_eq!(
            parent.execute(
                &SyscallRequest::new(
                    libc::SYS_openat as u64,
                    [libc::AT_FDCWD as u64, 0x100, libc::O_RDONLY as u64, 0, 0, 0],
                ),
                &memory,
            ),
            3
        );

        assert_eq!(
            child.execute(
                &SyscallRequest::new(libc::SYS_read as u64, [3, 0x200, 3, 0, 0, 0]),
                &memory,
            ),
            3
        );
        let mut bytes = [0; 3];
        memory.read(0x200, &mut bytes).unwrap();
        assert_eq!(&bytes, b"new");
    }

    #[test]
    fn mprotect_and_munmap_bound_tool_user_copies() {
        let root = TestDir::new();
        let mut state = test_state(&root.0);
        let memory_size = BOOT_RESERVED_END + 8 * PAGE_SIZE;
        let mut memory = GuestMemory::new(0, memory_size as usize).unwrap();
        state.mmap_next = BOOT_RESERVED_END + PAGE_SIZE;
        state.mmap_limit = memory_size;
        let mapping = syscall_result(
            &mut memory,
            &mut state,
            libc::SYS_mmap,
            [
                0,
                2 * PAGE_SIZE,
                (libc::PROT_READ | libc::PROT_WRITE) as u64,
                (libc::MAP_PRIVATE | libc::MAP_ANONYMOUS) as u64,
                -1_i32 as u64,
                0,
            ],
        ) as u64;
        memory.enable_user_access();

        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_mprotect,
                [
                    mapping + PAGE_SIZE,
                    PAGE_SIZE,
                    libc::PROT_NONE as u64,
                    0,
                    0,
                    0,
                ],
            ),
            0
        );
        let boundary = AddrMut::from_raw((mapping + PAGE_SIZE - 8) as usize).unwrap();
        assert_eq!(
            MemoryAccess::write(&mut memory, boundary, &[0x5a; 16]).unwrap(),
            8
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_mprotect,
                [
                    mapping + PAGE_SIZE,
                    PAGE_SIZE,
                    (libc::PROT_READ | libc::PROT_WRITE) as u64,
                    0,
                    0,
                    0,
                ],
            ),
            0
        );
        assert_eq!(
            MemoryAccess::write(&mut memory, boundary, &[0x33; 16]).unwrap(),
            16
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_munmap,
                [mapping, 2 * PAGE_SIZE, 0, 0, 0, 0],
            ),
            0
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_mprotect,
                [mapping, PAGE_SIZE, libc::PROT_READ as u64, 0, 0, 0],
            ),
            negative_errno(libc::ENOMEM)
        );
    }

    /// The memory-management syscalls name the stack by its user addresses at
    /// the top of the user address space and act on its physical pages; the
    /// stack's identity addresses are not user addresses. mremap in place
    /// returns the user address, and a move lands in low memory.
    #[test]
    fn memory_syscalls_act_on_the_stack_window() {
        const MIB: u64 = 1024 * 1024;
        let root = TestDir::new();
        let mut state = test_state(&root.0);
        let mut memory = GuestMemory::new(0, (16 * MIB) as usize).unwrap();
        state.mmap_next = BOOT_RESERVED_END + PAGE_SIZE;
        state.mmap_limit = 8 * MIB;
        memory
            .reserve_region(8 * MIB, 8 * MIB, crate::memory::RegionKind::Stack)
            .unwrap()
            .commit();
        let window = memory.establish_user_stack_window(8 * MIB).unwrap();
        memory.map_user_range(8 * MIB, 8 * MIB, false).unwrap();
        memory.enable_user_access();

        let mut call = |memory: &mut GuestMemory, number, args| {
            syscall_result(memory, &mut state, number, args)
        };
        assert_eq!(
            call(
                &mut memory,
                libc::SYS_mprotect,
                [
                    window + PAGE_SIZE,
                    PAGE_SIZE,
                    libc::PROT_NONE as u64,
                    0,
                    0,
                    0
                ],
            ),
            0
        );
        let boundary = AddrMut::from_raw((window + PAGE_SIZE - 8) as usize).unwrap();
        assert_eq!(
            MemoryAccess::write(&mut memory, boundary, &[0x5a; 16]).unwrap(),
            8
        );
        assert_eq!(
            call(
                &mut memory,
                libc::SYS_mprotect,
                [
                    8 * MIB + PAGE_SIZE,
                    PAGE_SIZE,
                    libc::PROT_READ as u64,
                    0,
                    0,
                    0
                ],
            ),
            negative_errno(libc::ENOMEM)
        );
        assert_eq!(
            call(
                &mut memory,
                libc::SYS_mremap,
                [window, PAGE_SIZE, PAGE_SIZE, 0, 0, 0],
            ),
            window as i64
        );
        assert_eq!(
            call(
                &mut memory,
                libc::SYS_mremap,
                [8 * MIB, PAGE_SIZE, PAGE_SIZE, 0, 0, 0],
            ),
            negative_errno(libc::EINVAL)
        );
        let shrink = window + 4 * PAGE_SIZE;
        assert_eq!(
            call(
                &mut memory,
                libc::SYS_mremap,
                [shrink, 2 * PAGE_SIZE, PAGE_SIZE, 0, 0, 0],
            ),
            shrink as i64
        );
        let tail = AddrMut::from_raw((shrink + PAGE_SIZE) as usize).unwrap();
        assert!(MemoryAccess::write(&mut memory, tail, &[0x11; 8]).is_err());
        let moved = window + 8 * PAGE_SIZE;
        let marker = AddrMut::from_raw(moved as usize).unwrap();
        assert_eq!(
            MemoryAccess::write(&mut memory, marker, &[0x77; 8]).unwrap(),
            8
        );
        let destination = call(
            &mut memory,
            libc::SYS_mremap,
            [
                moved,
                PAGE_SIZE,
                2 * PAGE_SIZE,
                libc::MREMAP_MAYMOVE as u64,
                0,
                0,
            ],
        );
        assert!((BOOT_RESERVED_END as i64..(8 * MIB) as i64).contains(&destination));
        let mut copied = [0; 8];
        memory.user().read(destination as u64, &mut copied).unwrap();
        assert_eq!(copied, [0x77; 8]);
        assert_eq!(
            call(
                &mut memory,
                libc::SYS_munmap,
                [window + 2 * PAGE_SIZE, PAGE_SIZE, 0, 0, 0, 0],
            ),
            0
        );
        let unmapped = AddrMut::from_raw((window + 2 * PAGE_SIZE) as usize).unwrap();
        assert!(MemoryAccess::write(&mut memory, unmapped, &[0x33; 8]).is_err());
    }

    /// In Linux's layout, mappings without MAP_FIXED are placed as Linux 7.x
    /// places them (measured under ptrace; see the K2 design note): top-down
    /// below mmap_base and the host vDSO pages, with large-page alignment for
    /// an anonymous length that is a whole number of large pages (and no hint)
    /// and for a regular file range holding an aligned large page; a free hint
    /// is used as is and an occupied one ignored; MAP_FIXED reaches the
    /// identity addresses below the identity end and is refused at it; a
    /// mapping the window cannot hold goes to identity memory.
    #[test]
    fn mappings_follow_linux_top_down_placement() {
        const MIB: u64 = 1024 * 1024;
        let root = TestDir::new();
        let mut state = test_state(&root.0);
        let mut memory = GuestMemory::new(0, (128 * MIB) as usize).unwrap();
        let layout = crate::elf::establish_linux_layout(
            &mut memory,
            BOOT_RESERVED_END + PAGE_SIZE,
            MIB,
            None,
        )
        .unwrap()
        .unwrap();
        assert_eq!(layout.identity_end, 86 * MIB);
        crate::elf::reserve_vdso_gap(&mut memory, layout.mmap_end).unwrap();
        state.mmap_base = layout.identity_end;
        state.mmap_next = layout.identity_end;
        state.mmap_limit = layout.mmap_end;
        state.brk_limit = layout.identity_end;
        memory.enable_user_access();
        let large = root.0.join("three-mib.bin");
        std::fs::write(&large, vec![0; 0x30_0000]).unwrap();
        let small = root.0.join("small.bin");
        std::fs::write(&small, vec![0; 29_499]).unwrap();
        state.files.insert(3, std::fs::File::open(&large).unwrap());
        state.files.insert(4, std::fs::File::open(&small).unwrap());
        let read_write = (libc::PROT_READ | libc::PROT_WRITE) as u64;
        let anonymous = (libc::MAP_PRIVATE | libc::MAP_ANONYMOUS) as u64;
        let mut map = |memory: &mut GuestMemory, args: [u64; 6]| {
            syscall_result(memory, &mut state, libc::SYS_mmap, args)
        };
        for (length, expected) in [
            (0x1000, 0x7fff_f7ff_6000_u64),
            (0x10_0000, 0x7fff_f7ef_6000),
            (0x20_0000, 0x7fff_f7c0_0000),
            (0x20_1000, 0x7fff_f79f_f000),
            (0x40_0000, 0x7fff_f740_0000),
            (0x3f_f000, 0x7fff_f700_1000),
        ] {
            assert_eq!(
                map(&mut memory, [0, length, read_write, anonymous, u64::MAX, 0]),
                expected as i64,
                "anonymous {length:#x}"
            );
        }
        let private = libc::MAP_PRIVATE as u64;
        let read = libc::PROT_READ as u64;
        assert_eq!(
            map(&mut memory, [0, 0x30_0000, read, private, 3, 0]),
            0x7fff_f6c0_0000
        );
        assert_eq!(
            // The highest gap that fits: above the aligned large-page mapping.
            map(&mut memory, [0, 29_499, read, private, 4, 0]),
            0x7fff_f7ee_e000
        );
        let hint = BOOT_RESERVED_END + 16 * PAGE_SIZE;
        assert_eq!(
            map(
                &mut memory,
                [hint, PAGE_SIZE, read_write, anonymous, u64::MAX, 0]
            ),
            hint as i64
        );
        // An occupied hint is ignored: the highest gap below mmap_base, not the
        // free identity memory just below the hint.
        assert_eq!(
            map(
                &mut memory,
                [hint, PAGE_SIZE, read_write, anonymous, u64::MAX, 0]
            ),
            0x7fff_f7ee_d000
        );
        // An occupied hint falls back to top-down placement without alignment.
        assert_eq!(
            map(
                &mut memory,
                [hint, 0x20_0000, read_write, anonymous, u64::MAX, 0]
            ),
            0x7fff_f6a0_0000
        );
        // A low hint with no memory behind it lands as high as possible in
        // identity memory below it, not at the top of the address space.
        let unbacked = 0x1_0000_0000;
        let placed = map(
            &mut memory,
            [unbacked, 2 * PAGE_SIZE, read_write, anonymous, u64::MAX, 0],
        );
        assert_eq!(placed as u64, layout.identity_end - 2 * PAGE_SIZE);
        let fixed = anonymous | libc::MAP_FIXED as u64;
        let below = layout.identity_end - 3 * PAGE_SIZE;
        assert_eq!(
            map(
                &mut memory,
                [below, PAGE_SIZE, read_write, fixed, u64::MAX, 0]
            ),
            below as i64
        );
        assert_eq!(
            map(
                &mut memory,
                [
                    layout.identity_end,
                    PAGE_SIZE,
                    read_write,
                    fixed,
                    u64::MAX,
                    0
                ]
            ),
            negative_errno(libc::ENOMEM)
        );
        // 12 MiB of the window is left; 16 MiB goes to the top of the free
        // identity memory.
        assert_eq!(
            map(
                &mut memory,
                [0, 16 * MIB, read_write, anonymous, u64::MAX, 0]
            ),
            (layout.identity_end - 3 * PAGE_SIZE - 16 * MIB) as i64
        );
    }

    /// A guest of `size` bytes laid out as the loader lays out a static
    /// program at the boot area's end, with the vDSO gap reserved.
    fn linux_layout_fixture(
        root: &TestDir,
        size: u64,
    ) -> (GuestMemory, LoadedStaticElf, crate::elf::LinuxLayout) {
        let mut state = test_state(&root.0);
        let mut memory = GuestMemory::new(0, size as usize).unwrap();
        let layout = crate::elf::establish_linux_layout(
            &mut memory,
            BOOT_RESERVED_END + PAGE_SIZE,
            1024 * 1024,
            None,
        )
        .unwrap()
        .unwrap();
        crate::elf::reserve_vdso_gap(&mut memory, layout.mmap_end).unwrap();
        state.mmap_base = layout.identity_end;
        state.mmap_next = layout.identity_end;
        state.mmap_limit = layout.mmap_end;
        state.brk_limit = layout.identity_end;
        memory.enable_user_access();
        (memory, state, layout)
    }

    /// The measured sequence in a 64 MiB guest, whose window (18 MiB) cannot
    /// hold the 3 MiB file after the anonymous mappings: the file goes to the
    /// top of identity memory, and later mappings still fill the window as
    /// Linux fills its address space.
    #[test]
    fn mappings_in_a_small_window_fall_back_to_identity_memory() {
        const MIB: u64 = 1024 * 1024;
        let root = TestDir::new();
        let (mut memory, mut state, layout) = linux_layout_fixture(&root, 64 * MIB);
        assert_eq!(layout.identity_end, 38 * MIB);
        let large = root.0.join("three-mib.bin");
        std::fs::write(&large, vec![0; 0x30_0000]).unwrap();
        let small = root.0.join("small.bin");
        std::fs::write(&small, vec![0; 29_499]).unwrap();
        state.files.insert(3, std::fs::File::open(&large).unwrap());
        state.files.insert(4, std::fs::File::open(&small).unwrap());
        let read_write = (libc::PROT_READ | libc::PROT_WRITE) as u64;
        let anonymous = (libc::MAP_PRIVATE | libc::MAP_ANONYMOUS) as u64;
        let mut map = |memory: &mut GuestMemory, args: [u64; 6]| {
            syscall_result(memory, &mut state, libc::SYS_mmap, args)
        };
        for (length, expected) in [
            (0x1000, 0x7fff_f7ff_6000_u64),
            (0x10_0000, 0x7fff_f7ef_6000),
            (0x20_0000, 0x7fff_f7c0_0000),
            (0x20_1000, 0x7fff_f79f_f000),
            (0x40_0000, 0x7fff_f740_0000),
            (0x3f_f000, 0x7fff_f700_1000),
        ] {
            assert_eq!(
                map(&mut memory, [0, length, read_write, anonymous, u64::MAX, 0]),
                expected as i64,
                "anonymous {length:#x}"
            );
        }
        let private = libc::MAP_PRIVATE as u64;
        let read = libc::PROT_READ as u64;
        assert_eq!(
            map(&mut memory, [0, 0x30_0000, read, private, 3, 0]),
            (layout.identity_end - 0x30_0000) as i64
        );
        assert_eq!(
            map(&mut memory, [0, 29_499, read, private, 4, 0]),
            0x7fff_f7ee_e000
        );
    }

    /// A MAP_32BIT mapping lies below 2 GiB: a free hint below 2 GiB as is,
    /// otherwise the highest free identity memory below 2 GiB (KVM backs
    /// nothing in Linux's [1 GiB, 2 GiB) search range). MAP_FIXED overrides it.
    #[test]
    fn map_32bit_mappings_stay_below_two_gib() {
        const MIB: u64 = 1024 * 1024;
        let root = TestDir::new();
        let (mut memory, mut state, layout) = linux_layout_fixture(&root, 128 * MIB);
        let read_write = (libc::PROT_READ | libc::PROT_WRITE) as u64;
        let low = (libc::MAP_PRIVATE | libc::MAP_ANONYMOUS | libc::MAP_32BIT) as u64;
        let map = |memory: &mut GuestMemory, state: &mut LoadedStaticElf, args: [u64; 6]| {
            syscall_result(memory, state, libc::SYS_mmap, args)
        };
        assert_eq!(
            map(
                &mut memory,
                &mut state,
                [0, PAGE_SIZE, read_write, low, u64::MAX, 0]
            ),
            (layout.identity_end - PAGE_SIZE) as i64
        );
        assert_eq!(
            map(
                &mut memory,
                &mut state,
                [0x0400_0000, PAGE_SIZE, read_write, low, u64::MAX, 0]
            ),
            0x0400_0000
        );
        // A hint above 2 GiB is not used.
        assert_eq!(
            map(
                &mut memory,
                &mut state,
                [
                    MMAP_BASE - 0x10_0000,
                    PAGE_SIZE,
                    read_write,
                    low,
                    u64::MAX,
                    0
                ]
            ),
            (layout.identity_end - 2 * PAGE_SIZE) as i64
        );
        let fixed = low | libc::MAP_FIXED as u64;
        assert_eq!(
            map(
                &mut memory,
                &mut state,
                [
                    MMAP_BASE - 0x10_0000,
                    PAGE_SIZE,
                    read_write,
                    fixed,
                    u64::MAX,
                    0
                ]
            ),
            (MMAP_BASE - 0x10_0000) as i64
        );

        // A 3 GiB guest's identity memory reaches past 2 GiB; MAP_32BIT stops
        // below it.
        let (mut big, mut big_state, big_layout) = linux_layout_fixture(&root, 3072 * MIB);
        assert!(big_layout.identity_end > MAP_32BIT_END);
        assert_eq!(
            map(
                &mut big,
                &mut big_state,
                [0, PAGE_SIZE, read_write, low, u64::MAX, 0]
            ),
            (MAP_32BIT_END - PAGE_SIZE) as i64
        );
    }

    /// Linux rounds a hint down to a page: an unaligned free hint maps at its
    /// page, and an unaligned occupied one is ignored. A hint below the first
    /// page is no hint, so large-page alignment applies.
    #[test]
    fn hints_round_down_to_a_page() {
        const MIB: u64 = 1024 * 1024;
        let root = TestDir::new();
        let (mut memory, mut state, _layout) = linux_layout_fixture(&root, 128 * MIB);
        let read_write = (libc::PROT_READ | libc::PROT_WRITE) as u64;
        let anonymous = (libc::MAP_PRIVATE | libc::MAP_ANONYMOUS) as u64;
        let mut map = |memory: &mut GuestMemory, args: [u64; 6]| {
            syscall_result(memory, &mut state, libc::SYS_mmap, args)
        };
        assert_eq!(
            map(
                &mut memory,
                [0x0400_0123, PAGE_SIZE, read_write, anonymous, u64::MAX, 0]
            ),
            0x0400_0000
        );
        assert_eq!(
            map(
                &mut memory,
                [0x0400_0123, PAGE_SIZE, read_write, anonymous, u64::MAX, 0]
            ),
            0x7fff_f7ff_6000
        );
        assert_eq!(
            map(
                &mut memory,
                [0x10, 2 * MIB, read_write, anonymous, u64::MAX, 0]
            ),
            0x7fff_f7c0_0000
        );
    }

    /// mremap moves a regular-file mapping as Linux does, by its file offset:
    /// grown to 4 MiB from offset 0x1000, it lands 0x1000 past a large-page
    /// boundary, and its pages keep their offsets. An anonymous mapping moved
    /// the same way lands on a boundary.
    #[test]
    fn moved_file_mremap_keeps_its_file_offset_alignment() {
        const MIB: u64 = 1024 * 1024;
        let root = TestDir::new();
        let (mut memory, mut state, _layout) = linux_layout_fixture(&root, 128 * MIB);
        let path = root.0.join("file.bin");
        std::fs::write(&path, vec![7; 2 * PAGE_SIZE as usize]).unwrap();
        state.files.insert(3, std::fs::File::open(&path).unwrap());
        let read = libc::PROT_READ as u64;
        let read_write = (libc::PROT_READ | libc::PROT_WRITE) as u64;
        let private_fixed = (libc::MAP_PRIVATE | libc::MAP_FIXED) as u64;
        let anonymous_fixed = private_fixed | libc::MAP_ANONYMOUS as u64;
        let maymove = libc::MREMAP_MAYMOVE as u64;
        for (start, fd, offset, protection, alignment) in [
            (0x0400_0000_u64, 3_u64, PAGE_SIZE, read, PAGE_SIZE),
            (0x0500_0000, u64::MAX, 0, read_write, 0),
        ] {
            let flags = if fd == 3 {
                private_fixed
            } else {
                anonymous_fixed
            };
            assert_eq!(
                syscall_result(
                    &mut memory,
                    &mut state,
                    libc::SYS_mmap,
                    [start, PAGE_SIZE, protection, flags, fd, offset]
                ),
                start as i64
            );
            assert_eq!(
                syscall_result(
                    &mut memory,
                    &mut state,
                    libc::SYS_mmap,
                    [
                        start + PAGE_SIZE,
                        PAGE_SIZE,
                        read_write,
                        anonymous_fixed,
                        u64::MAX,
                        0
                    ]
                ),
                (start + PAGE_SIZE) as i64
            );
            let moved = syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_mremap,
                [start, PAGE_SIZE, 4 * MIB, maymove, 0, 0],
            ) as u64;
            assert!(moved > MAP_32BIT_END, "{moved:#x}");
            assert_eq!(moved % (2 * MIB), alignment, "{moved:#x}");
            let physical = memory.user_range_to_guest(moved, 4 * MIB).unwrap();
            if fd == 3 {
                assert_eq!(memory.file_offset(physical), Some(PAGE_SIZE));
                assert_eq!(
                    memory.file_offset(physical + PAGE_SIZE),
                    Some(2 * PAGE_SIZE)
                );
                let mut byte = [0];
                memory.user().read(moved, &mut byte).unwrap();
                assert_eq!(byte, [7]);
            } else {
                assert_eq!(memory.file_offset(physical), None);
            }
            assert_eq!(memory.file_offset(start), None);
        }
    }

    /// In memory too tight for the preferred window, the window ends at the
    /// stack window with its user end below mmap_base; placement there is
    /// still Linux's: top-down below the vDSO gap, free hints honoured, and
    /// MAP_32BIT kept below 2 GiB.
    #[test]
    fn a_window_with_a_moved_user_end_places_mappings_as_linux_does() {
        let root = TestDir::new();
        let (mut memory, mut state, layout) =
            linux_layout_fixture(&root, 11 * 1024 * 1024 + 0x1_0000);
        assert_eq!(layout.mmap_end, 0x31_0000);
        assert_eq!(layout.mmap_user_end, MMAP_BASE - 0xef000);
        let read_write = (libc::PROT_READ | libc::PROT_WRITE) as u64;
        let anonymous = (libc::MAP_PRIVATE | libc::MAP_ANONYMOUS) as u64;
        let mut map = |memory: &mut GuestMemory, args: [u64; 6]| {
            syscall_result(memory, &mut state, libc::SYS_mmap, args)
        };
        assert_eq!(
            map(
                &mut memory,
                [0, PAGE_SIZE, read_write, anonymous, u64::MAX, 0]
            ),
            (layout.mmap_user_end - 0x8000 - PAGE_SIZE) as i64
        );
        let low = anonymous | libc::MAP_32BIT as u64;
        assert_eq!(
            map(&mut memory, [0, PAGE_SIZE, read_write, low, u64::MAX, 0]),
            (layout.identity_end - PAGE_SIZE) as i64
        );
        let hint = BOOT_RESERVED_END + 4 * PAGE_SIZE + 0x123;
        assert_eq!(
            map(
                &mut memory,
                [hint, PAGE_SIZE, read_write, anonymous, u64::MAX, 0]
            ),
            (BOOT_RESERVED_END + 4 * PAGE_SIZE) as i64
        );
    }

    /// Without a window (a static program in memory too small for one, or a
    /// memory no loader laid out), a MAP_32BIT mapping takes a free hint below
    /// 2 GiB, else the mapping range's part below 2 GiB bottom-up, else the
    /// highest free identity memory below 2 GiB and below the mapping range,
    /// even when the mapping range starts above 2 GiB.
    #[test]
    fn map_32bit_without_a_window_stays_below_two_gib() {
        let root = TestDir::new();
        let mut state = test_state(&root.0);
        let mut memory = GuestMemory::new(0, 3 * 1024 * 1024 * 1024).unwrap();
        memory.enable_user_access();
        let read_write = (libc::PROT_READ | libc::PROT_WRITE) as u64;
        let low = (libc::MAP_PRIVATE | libc::MAP_ANONYMOUS | libc::MAP_32BIT) as u64;
        let map = |memory: &mut GuestMemory, state: &mut LoadedStaticElf, args: [u64; 6]| {
            syscall_result(memory, state, libc::SYS_mmap, args)
        };
        state.mmap_base = 0xbf7f_f000;
        state.mmap_next = 0xbf7f_f000;
        state.mmap_limit = 0xbf80_0000;
        memory.set_allocation_cursors(AllocationCursors::from_elf(&state));
        assert_eq!(
            map(
                &mut memory,
                &mut state,
                [0x4000_0000, PAGE_SIZE, read_write, low, u64::MAX, 0]
            ),
            0x4000_0000
        );
        assert_eq!(
            map(
                &mut memory,
                &mut state,
                [0, PAGE_SIZE, read_write, low, u64::MAX, 0]
            ),
            (MAP_32BIT_END - PAGE_SIZE) as i64
        );
        state.mmap_base = 0x7fff_c000;
        state.mmap_next = 0x7fff_c000;
        memory.set_allocation_cursors(AllocationCursors::from_elf(&state));
        assert_eq!(
            map(
                &mut memory,
                &mut state,
                [0, 3 * PAGE_SIZE, read_write, low, u64::MAX, 0]
            ),
            0x7fff_c000
        );
        assert_eq!(
            map(
                &mut memory,
                &mut state,
                [0, PAGE_SIZE, read_write, low, u64::MAX, 0]
            ),
            0x7fff_b000
        );
    }

    /// The program break does not grow into a mapping placed in identity
    /// memory above it (a MAP_32BIT mapping without a window, or one the
    /// window could not hold), nor to the page just below it: brk returns the
    /// old break and the mapping keeps its bytes; growth that leaves a page
    /// free below the mapping succeeds.
    #[test]
    fn brk_refuses_to_grow_into_a_mapping() {
        const MIB: u64 = 1024 * 1024;
        let root = TestDir::new();
        let read_write = (libc::PROT_READ | libc::PROT_WRITE) as u64;
        let anonymous = (libc::MAP_PRIVATE | libc::MAP_ANONYMOUS) as u64;
        let low = anonymous | libc::MAP_32BIT as u64;

        // No window: the 11 MiB + 12 KiB static layout, one page of mapping
        // range, so a two-page MAP_32BIT mapping goes just below it.
        let mut state = test_state(&root.0);
        let mut memory = GuestMemory::new(0, (11 * MIB + 0x3000) as usize).unwrap();
        memory.enable_user_access();
        state.heap_base = 0x20_2000;
        state.program_break = 0x20_2000;
        state.brk_limit = 0x30_2000;
        state.mmap_base = 0x30_2000;
        state.mmap_next = 0x30_2000;
        state.mmap_limit = 0x30_3000;
        memory.set_allocation_cursors(AllocationCursors::from_elf(&state));
        // With a window: a 20 MiB mapping the 18 MiB window cannot hold.
        let (mut windowed, mut windowed_state, layout) = linux_layout_fixture(&root, 64 * MIB);
        windowed_state.heap_base = 0x30_0000;
        windowed_state.program_break = 0x30_0000;
        windowed.set_allocation_cursors(AllocationCursors::from_elf(&windowed_state));
        for (memory, state, flags, length, expected) in [
            (&mut memory, &mut state, low, 2 * PAGE_SIZE, 0x30_0000),
            (
                &mut windowed,
                &mut windowed_state,
                anonymous,
                20 * MIB,
                layout.identity_end - 20 * MIB,
            ),
        ] {
            assert_eq!(
                syscall_result(
                    memory,
                    state,
                    libc::SYS_mmap,
                    [0, length, read_write, flags, u64::MAX, 0]
                ),
                expected as i64
            );
            memory.user().write(expected, &[0x5a]).unwrap();
            let before = state.program_break;
            assert_eq!(
                syscall_result(
                    memory,
                    state,
                    libc::SYS_brk,
                    [expected + PAGE_SIZE, 0, 0, 0, 0, 0]
                ),
                before as i64
            );
            let mut byte = [0];
            memory.user().read(expected, &mut byte).unwrap();
            assert_eq!(byte, [0x5a]);
            // Linux keeps a page between the break and the mapping.
            assert_eq!(
                syscall_result(memory, state, libc::SYS_brk, [expected, 0, 0, 0, 0, 0]),
                before as i64
            );
            assert_eq!(
                syscall_result(
                    memory,
                    state,
                    libc::SYS_brk,
                    [expected - PAGE_SIZE, 0, 0, 0, 0, 0]
                ),
                (expected - PAGE_SIZE) as i64
            );
            memory.user().read(expected, &mut byte).unwrap();
            assert_eq!(byte, [0x5a]);
        }
    }

    /// Heap growth adds only whole pages above the old break's page: a
    /// mapping now in that page (the heap's page was unmapped and a private
    /// file page mapped there through a hint) keeps its bytes, permissions,
    /// reservation and file offset when the break grows past it. Growth
    /// within the break's page only moves the break, even with a mapping on
    /// the next page.
    #[test]
    fn brk_growth_leaves_the_old_break_page_alone() {
        const MIB: u64 = 1024 * 1024;
        let root = TestDir::new();
        let (mut memory, mut state, _layout) = linux_layout_fixture(&root, 64 * MIB);
        let base = 0x30_0000;
        state.heap_base = base;
        state.program_break = base;
        memory.set_allocation_cursors(AllocationCursors::from_elf(&state));
        let path = root.0.join("file.bin");
        std::fs::write(&path, vec![7; 2 * PAGE_SIZE as usize]).unwrap();
        state.files.insert(3, std::fs::File::open(&path).unwrap());
        let read = libc::PROT_READ as u64;
        let read_write = (libc::PROT_READ | libc::PROT_WRITE) as u64;
        let call = |memory: &mut GuestMemory, state: &mut LoadedStaticElf, number, args| {
            syscall_result(memory, state, number, args)
        };
        assert_eq!(
            call(
                &mut memory,
                &mut state,
                libc::SYS_brk,
                [base + 1, 0, 0, 0, 0, 0]
            ),
            (base + 1) as i64
        );
        assert_eq!(
            call(
                &mut memory,
                &mut state,
                libc::SYS_munmap,
                [base, PAGE_SIZE, 0, 0, 0, 0]
            ),
            0
        );
        assert_eq!(
            call(
                &mut memory,
                &mut state,
                libc::SYS_mmap,
                [
                    base,
                    PAGE_SIZE,
                    read,
                    libc::MAP_PRIVATE as u64,
                    3,
                    PAGE_SIZE
                ]
            ),
            base as i64
        );
        assert_eq!(
            call(
                &mut memory,
                &mut state,
                libc::SYS_brk,
                [base + PAGE_SIZE + 1, 0, 0, 0, 0, 0]
            ),
            (base + PAGE_SIZE + 1) as i64
        );
        let mut bytes = [0; 16];
        memory.user().read(base + 0x100, &mut bytes).unwrap();
        assert_eq!(bytes, [7; 16]);
        assert_eq!(
            memory.user().user_writable_prefix(base + 0x100, 1).unwrap(),
            0
        );
        assert_eq!(memory.reservation_kind(base), Some(RegionKind::Mmap));
        assert_eq!(memory.file_offset(base), Some(PAGE_SIZE));
        assert_eq!(
            memory.reservation_kind(base + PAGE_SIZE),
            Some(RegionKind::Heap)
        );

        // Growth within the break's page with a mapping on the next page.
        let next = base + 2 * PAGE_SIZE;
        let anonymous_fixed = (libc::MAP_PRIVATE | libc::MAP_ANONYMOUS | libc::MAP_FIXED) as u64;
        assert_eq!(
            call(
                &mut memory,
                &mut state,
                libc::SYS_mmap,
                [next, PAGE_SIZE, read_write, anonymous_fixed, u64::MAX, 0]
            ),
            next as i64
        );
        assert_eq!(
            call(
                &mut memory,
                &mut state,
                libc::SYS_brk,
                [base + PAGE_SIZE + 2, 0, 0, 0, 0, 0]
            ),
            (base + PAGE_SIZE + 2) as i64
        );
        assert_eq!(
            call(
                &mut memory,
                &mut state,
                libc::SYS_brk,
                [next + 1, 0, 0, 0, 0, 0]
            ),
            (base + PAGE_SIZE + 2) as i64
        );
    }

    /// Without a window, a free range that the allocation cursor splits is
    /// still found: map a page, unmap it, and three pages fit where it was.
    #[test]
    fn legacy_placement_reuses_a_hole_the_cursor_splits() {
        let root = TestDir::new();
        let mut state = test_state(&root.0);
        let mut memory = GuestMemory::new(0, 16 * 1024 * 1024).unwrap();
        memory.enable_user_access();
        state.mmap_base = 0x30_2000;
        state.mmap_next = 0x30_2000;
        state.mmap_limit = 0x30_5000;
        memory.set_allocation_cursors(AllocationCursors::from_elf(&state));
        let read_write = (libc::PROT_READ | libc::PROT_WRITE) as u64;
        let anonymous = (libc::MAP_PRIVATE | libc::MAP_ANONYMOUS) as u64;
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_mmap,
                [0, PAGE_SIZE, read_write, anonymous, u64::MAX, 0]
            ),
            0x30_2000
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_munmap,
                [0x30_2000, PAGE_SIZE, 0, 0, 0, 0]
            ),
            0
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_mmap,
                [0, 3 * PAGE_SIZE, read_write, anonymous, u64::MAX, 0]
            ),
            0x30_2000
        );
    }

    /// A page that an anonymous mapping replaces through MREMAP_FIXED no
    /// longer counts as the file page it was: moving it later places it as
    /// anonymous memory, on a large-page boundary.
    #[test]
    fn mremap_fixed_over_a_file_page_drops_its_file_offset() {
        const MIB: u64 = 1024 * 1024;
        let root = TestDir::new();
        let (mut memory, mut state, _layout) = linux_layout_fixture(&root, 128 * MIB);
        let path = root.0.join("file.bin");
        std::fs::write(&path, vec![7; 2 * PAGE_SIZE as usize]).unwrap();
        state.files.insert(3, std::fs::File::open(&path).unwrap());
        let read_write = (libc::PROT_READ | libc::PROT_WRITE) as u64;
        let anonymous_fixed = (libc::MAP_PRIVATE | libc::MAP_ANONYMOUS | libc::MAP_FIXED) as u64;
        let file_fixed = (libc::MAP_PRIVATE | libc::MAP_FIXED) as u64;
        let (anonymous, file) = (0x0400_0000_u64, 0x0500_0000_u64);
        for (address, flags, fd, offset) in [
            (anonymous, anonymous_fixed, u64::MAX, 0),
            (file, file_fixed, 3, PAGE_SIZE),
        ] {
            assert_eq!(
                syscall_result(
                    &mut memory,
                    &mut state,
                    libc::SYS_mmap,
                    [address, PAGE_SIZE, read_write, flags, fd, offset]
                ),
                address as i64
            );
        }
        assert_eq!(memory.file_offset(file), Some(PAGE_SIZE));
        let fixed_move = (libc::MREMAP_MAYMOVE | libc::MREMAP_FIXED) as u64;
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_mremap,
                [anonymous, PAGE_SIZE, PAGE_SIZE, fixed_move, file, 0]
            ),
            file as i64
        );
        assert_eq!(memory.file_offset(file), None);
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_mmap,
                [
                    file + PAGE_SIZE,
                    PAGE_SIZE,
                    read_write,
                    anonymous_fixed,
                    u64::MAX,
                    0
                ]
            ),
            (file + PAGE_SIZE) as i64
        );
        let moved = syscall_result(
            &mut memory,
            &mut state,
            libc::SYS_mremap,
            [file, PAGE_SIZE, 4 * MIB, libc::MREMAP_MAYMOVE as u64, 0, 0],
        ) as u64;
        assert!(moved > MAP_32BIT_END, "{moved:#x}");
        assert_eq!(moved % (2 * MIB), 0, "{moved:#x}");
    }

    /// mremap grows a mapping in place only while the grown range stays one run
    /// of user addresses: a page just below the identity end cannot grow into
    /// the window's physical memory, which has no identity user address.
    /// Without MREMAP_MAYMOVE that is ENOMEM; with it the mapping moves.
    #[test]
    fn mremap_does_not_grow_across_the_identity_end() {
        const MIB: u64 = 1024 * 1024;
        let root = TestDir::new();
        let mut state = test_state(&root.0);
        let mut memory = GuestMemory::new(0, (64 * MIB) as usize).unwrap();
        let layout = crate::elf::establish_linux_layout(
            &mut memory,
            BOOT_RESERVED_END + PAGE_SIZE,
            MIB,
            None,
        )
        .unwrap()
        .unwrap();
        state.mmap_base = layout.identity_end;
        state.mmap_next = layout.identity_end;
        state.mmap_limit = layout.mmap_end;
        state.brk_limit = layout.identity_end;
        memory.enable_user_access();
        let read_write = (libc::PROT_READ | libc::PROT_WRITE) as u64;
        let fixed = (libc::MAP_PRIVATE | libc::MAP_ANONYMOUS | libc::MAP_FIXED) as u64;
        let last = layout.identity_end - PAGE_SIZE;
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_mmap,
                [last, PAGE_SIZE, read_write, fixed, u64::MAX, 0]
            ),
            last as i64
        );
        assert!(
            memory
                .find_unmapped_user_range(
                    layout.identity_end,
                    layout.identity_end + PAGE_SIZE,
                    PAGE_SIZE
                )
                .is_some()
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_mremap,
                [last, PAGE_SIZE, 2 * PAGE_SIZE, 0, 0, 0]
            ),
            negative_errno(libc::ENOMEM)
        );
        assert!(memory.user_range_to_guest(last, PAGE_SIZE).is_some());
        let moved = syscall_result(
            &mut memory,
            &mut state,
            libc::SYS_mremap,
            [
                last,
                PAGE_SIZE,
                2 * PAGE_SIZE,
                libc::MREMAP_MAYMOVE as u64,
                0,
                0,
            ],
        ) as u64;
        assert_ne!(moved, last);
        assert!(memory.user().write(moved + PAGE_SIZE, &[1]).is_ok());
        assert!(memory.user().write(moved, &[1]).is_ok());
    }

    /// time(2) and gettimeofday(2) store only to writable pages, as Linux's
    /// `put_user` and `copy_to_user` do: a read-only page faults like an
    /// unmapped one. Each eight-byte scalar is stored whole or not at all,
    /// gettimeofday keeps a `tv_sec` it stored before `tv_usec` faulted, and
    /// its `tz` copy keeps the writable prefix.
    #[test]
    fn time_and_gettimeofday_store_only_to_writable_pages() {
        const READ_ONLY: u64 = 2 * PAGE_SIZE;
        const UNMAPPED: u64 = 3 * PAGE_SIZE;
        const TIMEZONE: u64 = 0x200;
        const SENTINEL: [u8; 16] = [0xa5; 16];

        let root = TestDir::new();
        let mut state = test_state(&root.0);
        let mut memory = GuestMemory::new(0, 4 * PAGE_SIZE as usize).unwrap();
        memory.enable_user_access();
        memory.map_user_range(0, 2 * PAGE_SIZE, false).unwrap();
        memory
            .map_user_permissions(READ_ONLY, PAGE_SIZE, true, false)
            .unwrap();
        let reset = |memory: &mut GuestMemory| {
            memory.write_raw(READ_ONLY - 16, &SENTINEL).unwrap();
            memory.write_raw(READ_ONLY, &SENTINEL).unwrap();
            memory.write_raw(TIMEZONE, &SENTINEL[..8]).unwrap();
        };
        let mut call = |memory: &mut GuestMemory, number: libc::c_long, a0: u64, a1: u64| {
            syscall_result(memory, &mut state, number, [a0, a1, 0, 0, 0, 0])
        };
        let bytes = |memory: &GuestMemory, address: u64| read_struct::<[u8; 8]>(memory, address);
        // A stored tv_sec is the host's, well past 2001; a stored tv_usec is
        // below a second.
        let host_seconds = |memory: &GuestMemory, address: u64| {
            read_struct::<u64>(memory, address) > 1_000_000_000
        };
        let microseconds =
            |memory: &GuestMemory, address: u64| read_struct::<u64>(memory, address) < 1_000_000;
        let zone = host_timezone();
        let efault = negative_errno(libc::EFAULT);

        // time(2): a read-only tloc, and one whose last four bytes are
        // read-only, fault without storing a byte.
        for tloc in [READ_ONLY, READ_ONLY + 0x100, READ_ONLY - 4] {
            reset(&mut memory);
            assert_eq!(
                call(&mut memory, libc::SYS_time, tloc, 0),
                efault,
                "{tloc:#x}"
            );
            assert_eq!(bytes(&memory, READ_ONLY - 8), [0xa5; 8], "{tloc:#x}");
            assert_eq!(bytes(&memory, READ_ONLY), [0xa5; 8], "{tloc:#x}");
            assert_eq!(bytes(&memory, READ_ONLY + 0x100), [0; 8], "{tloc:#x}");
        }
        reset(&mut memory);
        let seconds = call(&mut memory, libc::SYS_time, READ_ONLY - 8, 0);
        assert!(seconds > 1_000_000_000);
        assert_eq!(
            bytes(&memory, READ_ONLY - 8),
            (seconds as u64).to_ne_bytes()
        );

        // gettimeofday(2): a read-only tv faults before tz is looked at, with
        // nothing stored, whether tz is valid, unmapped or null.
        for tz in [0, TIMEZONE, UNMAPPED] {
            reset(&mut memory);
            assert_eq!(
                call(&mut memory, libc::SYS_gettimeofday, READ_ONLY, tz),
                efault,
                "{tz:#x}"
            );
            assert_eq!(bytes(&memory, READ_ONLY), [0xa5; 8], "{tz:#x}");
            assert_eq!(bytes(&memory, READ_ONLY + 8), [0xa5; 8], "{tz:#x}");
            assert_eq!(bytes(&memory, TIMEZONE), [0xa5; 8], "{tz:#x}");
        }

        // tv_sec writable, tv_usec read-only: tv_sec is stored, then EFAULT.
        reset(&mut memory);
        assert_eq!(
            call(&mut memory, libc::SYS_gettimeofday, READ_ONLY - 8, TIMEZONE),
            efault
        );
        assert!(host_seconds(&memory, READ_ONLY - 8));
        assert_eq!(bytes(&memory, READ_ONLY), [0xa5; 8]);
        assert_eq!(bytes(&memory, TIMEZONE), [0xa5; 8]);

        // tv_sec itself straddles into the read-only page: nothing stored.
        reset(&mut memory);
        assert_eq!(
            call(&mut memory, libc::SYS_gettimeofday, READ_ONLY - 4, 0),
            efault
        );
        assert_eq!(bytes(&memory, READ_ONLY - 8), [0xa5; 8]);
        assert_eq!(bytes(&memory, READ_ONLY), [0xa5; 8]);

        // A writable tv with a read-only tz: tv is stored, then EFAULT.
        reset(&mut memory);
        assert_eq!(
            call(
                &mut memory,
                libc::SYS_gettimeofday,
                READ_ONLY - 16,
                READ_ONLY
            ),
            efault
        );
        assert!(host_seconds(&memory, READ_ONLY - 16));
        assert!(microseconds(&memory, READ_ONLY - 8));
        assert_eq!(bytes(&memory, READ_ONLY), [0xa5; 8]);

        // A tz whose second half is read-only keeps its writable first half.
        reset(&mut memory);
        assert_eq!(
            call(&mut memory, libc::SYS_gettimeofday, 0, READ_ONLY - 4),
            efault
        );
        let mut expected = [0xa5; 8];
        expected[4..].copy_from_slice(&zone[0].to_ne_bytes());
        assert_eq!(bytes(&memory, READ_ONLY - 8), expected);
        assert_eq!(bytes(&memory, READ_ONLY), [0xa5; 8]);

        // Every output writable: the host's values everywhere, success.
        reset(&mut memory);
        assert_eq!(
            call(
                &mut memory,
                libc::SYS_gettimeofday,
                READ_ONLY - 16,
                TIMEZONE
            ),
            0
        );
        assert!(host_seconds(&memory, READ_ONLY - 16));
        assert!(microseconds(&memory, READ_ONLY - 8));
        assert_eq!(read_struct::<[libc::c_int; 2]>(&memory, TIMEZONE), zone);
    }

    #[test]
    fn gettimeofday_reads_the_host_clock_and_validates_outputs() {
        const TIMEVAL: u64 = 0x100;
        const TIMEZONE: u64 = 0x200;

        let root = TestDir::new();
        let mut state = test_state(&root.0);
        let mut memory = GuestMemory::new(0, PAGE_SIZE as usize).unwrap();
        let before = host_clock(libc::CLOCK_REALTIME).tv_sec;
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_gettimeofday,
                [TIMEVAL, TIMEZONE, 0, 0, 0, 0],
            ),
            0
        );
        let after = host_clock(libc::CLOCK_REALTIME).tv_sec;
        let timeval: libc::timeval = read_struct(&memory, TIMEVAL);
        assert!(before <= timeval.tv_sec && timeval.tv_sec <= after);
        assert!((0..1_000_000).contains(&timeval.tv_usec));
        let timezone: [libc::c_int; 2] = read_struct(&memory, TIMEZONE);
        assert_eq!(timezone, host_timezone());
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_gettimeofday,
                [0, 0, 0, 0, 0, 0],
            ),
            0
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_gettimeofday,
                [u64::MAX, 0, 0, 0, 0, 0],
            ),
            negative_errno(libc::EFAULT)
        );
    }

    #[test]
    fn sleep_syscalls_are_host_sleeps() {
        const REQUEST: u64 = 0x100;

        let root = TestDir::new();
        let mut state = test_state(&root.0);
        let mut memory = GuestMemory::new(0, PAGE_SIZE as usize).unwrap();
        let request = |memory: &GuestMemory, tv_sec, tv_nsec| {
            assert_eq!(
                write_struct(
                    &mut ProviderMemory(memory),
                    REQUEST,
                    &libc::timespec { tv_sec, tv_nsec },
                ),
                0
            );
        };
        // One microsecond, relative, and an absolute deadline long past.
        request(&memory, 0, 1_000);
        for args in [
            [libc::SYS_nanosleep as u64, REQUEST, u64::MAX, 0],
            [
                libc::SYS_clock_nanosleep as u64,
                libc::CLOCK_REALTIME as u64,
                0,
                REQUEST,
            ],
            [
                libc::SYS_clock_nanosleep as u64,
                libc::CLOCK_MONOTONIC as u64,
                libc::TIMER_ABSTIME as u64,
                REQUEST,
            ],
            // A CPU-time clock advances only while the process runs, so its
            // deadline is absolute (already passed), not a relative wait.
            [
                libc::SYS_clock_nanosleep as u64,
                libc::CLOCK_PROCESS_CPUTIME_ID as u64,
                libc::TIMER_ABSTIME as u64,
                REQUEST,
            ],
        ] {
            let call_args = if args[0] == libc::SYS_nanosleep as u64 {
                [args[1], args[2], 0, 0, 0, 0]
            } else {
                [args[1], args[2], args[3], 0, 0, 0]
            };
            assert_eq!(
                syscall_result(&mut memory, &mut state, args[0] as libc::c_long, call_args),
                0,
                "{args:?}"
            );
        }

        // An unreadable request faults before any sleep.
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_nanosleep,
                [0, 0, 0, 0, 0, 0],
            ),
            negative_errno(libc::EFAULT)
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_clock_nanosleep,
                [libc::CLOCK_REALTIME as u64, 0, u64::MAX, 0, 0, 0,],
            ),
            negative_errno(libc::EFAULT)
        );
        // The host kernel validates the request and the clock.
        for (tv_sec, tv_nsec) in [(-1, 0), (0, 1_000_000_000)] {
            request(&memory, tv_sec, tv_nsec);
            assert_eq!(
                syscall_result(
                    &mut memory,
                    &mut state,
                    libc::SYS_nanosleep,
                    [REQUEST, 0, 0, 0, 0, 0],
                ),
                negative_errno(libc::EINVAL)
            );
            assert_eq!(
                syscall_result(
                    &mut memory,
                    &mut state,
                    libc::SYS_clock_nanosleep,
                    [libc::CLOCK_REALTIME as u64, 0, REQUEST, 0, 0, 0],
                ),
                negative_errno(libc::EINVAL)
            );
        }
        request(&memory, 0, 1_000);
        // A clock id that names a pid or a descriptor by its host-side number
        // is refused.
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_clock_nanosleep,
                [u64::MAX, 0, REQUEST, 0, 0, 0],
            ),
            negative_errno(libc::EINVAL)
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_clock_nanosleep,
                [libc::CLOCK_THREAD_CPUTIME_ID as u64, 0, REQUEST, 0, 0, 0,],
            ),
            negative_errno(libc::EOPNOTSUPP)
        );
    }

    #[test]
    fn path_mutation_metadata_and_timestamp_syscalls_round_trip() {
        const DIRECTORY: u64 = 0x100;
        const SOURCE: u64 = 0x180;
        const HARD_LINK: u64 = 0x200;
        const SYMLINK: u64 = 0x280;
        const RENAMED: u64 = 0x300;
        const FIFO: u64 = 0x380;
        const DOT: u64 = 0x400;
        const FOLLOWED_LINK: u64 = 0x480;
        const STATFS: u64 = 0x500;

        let root = TestDir::new();
        let mut state = test_state(&root.0);
        let mut memory = GuestMemory::new(0, PAGE_SIZE as usize).unwrap();
        for (address, value) in [
            (DIRECTORY, "directory"),
            (SOURCE, "source"),
            (HARD_LINK, "hard-link"),
            (SYMLINK, "symlink"),
            (RENAMED, "renamed"),
            (FIFO, "fifo"),
            (DOT, "."),
            (FOLLOWED_LINK, "followed-link"),
        ] {
            write_c_string(&mut memory, address, value);
        }
        std::fs::write(root.0.join("source"), b"payload").unwrap();

        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_umask,
                [0o027, 0, 0, 0, 0, 0]
            ),
            0o022
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_mkdir,
                [DIRECTORY, 0o777, 0, 0, 0, 0],
            ),
            0
        );
        assert_eq!(
            std::fs::metadata(root.0.join("directory"))
                .unwrap()
                .permissions()
                .mode()
                & 0o777,
            0o750
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_linkat,
                [
                    libc::AT_FDCWD as u64,
                    SOURCE,
                    libc::AT_FDCWD as u64,
                    HARD_LINK,
                    0,
                    0
                ],
            ),
            0
        );
        assert_eq!(std::fs::read(root.0.join("hard-link")).unwrap(), b"payload");
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_symlinkat,
                [SOURCE, libc::AT_FDCWD as u64, SYMLINK, 0, 0, 0],
            ),
            0
        );
        assert_eq!(
            std::fs::read_link(root.0.join("symlink")).unwrap(),
            Path::new("source")
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_linkat,
                [
                    libc::AT_FDCWD as u64,
                    SYMLINK,
                    libc::AT_FDCWD as u64,
                    FOLLOWED_LINK,
                    libc::AT_SYMLINK_FOLLOW as u64,
                    0,
                ],
            ),
            0
        );
        assert_eq!(
            std::fs::read(root.0.join("followed-link")).unwrap(),
            b"payload"
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_renameat,
                [
                    libc::AT_FDCWD as u64,
                    HARD_LINK,
                    libc::AT_FDCWD as u64,
                    RENAMED,
                    0,
                    0
                ],
            ),
            0
        );
        assert!(!root.0.join("hard-link").exists());
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_fchmodat,
                [libc::AT_FDCWD as u64, RENAMED, 0o600, 0xdead_beef, 0, 0,],
            ),
            0
        );
        assert_eq!(
            std::fs::metadata(root.0.join("renamed")).unwrap().mode() & 0o777,
            0o600
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_utimensat,
                [libc::AT_FDCWD as u64, RENAMED, 0, 0, 0, 0],
            ),
            0
        );
        assert_eq!(
            std::fs::metadata(root.0.join("renamed")).unwrap().mtime(),
            DETERMINISTIC_METADATA_SECONDS
        );
        let fd = syscall_result(
            &mut memory,
            &mut state,
            libc::SYS_openat,
            [
                libc::AT_FDCWD as u64,
                RENAMED,
                libc::O_RDONLY as u64,
                0,
                0,
                0,
            ],
        );
        assert_eq!(fd, 3);
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_utimensat,
                [fd as u64, 0, 0, 0, 0, 0],
            ),
            0,
            "fd-based utimensat with a NULL pathname must use futimens"
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_close,
                [fd as u64, 0, 0, 0, 0, 0],
            ),
            0
        );
        const EMPTY_OPATH: u64 = 0x580;
        write_c_string(&mut memory, EMPTY_OPATH, "");
        let path_fd = syscall_result(
            &mut memory,
            &mut state,
            libc::SYS_openat,
            [libc::AT_FDCWD as u64, RENAMED, libc::O_PATH as u64, 0, 0, 0],
        );
        assert_eq!(path_fd, 3);
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_utimensat,
                [path_fd as u64, 0, 0, 0, 0, 0],
            ),
            negative_errno(libc::EBADF),
            "NULL-path timestamp updates reject O_PATH descriptors"
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_utimensat,
                [
                    path_fd as u64,
                    EMPTY_OPATH,
                    0,
                    libc::AT_EMPTY_PATH as u64,
                    0,
                    0,
                ],
            ),
            0,
            "AT_EMPTY_PATH accepts O_PATH descriptors"
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_close,
                [path_fd as u64, 0, 0, 0, 0, 0],
            ),
            0
        );

        const OMIT_TIMES: u64 = 0x600;
        const CREATED: u64 = 0x700;
        let omit = libc::timespec {
            tv_sec: 0,
            tv_nsec: libc::UTIME_OMIT,
        };
        assert_eq!(
            write_struct(&mut ProviderMemory(&memory), OMIT_TIMES, &omit),
            0
        );
        assert_eq!(
            write_struct(
                &mut ProviderMemory(&memory),
                OMIT_TIMES + std::mem::size_of::<libc::timespec>() as u64,
                &omit,
            ),
            0
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_utimensat,
                [libc::AT_FDCWD as u64, u64::MAX, OMIT_TIMES, 0, 0, 0],
            ),
            0,
            "two UTIME_OMIT values must not resolve the pathname"
        );

        write_c_string(&mut memory, CREATED, "created");
        state.umask = 0;
        let created_fd = syscall_result(
            &mut memory,
            &mut state,
            libc::SYS_openat,
            [
                libc::AT_FDCWD as u64,
                CREATED,
                (libc::O_CREAT | libc::O_EXCL | libc::O_WRONLY) as u64,
                0o666,
                0,
                0,
            ],
        );
        assert!(created_fd >= 0);
        assert_eq!(
            std::fs::metadata(root.0.join("created")).unwrap().mode() & 0o777,
            0o666,
            "the supervisor umask must not be applied after the guest umask"
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_close,
                [created_fd as u64, 0, 0, 0, 0, 0],
            ),
            0
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_unlinkat,
                [libc::AT_FDCWD as u64, CREATED, 0, 0, 0, 0],
            ),
            0
        );

        std::os::unix::fs::symlink("created-target", root.0.join("created-link")).unwrap();
        write_c_string(&mut memory, CREATED, "created-link");
        let symlink_created_fd = syscall_result(
            &mut memory,
            &mut state,
            libc::SYS_openat,
            [
                libc::AT_FDCWD as u64,
                CREATED,
                (libc::O_CREAT | libc::O_WRONLY) as u64,
                0o666,
                0,
                0,
            ],
        );
        assert!(symlink_created_fd >= 0);
        assert_eq!(
            std::fs::metadata(root.0.join("created-target"))
                .unwrap()
                .mode()
                & 0o777,
            0o666,
            "guest umask must apply when O_CREAT follows a dangling symlink"
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_close,
                [symlink_created_fd as u64, 0, 0, 0, 0, 0],
            ),
            0
        );

        let protected = root.0.join("protected");
        std::fs::write(&protected, b"payload").unwrap();
        std::fs::set_permissions(&protected, std::fs::Permissions::from_mode(0o600)).unwrap();
        let protected_file = std::fs::File::open(&protected).unwrap();
        write_c_string(
            &mut memory,
            CREATED,
            &format!("/proc/self/fd/{}", protected_file.as_raw_fd()),
        );
        assert!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_fchmodat,
                [libc::AT_FDCWD as u64, CREATED, 0o777, 0, 0, 0],
            ) < 0,
            "guest mutations must not follow supervisor procfs descriptors"
        );
        assert_eq!(std::fs::metadata(&protected).unwrap().mode() & 0o777, 0o600);
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_mknodat,
                [
                    libc::AT_FDCWD as u64,
                    FIFO,
                    (libc::S_IFIFO | 0o666) as u64,
                    0,
                    0,
                    0
                ],
            ),
            0
        );
        assert!(
            std::fs::symlink_metadata(root.0.join("fifo"))
                .unwrap()
                .file_type()
                .is_fifo()
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_statfs,
                [DOT, STATFS, 0, 0, 0, 0],
            ),
            0
        );
        let statfs: libc::statfs = read_struct(&memory, STATFS);
        assert_ne!(statfs.f_type, 0);

        for path in [RENAMED, SYMLINK, FIFO, FOLLOWED_LINK] {
            assert_eq!(
                syscall_result(
                    &mut memory,
                    &mut state,
                    libc::SYS_unlinkat,
                    [libc::AT_FDCWD as u64, path, 0, 0, 0, 0],
                ),
                0
            );
        }
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_unlinkat,
                [
                    libc::AT_FDCWD as u64,
                    DIRECTORY,
                    libc::AT_REMOVEDIR as u64,
                    0,
                    0,
                    0,
                ],
            ),
            0
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_mkdirat,
                [99, DIRECTORY, 0o755, 0, 0, 0],
            ),
            negative_errno(libc::EBADF)
        );
    }

    #[test]
    fn fchmodat2_matches_linux_flags_empty_path_and_error_ordering() {
        const FILE: u64 = 0x100;
        const LINK: u64 = 0x200;
        const MISSING: u64 = 0x300;
        const EMPTY: u64 = 0x400;
        const PROTECTED: u64 = 0x500;
        const SYNTHETIC_PROC: u64 = 0x600;

        let root = TestDir::new();
        let mut state = test_state(&root.0);
        let mut memory = GuestMemory::new(0, PAGE_SIZE as usize).unwrap();
        for (address, value) in [
            (FILE, "file"),
            (LINK, "link"),
            (MISSING, "missing"),
            (EMPTY, ""),
            (SYNTHETIC_PROC, "/proc/self/maps"),
        ] {
            write_c_string(&mut memory, address, value);
        }
        std::fs::write(root.0.join("file"), b"payload").unwrap();
        std::fs::set_permissions(root.0.join("file"), std::fs::Permissions::from_mode(0o600))
            .unwrap();
        std::os::unix::fs::symlink("file", root.0.join("link")).unwrap();

        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_fchmodat2,
                [
                    libc::AT_FDCWD as u64,
                    FILE,
                    0o640,
                    0,
                    0xdead_beef,
                    0xcafe_babe,
                ],
            ),
            0
        );
        assert_eq!(
            std::fs::metadata(root.0.join("file")).unwrap().mode() & 0o7777,
            0o640
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_fchmodat2,
                [
                    libc::AT_FDCWD as u64,
                    FILE,
                    0o600,
                    libc::AT_SYMLINK_NOFOLLOW as u64,
                    0,
                    0,
                ],
            ),
            0
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_fchmodat2,
                [libc::AT_FDCWD as u64, LINK, 0o644, 0, 0, 0],
            ),
            0
        );
        assert_eq!(
            std::fs::metadata(root.0.join("file")).unwrap().mode() & 0o7777,
            0o644
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_fchmodat2,
                [
                    libc::AT_FDCWD as u64,
                    LINK,
                    0o600,
                    libc::AT_SYMLINK_NOFOLLOW as u64,
                    0,
                    0,
                ],
            ),
            negative_errno(libc::EOPNOTSUPP)
        );
        assert_eq!(
            std::fs::metadata(root.0.join("file")).unwrap().mode() & 0o7777,
            0o644
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_fchmodat2,
                [libc::AT_FDCWD as u64, MISSING, 0o600, 0, 0, 0],
            ),
            negative_errno(libc::ENOENT)
        );

        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_fchmodat2,
                [99, u64::MAX, 0o600, 0xffff, 0, 0],
            ),
            negative_errno(libc::EINVAL),
            "invalid flags precede pathname and dirfd checks"
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_fchmodat2,
                [99, u64::MAX, 0o600, 0, 0, 0],
            ),
            negative_errno(libc::EFAULT),
            "pathname access precedes a relative-path dirfd check"
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_fchmodat2,
                [99, EMPTY, 0o600, 0, 0, 0],
            ),
            negative_errno(libc::ENOENT)
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_fchmodat2,
                [99, EMPTY, 0o600, libc::AT_EMPTY_PATH as u64, 0, 0],
            ),
            negative_errno(libc::EBADF)
        );

        let file_fd = syscall_result(
            &mut memory,
            &mut state,
            libc::SYS_openat,
            [libc::AT_FDCWD as u64, FILE, libc::O_PATH as u64, 0, 0, 0],
        );
        assert_eq!(file_fd, 3);
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_fchmodat2,
                [
                    file_fd as u64,
                    EMPTY,
                    !0o7777_u64 | 0o640,
                    libc::AT_EMPTY_PATH as u64,
                    0,
                    0,
                ],
            ),
            0
        );
        assert_eq!(
            std::fs::metadata(root.0.join("file")).unwrap().mode() & 0o7777,
            0o640
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_fchmodat2,
                [
                    file_fd as u64,
                    EMPTY,
                    0o600,
                    (libc::AT_EMPTY_PATH | libc::AT_SYMLINK_NOFOLLOW) as u64,
                    0,
                    0,
                ],
            ),
            0
        );
        assert_eq!(
            std::fs::metadata(root.0.join("file")).unwrap().mode() & 0o7777,
            0o600
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_close,
                [file_fd as u64, 0, 0, 0, 0, 0],
            ),
            0
        );

        let link_fd = syscall_result(
            &mut memory,
            &mut state,
            libc::SYS_openat,
            [
                libc::AT_FDCWD as u64,
                LINK,
                (libc::O_PATH | libc::O_NOFOLLOW) as u64,
                0,
                0,
                0,
            ],
        );
        assert_eq!(link_fd, 3);
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_fchmodat2,
                [
                    link_fd as u64,
                    EMPTY,
                    0o600,
                    (libc::AT_EMPTY_PATH | libc::AT_SYMLINK_NOFOLLOW) as u64,
                    0,
                    0,
                ],
            ),
            negative_errno(libc::EOPNOTSUPP)
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_close,
                [link_fd as u64, 0, 0, 0, 0, 0],
            ),
            0
        );

        let synthetic_proc_fd = syscall_result(
            &mut memory,
            &mut state,
            libc::SYS_openat,
            [
                libc::AT_FDCWD as u64,
                SYNTHETIC_PROC,
                libc::O_RDONLY as u64,
                0,
                0,
                0,
            ],
        );
        assert_eq!(synthetic_proc_fd, 3);
        assert!(
            state
                .proc_files
                .contains_key(&(synthetic_proc_fd as libc::c_int))
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_fchmodat2,
                [
                    synthetic_proc_fd as u64,
                    EMPTY,
                    0o777,
                    libc::AT_EMPTY_PATH as u64,
                    0,
                    0,
                ],
            ),
            negative_errno(libc::EACCES)
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_close,
                [synthetic_proc_fd as u64, 0, 0, 0, 0, 0],
            ),
            0
        );

        let protected = root.0.join("protected");
        std::fs::write(&protected, b"payload").unwrap();
        std::fs::set_permissions(&protected, std::fs::Permissions::from_mode(0o600)).unwrap();
        let protected_file = std::fs::File::open(&protected).unwrap();
        write_c_string(
            &mut memory,
            PROTECTED,
            &format!("/proc/self/fd/{}", protected_file.as_raw_fd()),
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_fchmodat2,
                [libc::AT_FDCWD as u64, PROTECTED, 0o777, 0, 0, 0],
            ),
            negative_errno(libc::EACCES)
        );
        assert_eq!(std::fs::metadata(protected).unwrap().mode() & 0o7777, 0o600);
    }

    #[test]
    fn read_path_at_preserves_trailing_slashes_and_edge_cases() {
        const EMPTY: u64 = 0x900;

        let root = TestDir::new();
        std::fs::create_dir_all(root.0.join("nested/existing")).unwrap();
        std::fs::write(root.0.join("regular"), b"payload").unwrap();
        let state = test_state(&root.0);
        let mut memory = GuestMemory::new(0, PAGE_SIZE as usize).unwrap();
        let absolute = format!("{}/absolute///", root.0.display());
        let cases = [
            (0x100, "new/"),
            (0x200, "new///"),
            (0x300, "nested//new///"),
            (0x400, absolute.as_str()),
            (0x500, "nested/existing///"),
            (0x600, "regular///"),
            (0x700, "/"),
            (0x800, "///"),
        ];

        for (address, value) in cases {
            write_c_string(&mut memory, address, value);
            let (_, path) = read_path_at(&memory, &state, libc::AT_FDCWD, address, false)
                .unwrap_or_else(|error| panic!("{value:?} failed with {error}"));
            assert_eq!(path.to_bytes(), value.as_bytes(), "{value:?}");
        }

        write_c_string(&mut memory, EMPTY, "");
        let (_, empty) = read_path_at(&memory, &state, libc::AT_FDCWD, EMPTY, true).unwrap();
        assert!(empty.to_bytes().is_empty());
        assert_eq!(
            read_path_at(&memory, &state, libc::AT_FDCWD, EMPTY, false).unwrap_err(),
            negative_errno(libc::ENOENT)
        );
    }

    #[test]
    fn mkdir_with_trailing_slash_creates_git_hooks_directory() {
        const HOOKS: u64 = 0x100;
        const OBJECTS: u64 = 0x300;
        const REFS: u64 = 0x500;

        let root = TestDir::new();
        std::fs::create_dir_all(root.0.join("repo/.git")).unwrap();
        let mut state = test_state(&root.0);
        state
            .files
            .insert(3, std::fs::File::open(root.0.join("repo")).unwrap());
        let mut memory = GuestMemory::new(0, PAGE_SIZE as usize).unwrap();
        write_c_string(&mut memory, HOOKS, "repo/.git/hooks/");
        write_c_string(&mut memory, OBJECTS, ".git/objects///");
        write_c_string(
            &mut memory,
            REFS,
            &format!("{}/repo/.git/refs///", root.0.display()),
        );

        // Mutation check: restoring the old last-slash parent selection makes
        // the first mkdir return ENOENT instead of creating the hooks directory.

        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_mkdir,
                [HOOKS, 0o755, 0, 0, 0, 0],
            ),
            0
        );
        assert!(root.0.join("repo/.git/hooks").is_dir());
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_mkdirat,
                [3, OBJECTS, 0o755, 0, 0, 0],
            ),
            0
        );
        assert!(root.0.join("repo/.git/objects").is_dir());
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_mkdir,
                [REFS, 0o755, 0, 0, 0, 0],
            ),
            0
        );
        assert!(root.0.join("repo/.git/refs").is_dir());
    }

    #[test]
    fn trailing_slash_keeps_linux_target_semantics() {
        const DIRECTORY: u64 = 0x100;
        const REGULAR: u64 = 0x300;
        const ROOT: u64 = 0x500;
        const REPEATED_ROOT: u64 = 0x700;
        const EMPTY: u64 = 0x900;

        let root = TestDir::new();
        std::fs::create_dir(root.0.join("directory")).unwrap();
        std::fs::set_permissions(
            root.0.join("directory"),
            std::fs::Permissions::from_mode(0o755),
        )
        .unwrap();
        std::fs::write(root.0.join("regular"), b"payload").unwrap();
        std::fs::set_permissions(
            root.0.join("regular"),
            std::fs::Permissions::from_mode(0o600),
        )
        .unwrap();
        let mut state = test_state(&root.0);
        let mut memory = GuestMemory::new(0, PAGE_SIZE as usize).unwrap();
        for (address, value) in [
            (DIRECTORY, "directory///"),
            (REGULAR, "regular///"),
            (ROOT, "/"),
            (REPEATED_ROOT, "///"),
            (EMPTY, ""),
        ] {
            write_c_string(&mut memory, address, value);
        }

        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_chmod,
                [DIRECTORY, 0o711, 0, 0, 0, 0],
            ),
            0
        );
        assert_eq!(
            std::fs::metadata(root.0.join("directory")).unwrap().mode() & 0o777,
            0o711
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_chmod,
                [REGULAR, 0o777, 0, 0, 0, 0],
            ),
            negative_errno(libc::ENOTDIR)
        );
        assert_eq!(
            std::fs::metadata(root.0.join("regular")).unwrap().mode() & 0o777,
            0o600
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_unlink,
                [REGULAR, 0, 0, 0, 0, 0],
            ),
            negative_errno(libc::ENOTDIR)
        );
        assert!(root.0.join("regular").exists());
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_mkdir,
                [DIRECTORY, 0o755, 0, 0, 0, 0],
            ),
            negative_errno(libc::EEXIST)
        );
        for address in [ROOT, REPEATED_ROOT] {
            assert_eq!(
                syscall_result(
                    &mut memory,
                    &mut state,
                    libc::SYS_mkdir,
                    [address, 0o755, 0, 0, 0, 0],
                ),
                negative_errno(libc::EEXIST)
            );
        }
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_mkdir,
                [EMPTY, 0o755, 0, 0, 0, 0],
            ),
            negative_errno(libc::ENOENT)
        );
    }

    #[test]
    fn all_read_path_at_mutation_dispatchers_reject_procfs_with_trailing_slash() {
        const PROTECTED: u64 = 0x100;
        const LOCAL_SOURCE: u64 = 0x500;

        let root = TestDir::new();
        std::fs::write(root.0.join("local-source"), b"payload").unwrap();
        let mut state = test_state(&root.0);
        let mut memory = GuestMemory::new(0, PAGE_SIZE as usize).unwrap();
        write_c_string(
            &mut memory,
            PROTECTED,
            &format!(
                "/proc/{}/reverie-kvm-mutation-missing///",
                std::process::id()
            ),
        );
        write_c_string(&mut memory, LOCAL_SOURCE, "local-source");
        let at_fdcwd = libc::AT_FDCWD as u64;
        let calls = [
            ("mkdir", libc::SYS_mkdir, [PROTECTED, 0o755, 0, 0, 0, 0]),
            (
                "mkdirat",
                libc::SYS_mkdirat,
                [at_fdcwd, PROTECTED, 0o755, 0, 0, 0],
            ),
            ("unlink", libc::SYS_unlink, [PROTECTED, 0, 0, 0, 0, 0]),
            ("rmdir", libc::SYS_rmdir, [PROTECTED, 0, 0, 0, 0, 0]),
            (
                "unlinkat",
                libc::SYS_unlinkat,
                [at_fdcwd, PROTECTED, 0, 0, 0, 0],
            ),
            (
                "rename",
                libc::SYS_rename,
                [LOCAL_SOURCE, PROTECTED, 0, 0, 0, 0],
            ),
            (
                "renameat",
                libc::SYS_renameat,
                [at_fdcwd, LOCAL_SOURCE, at_fdcwd, PROTECTED, 0, 0],
            ),
            (
                "renameat2",
                libc::SYS_renameat2,
                [at_fdcwd, LOCAL_SOURCE, at_fdcwd, PROTECTED, 0, 0],
            ),
            (
                "link",
                libc::SYS_link,
                [LOCAL_SOURCE, PROTECTED, 0, 0, 0, 0],
            ),
            (
                "linkat",
                libc::SYS_linkat,
                [at_fdcwd, LOCAL_SOURCE, at_fdcwd, PROTECTED, 0, 0],
            ),
            (
                "symlink",
                libc::SYS_symlink,
                [LOCAL_SOURCE, PROTECTED, 0, 0, 0, 0],
            ),
            (
                "symlinkat",
                libc::SYS_symlinkat,
                [LOCAL_SOURCE, at_fdcwd, PROTECTED, 0, 0, 0],
            ),
            ("chmod", libc::SYS_chmod, [PROTECTED, 0o600, 0, 0, 0, 0]),
            (
                "fchmodat",
                libc::SYS_fchmodat,
                [at_fdcwd, PROTECTED, 0o600, 0, 0, 0],
            ),
            (
                "mknod",
                libc::SYS_mknod,
                [PROTECTED, (libc::S_IFIFO | 0o600) as u64, 0, 0, 0, 0],
            ),
            (
                "mknodat",
                libc::SYS_mknodat,
                [at_fdcwd, PROTECTED, (libc::S_IFIFO | 0o600) as u64, 0, 0, 0],
            ),
            (
                "utimensat",
                libc::SYS_utimensat,
                [at_fdcwd, PROTECTED, 0, 0, 0, 0],
            ),
        ];
        assert_eq!(calls.len(), 17);

        for (name, number, args) in calls {
            assert_eq!(
                syscall_result(&mut memory, &mut state, number, args),
                negative_errno(libc::EACCES),
                "{name} did not preserve the procfs mutation guard"
            );
        }
        assert_eq!(
            std::fs::read(root.0.join("local-source")).unwrap(),
            b"payload"
        );
    }

    #[test]
    fn utimensat_rejects_empty_paths_on_procfs_and_synthetic_proc_descriptors() {
        const EMPTY: u64 = 0x500;
        const CHILD: u64 = 0x700;

        let root = TestDir::new();
        let mut state = test_state(&root.0);
        let mut memory = GuestMemory::new(0, 2 * PAGE_SIZE as usize).unwrap();
        // A procfs descriptor the guest holds, as one it inherited: no guest
        // open reaches procfs.
        let proc_directory_fd: i64 = 9;
        state.files.insert(9, std::fs::File::open("/proc").unwrap());
        let proc_file_fd = open_readonly(&mut memory, &mut state, "/proc/self/maps");
        assert!(proc_file_fd >= 0);
        write_c_string(&mut memory, EMPTY, "");
        write_c_string(&mut memory, CHILD, "child/");

        for (name, fd, path, flags) in [
            ("directory NULL", proc_directory_fd, 0, 0),
            (
                "directory empty",
                proc_directory_fd,
                EMPTY,
                libc::AT_EMPTY_PATH as u64,
            ),
            ("file NULL", proc_file_fd, 0, 0),
            (
                "file empty",
                proc_file_fd,
                EMPTY,
                libc::AT_EMPTY_PATH as u64,
            ),
        ] {
            assert_eq!(
                syscall_result(
                    &mut memory,
                    &mut state,
                    libc::SYS_utimensat,
                    [fd as u64, path, 0, flags, 0, 0],
                ),
                negative_errno(libc::EACCES),
                "{name} mutated a procfs or synthetic proc backing descriptor"
            );
        }

        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_mkdirat,
                [proc_file_fd as u64, CHILD, 0o755, 0, 0, 0],
            ),
            negative_errno(libc::ENOTDIR),
            "a nonempty path under a synthetic regular file retains ENOTDIR"
        );
    }

    #[test]
    fn rmdir_removes_empty_directories_like_unlinkat_removedir() {
        const DIRECTORY: u64 = 0x100;
        const FILE: u64 = 0x200;
        const NONEMPTY: u64 = 0x300;
        const MISSING: u64 = 0x400;

        let root = TestDir::new();
        let mut state = test_state(&root.0);
        let mut memory = GuestMemory::new(0, PAGE_SIZE as usize).unwrap();
        for (address, value) in [
            (DIRECTORY, "directory"),
            (FILE, "file"),
            (NONEMPTY, "nonempty"),
            (MISSING, "missing"),
        ] {
            write_c_string(&mut memory, address, value);
        }

        // A bare rmdir(2) removes an empty directory. Regression: this syscall
        // previously fell through to ENOSYS under the KVM backend, so coreutils
        // `rmdir` and `mktemp -d` cleanup failed even though `rm -rf` (which
        // uses unlinkat(AT_REMOVEDIR)) worked.
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_mkdir,
                [DIRECTORY, 0o755, 0, 0, 0, 0],
            ),
            0
        );
        assert!(root.0.join("directory").is_dir());
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_rmdir,
                [DIRECTORY, 0, 0, 0, 0, 0],
            ),
            0
        );
        assert!(!root.0.join("directory").exists());

        // rmdir on a missing path reports ENOENT, not ENOSYS.
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_rmdir,
                [MISSING, 0, 0, 0, 0, 0],
            ),
            negative_errno(libc::ENOENT)
        );

        // rmdir on a regular file reports ENOTDIR.
        std::fs::write(root.0.join("file"), b"payload").unwrap();
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_rmdir,
                [FILE, 0, 0, 0, 0, 0],
            ),
            negative_errno(libc::ENOTDIR)
        );

        // rmdir refuses a non-empty directory with ENOTEMPTY.
        std::fs::create_dir(root.0.join("nonempty")).unwrap();
        std::fs::write(root.0.join("nonempty/child"), b"payload").unwrap();
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_rmdir,
                [NONEMPTY, 0, 0, 0, 0, 0],
            ),
            negative_errno(libc::ENOTEMPTY)
        );
    }

    #[test]
    fn descriptor_duplication_and_fchmod_preserve_guest_fd_semantics() {
        let root = TestDir::new();
        let path = root.0.join("descriptor");
        std::fs::write(&path, b"payload").unwrap();
        let mut state = test_state(&root.0);
        state.files.insert(
            3,
            std::fs::OpenOptions::new()
                .read(true)
                .write(true)
                .open(&path)
                .unwrap(),
        );
        let mut memory = GuestMemory::new(0, PAGE_SIZE as usize).unwrap();

        assert_eq!(
            syscall_result(&mut memory, &mut state, libc::SYS_dup, [3, 0, 0, 0, 0, 0]),
            4
        );
        assert_eq!(
            syscall_result(&mut memory, &mut state, libc::SYS_dup2, [3, 0, 0, 0, 0, 0],),
            0
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_fchmod,
                [4, 0o640, 0, 0, 0, 0],
            ),
            0
        );
        assert_eq!(std::fs::metadata(&path).unwrap().mode() & 0o777, 0o640);
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_dup3,
                [3, 3, libc::O_CLOEXEC as u64, 0, 0, 0],
            ),
            negative_errno(libc::EINVAL)
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_dup3,
                [3, 9, u64::MAX, 0, 0, 0],
            ),
            negative_errno(libc::EINVAL)
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_dup3,
                [u64::MAX, 9, u64::MAX, 0, 0, 0],
            ),
            negative_errno(libc::EINVAL),
            "dup3 validates flags before the old descriptor"
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_dup3,
                [3, 10, 1_u64 << 32, 0, 0, 0],
            ),
            10,
            "dup3 flags use the low 32-bit Linux int ABI"
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_dup3,
                [u64::MAX, 11, 1_u64 << 32, 0, 0, 0],
            ),
            negative_errno(libc::EBADF)
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_close,
                [10, 0, 0, 0, 0, 0],
            ),
            0
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_dup3,
                [(1_u64 << 32) | 3, 90, 0, 0, 0, 0],
            ),
            90
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_dup3,
                [3, (1_u64 << 32) | 91, 0, 0, 0, 0],
            ),
            91
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_close,
                [90, 0, 0, 0, 0, 0],
            ),
            0
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_close,
                [91, 0, 0, 0, 0, 0],
            ),
            0
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_fcntl,
                [4, libc::F_SETFD as u64, libc::FD_CLOEXEC as u64, 0, 0, 0],
            ),
            0
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_fcntl,
                [4, libc::F_GETFD as u64, 0, 0, 0, 0],
            ),
            i64::from(libc::FD_CLOEXEC)
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_fcntl,
                [4, libc::F_DUPFD as u64, 10, 0, 0, 0],
            ),
            10
        );
        assert!(state.files.contains_key(&10));
        assert!(!state.cloexec_fds.contains(&10));
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_fcntl,
                [4, libc::F_DUPFD_CLOEXEC as u64, 10, 0, 0, 0],
            ),
            11
        );
        assert!(state.cloexec_fds.contains(&11));
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_fcntl,
                [4, libc::F_DUPFD as u64, u64::MAX, 0, 0, 0],
            ),
            negative_errno(libc::EINVAL)
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_fcntl,
                [4, libc::F_DUPFD as u64, GUEST_NOFILE_LIMIT as u64, 0, 0, 0,],
            ),
            negative_errno(libc::EINVAL)
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_fcntl,
                [u64::MAX, libc::F_DUPFD as u64, 0, 0, 0, 0],
            ),
            negative_errno(libc::EBADF)
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_fcntl,
                [(1_u64 << 32) | 4, libc::F_DUPFD as u64, 12, 0, 0, 0],
            ),
            12,
            "fcntl source fds use the low 32-bit Linux ABI"
        );
        for fd in [10, 11, 12] {
            assert_eq!(
                syscall_result(
                    &mut memory,
                    &mut state,
                    libc::SYS_close,
                    [fd, 0, 0, 0, 0, 0],
                ),
                0
            );
        }
        assert_eq!(
            syscall_result(&mut memory, &mut state, libc::SYS_close, [0, 0, 0, 0, 0, 0],),
            0
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_read,
                [0, 0x100, 1, 0, 0, 0],
            ),
            negative_errno(libc::EBADF)
        );
    }

    #[test]
    fn ioctl_cloexec_commands_update_guest_descriptor_flags() {
        let root = TestDir::new();
        let mut state = test_state(&root.0);
        state
            .files
            .insert(3, std::fs::File::open("/dev/null").unwrap());
        let memory = GuestMemory::new(0, PAGE_SIZE as usize).unwrap();
        let mut executor = ElfExecutor::new(state, false);

        assert_eq!(
            executor.execute(
                &SyscallRequest::new(libc::SYS_ioctl as u64, [3, libc::FIOCLEX, 0, 0, 0, 0],),
                &memory,
            ),
            0
        );
        assert_eq!(
            executor.execute(
                &SyscallRequest::new(
                    libc::SYS_fcntl as u64,
                    [3, libc::F_GETFD as u64, 0, 0, 0, 0],
                ),
                &memory,
            ),
            i64::from(libc::FD_CLOEXEC)
        );
        assert_eq!(
            executor.execute(
                &SyscallRequest::new(libc::SYS_ioctl as u64, [3, libc::FIONCLEX, 0, 0, 0, 0],),
                &memory,
            ),
            0
        );
        assert_eq!(
            executor.execute(
                &SyscallRequest::new(
                    libc::SYS_fcntl as u64,
                    [3, libc::F_GETFD as u64, 0, 0, 0, 0],
                ),
                &memory,
            ),
            0
        );
        // The host descriptor remains private even when the guest clears its
        // independently modeled close-on-exec bit.
        let host_fd = executor.state.files.get(&3).unwrap().as_raw_fd();
        assert_ne!(
            unsafe { libc::fcntl(host_fd, libc::F_GETFD) } & libc::FD_CLOEXEC,
            0
        );
        assert_eq!(
            executor.execute(
                &SyscallRequest::new(libc::SYS_ioctl as u64, [99, libc::FIOCLEX, 0, 0, 0, 0],),
                &memory,
            ),
            negative_errno(libc::EBADF)
        );
        assert_eq!(
            executor.execute(
                &SyscallRequest::new(libc::SYS_ioctl as u64, [3, SIOCETHTOOL, 0, 0, 0, 0],),
                &memory,
            ),
            negative_errno(libc::ENODEV)
        );
    }

    #[test]
    fn ioctl_terminal_queries_report_real_tty_ness() {
        // A real terminal answers TCGETS/TIOCGWINSZ successfully; a non-terminal
        // descriptor answers ENOTTY. The executor must forward these ioctls to
        // the host descriptor and report the real answer, so a guest's isatty()
        // matches the ptrace backend instead of always seeing a non-tty.
        let root = TestDir::new();
        let mut state = test_state(&root.0);

        // Open a pseudo-terminal; the slave end is a real tty.
        let mut master: libc::c_int = -1;
        let mut slave: libc::c_int = -1;
        let rc = unsafe {
            libc::openpty(
                &mut master,
                &mut slave,
                std::ptr::null_mut(),
                std::ptr::null(),
                std::ptr::null(),
            )
        };
        assert_eq!(rc, 0, "openpty failed: {}", std::io::Error::last_os_error());

        // Guest fd 3 -> the tty slave; guest fd 4 -> /dev/null (not a tty).
        // SAFETY: `slave` is a freshly opened, owned fd handed to the File.
        state
            .files
            .insert(3, unsafe { std::fs::File::from_raw_fd(slave) });
        state
            .files
            .insert(4, std::fs::File::open("/dev/null").unwrap());

        let memory = GuestMemory::new(0, PAGE_SIZE as usize).unwrap();
        let mut executor = ElfExecutor::new(state, false);

        // TCGETS on the tty succeeds -> isatty() == true.
        assert_eq!(
            executor.execute(
                &SyscallRequest::new(libc::SYS_ioctl as u64, [3, libc::TCGETS, 0x100, 0, 0, 0]),
                &memory,
            ),
            0,
        );
        // TIOCGWINSZ on the tty succeeds.
        assert_eq!(
            executor.execute(
                &SyscallRequest::new(
                    libc::SYS_ioctl as u64,
                    [3, libc::TIOCGWINSZ, 0x100, 0, 0, 0]
                ),
                &memory,
            ),
            0,
        );
        // TCGETS on a non-tty forwards to the host and reports the real ENOTTY,
        // so isatty() stays false for pipes/files (piped output is unchanged).
        assert_eq!(
            executor.execute(
                &SyscallRequest::new(libc::SYS_ioctl as u64, [4, libc::TCGETS, 0x100, 0, 0, 0]),
                &memory,
            ),
            negative_errno(libc::ENOTTY),
        );

        // SAFETY: `master` is the still-open master end owned by this test.
        unsafe {
            libc::close(master);
        }
    }

    #[test]
    fn signal_state_round_trips_and_filters_unmaskable_signals() {
        const ACTION: u64 = 0x100;
        const OLD_ACTION: u64 = 0x180;
        const MASK: u64 = 0x200;
        const OLD_MASK: u64 = 0x280;
        const ALT_STACK: u64 = 0x300;
        const OLD_ALT_STACK: u64 = 0x380;

        let root = TestDir::new();
        let mut state = test_state(&root.0);
        let mut memory = GuestMemory::new(0, PAGE_SIZE as usize).unwrap();
        let mut action = [0x5a; KERNEL_SIGACTION_SIZE];
        action[KERNEL_SIGACTION_SIZE - KERNEL_SIGSET_SIZE..].fill(u8::MAX);
        let mut expected_action = action;
        for signal in [libc::SIGKILL, libc::SIGSTOP] {
            let bit = (signal - 1) as usize;
            expected_action[KERNEL_SIGACTION_SIZE - KERNEL_SIGSET_SIZE + bit / 8] &=
                !(1 << (bit % 8));
        }
        memory.write(ACTION, &action).unwrap();
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_rt_sigaction,
                [
                    libc::SIGUSR1 as u64,
                    ACTION,
                    OLD_ACTION,
                    KERNEL_SIGSET_SIZE as u64,
                    0,
                    0,
                ],
            ),
            0
        );
        assert_eq!(
            read_guest_bytes::<KERNEL_SIGACTION_SIZE>(&ProviderMemory(&memory), OLD_ACTION)
                .unwrap(),
            [0; KERNEL_SIGACTION_SIZE]
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_rt_sigaction,
                [
                    libc::SIGUSR1 as u64,
                    0,
                    OLD_ACTION,
                    KERNEL_SIGSET_SIZE as u64,
                    0,
                    0,
                ],
            ),
            0
        );
        assert_eq!(
            read_guest_bytes::<KERNEL_SIGACTION_SIZE>(&ProviderMemory(&memory), OLD_ACTION)
                .unwrap(),
            expected_action
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_rt_sigaction,
                [
                    libc::SIGKILL as u64,
                    ACTION,
                    0,
                    KERNEL_SIGSET_SIZE as u64,
                    0,
                    0,
                ],
            ),
            negative_errno(libc::EINVAL)
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_rt_sigaction,
                [
                    libc::SIGUSR2 as u64,
                    ACTION,
                    u64::MAX,
                    KERNEL_SIGSET_SIZE as u64,
                    0,
                    0,
                ],
            ),
            negative_errno(libc::EFAULT)
        );
        assert_eq!(
            test_signal_action(&state, libc::SIGUSR2),
            Some(expected_action),
            "new sigaction remains installed if copying old action fails"
        );

        memory.write(MASK, &[u8::MAX; KERNEL_SIGSET_SIZE]).unwrap();
        memory.write(OLD_MASK, &[0x33; KERNEL_SIGSET_SIZE]).unwrap();
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_rt_sigprocmask,
                [99, MASK, OLD_MASK, KERNEL_SIGSET_SIZE as u64, 0, 0],
            ),
            negative_errno(libc::EINVAL)
        );
        assert_eq!(test_blocked_mask(&state), [0; KERNEL_SIGSET_SIZE]);
        assert_eq!(
            read_guest_bytes::<KERNEL_SIGSET_SIZE>(&ProviderMemory(&memory), OLD_MASK).unwrap(),
            [0x33; KERNEL_SIGSET_SIZE],
            "invalid how must not copy the old mask"
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_rt_sigprocmask,
                [
                    libc::SIG_SETMASK as u64,
                    MASK,
                    OLD_MASK,
                    KERNEL_SIGSET_SIZE as u64,
                    0,
                    0,
                ],
            ),
            0
        );
        assert_eq!(
            read_guest_bytes::<KERNEL_SIGSET_SIZE>(&ProviderMemory(&memory), OLD_MASK).unwrap(),
            [0; KERNEL_SIGSET_SIZE]
        );
        assert_eq!(
            test_blocked_mask(&state)[1] & 1,
            0,
            "SIGKILL must remain unblocked"
        );
        assert_eq!(
            test_blocked_mask(&state)[2] & 4,
            0,
            "SIGSTOP must remain unblocked"
        );
        memory.write(MASK, &[0; KERNEL_SIGSET_SIZE]).unwrap();
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_rt_sigprocmask,
                [
                    libc::SIG_SETMASK as u64,
                    MASK,
                    u64::MAX,
                    KERNEL_SIGSET_SIZE as u64,
                    0,
                    0,
                ],
            ),
            negative_errno(libc::EFAULT)
        );
        assert_eq!(
            test_blocked_mask(&state),
            [0; KERNEL_SIGSET_SIZE],
            "new signal mask remains installed if copying the old mask fails"
        );

        let stack = GuestStack {
            sp: 0x800,
            flags: 0,
            size: libc::MINSIGSTKSZ as u64,
        };
        assert_eq!(
            write_bytes(&mut ProviderMemory(&memory), ALT_STACK, &stack.encode()),
            0
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_sigaltstack,
                [ALT_STACK, OLD_ALT_STACK, 0, 0, 0, 0],
            ),
            0
        );
        let previous = GuestStack::decode(
            read_guest_bytes::<24>(&ProviderMemory(&memory), OLD_ALT_STACK).unwrap(),
        );
        assert_eq!(previous.flags, libc::SS_DISABLE);
        let disabled = GuestStack {
            sp: u64::MAX,
            flags: libc::SS_DISABLE,
            size: u64::MAX,
        };
        assert_eq!(
            write_bytes(&mut ProviderMemory(&memory), ALT_STACK, &disabled.encode()),
            0
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_sigaltstack,
                [ALT_STACK, u64::MAX, 0, 0, 0, 0],
            ),
            negative_errno(libc::EFAULT)
        );
        assert!(
            state.thread_signals.lock().altstack.is_none(),
            "disabled altstack remains applied if copying the old stack fails"
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_sigaltstack,
                [0, OLD_ALT_STACK, 0, 0, 0, 0],
            ),
            0
        );
        let disabled_query = GuestStack::decode(
            read_guest_bytes::<24>(&ProviderMemory(&memory), OLD_ALT_STACK).unwrap(),
        );
        assert_eq!(disabled_query.sp, 0);
        assert_eq!(disabled_query.flags, libc::SS_DISABLE);
        assert_eq!(disabled_query.size, 0);
        let child = state.try_clone_for_fork(2).unwrap();
        assert_eq!(
            test_signal_action(&child, libc::SIGUSR1),
            Some(expected_action)
        );
        assert_eq!(
            child.thread_signals.lock().blocked,
            state.thread_signals.lock().blocked
        );
        assert_eq!(
            child.thread_signals.lock().altstack,
            state.thread_signals.lock().altstack
        );
    }

    #[test]
    fn exec_closes_cloexec_descriptors_and_resets_caught_signals() {
        let root = TestDir::new();
        let path = root.0.join("descriptor");
        std::fs::write(&path, b"payload").unwrap();
        let mut previous = test_state(&root.0);
        previous
            .files
            .insert(3, std::fs::File::open(&path).unwrap());
        previous
            .files
            .insert(4, std::fs::File::open(&path).unwrap());
        previous.cloexec_fds.extend([libc::STDIN_FILENO, 4]);
        previous.thread_signals.lock().altstack = Some(GuestStack {
            sp: 1,
            flags: 0,
            size: 16,
        });
        previous.pgid = 55;
        let mut ignored = [0x7f; KERNEL_SIGACTION_SIZE];
        ignored[..std::mem::size_of::<usize>()].copy_from_slice(&libc::SIG_IGN.to_ne_bytes());
        let mut canonical_ignored = [0; KERNEL_SIGACTION_SIZE];
        canonical_ignored[..std::mem::size_of::<usize>()]
            .copy_from_slice(&libc::SIG_IGN.to_ne_bytes());
        let mut caught = [0; KERNEL_SIGACTION_SIZE];
        caught[..std::mem::size_of::<usize>()].copy_from_slice(&2usize.to_ne_bytes());
        test_install_signal_action(&previous, libc::SIGUSR1, ignored);
        test_install_signal_action(&previous, libc::SIGUSR2, caught);
        let mut replacement = test_state(&root.0);
        replacement.inherit_process_state(previous);
        assert!(replacement.files.contains_key(&3));
        assert!(!replacement.files.contains_key(&4));
        assert!(replacement.stdin.is_none());
        assert!(
            replacement
                .closed_standard_fds
                .contains(&libc::STDIN_FILENO)
        );
        assert!(replacement.cloexec_fds.is_empty());
        assert_eq!(
            test_signal_action(&replacement, libc::SIGUSR1),
            Some(canonical_ignored)
        );
        assert_eq!(test_signal_action(&replacement, libc::SIGUSR2), None);
        assert!(replacement.thread_signals.lock().altstack.is_none());
        assert_eq!(replacement.pgid, 55, "exec preserves the process group");
        assert_eq!(
            replacement
                .task_lifecycle
                .lock()
                .unwrap()
                .get(replacement.tid)
                .unwrap()
                .pgid,
            55,
        );
    }

    #[test]
    fn altstack_uses_open_lower_and_closed_upper_boundaries() {
        const REQUEST: u64 = 0x100;
        const OLD: u64 = 0x180;
        let root = TestDir::new();
        let mut state = test_state(&root.0);
        let mut memory = GuestMemory::new(0, PAGE_SIZE as usize).unwrap();
        let stack = GuestStack {
            sp: 0x8000,
            flags: 0,
            size: libc::MINSIGSTKSZ as u64,
        };
        let top = stack.sp + stack.size;
        state.thread_signals.lock().altstack = Some(stack);

        for (current, on_stack) in [(stack.sp, false), (stack.sp + 1, true), (top, true)] {
            assert_eq!(
                sigaltstack(
                    &mut memory,
                    &mut state,
                    Some(current),
                    &[0, OLD, 0, 0, 0, 0]
                ),
                0,
            );
            let queried =
                GuestStack::decode(read_guest_bytes::<24>(&ProviderMemory(&memory), OLD).unwrap());
            assert_eq!(
                queried.flags & libc::SS_ONSTACK != 0,
                on_stack,
                "current rsp={current:#x}",
            );
        }

        let replacement = GuestStack {
            sp: 0x20_000,
            flags: 0,
            size: libc::MINSIGSTKSZ as u64,
        };
        memory.write(REQUEST, &replacement.encode()).unwrap();
        for current in [stack.sp + 1, top] {
            assert_eq!(
                sigaltstack(
                    &mut memory,
                    &mut state,
                    Some(current),
                    &[REQUEST, 0, 0, 0, 0, 0],
                ),
                negative_errno(libc::EPERM),
            );
            assert_eq!(state.thread_signals.lock().altstack, Some(stack));
        }
        assert_eq!(
            sigaltstack(
                &mut memory,
                &mut state,
                Some(stack.sp),
                &[REQUEST, 0, 0, 0, 0, 0],
            ),
            0,
            "the lower bound is not part of a downward-growing altstack",
        );
        assert_eq!(state.thread_signals.lock().altstack, Some(replacement));
    }

    #[test]
    fn sigaltstack_accepts_and_preserves_an_overflowing_descriptor() {
        const REQUEST: u64 = 0x100;
        const OLD: u64 = 0x180;
        let root = TestDir::new();
        let mut state = test_state(&root.0);
        let mut memory = GuestMemory::new(0, PAGE_SIZE as usize).unwrap();
        let overflowing = GuestStack {
            sp: u64::MAX - 8,
            flags: 0,
            size: libc::MINSIGSTKSZ as u64,
        };
        memory.write(REQUEST, &overflowing.encode()).unwrap();
        assert_eq!(
            sigaltstack(
                &mut memory,
                &mut state,
                Some(0x4000),
                &[REQUEST, OLD, 0, 0, 0, 0],
            ),
            0,
        );
        assert_eq!(state.thread_signals.lock().altstack, Some(overflowing));
        assert_eq!(
            GuestStack::decode(read_guest_bytes::<24>(&ProviderMemory(&memory), OLD).unwrap()),
            GuestStack {
                sp: 0,
                flags: libc::SS_DISABLE,
                size: 0,
            },
        );
        assert_eq!(
            sigaltstack(
                &mut memory,
                &mut state,
                Some(u64::MAX),
                &[0, OLD, 0, 0, 0, 0],
            ),
            0,
        );
        let observed =
            GuestStack::decode(read_guest_bytes::<24>(&ProviderMemory(&memory), OLD).unwrap());
        assert_eq!(observed.sp, overflowing.sp);
        assert_eq!(observed.size, overflowing.size);
        assert_eq!(observed.flags, libc::SS_ONSTACK);

        let executor = ElfExecutor::new(state, false);
        let action = KernelSigaction {
            flags: libc::SA_ONSTACK as u64,
            ..Default::default()
        };
        assert_eq!(
            executor.signal_stack_top(action, 0x4000),
            Ok((
                overflowing.sp.wrapping_add(overflowing.size),
                Some(overflowing.sp),
                false,
                false,
            )),
        );
    }

    #[test]
    fn sa_onstack_placement_obeys_boundaries_and_autodisarm() {
        let root = TestDir::new();
        let executor = ElfExecutor::new(test_state(&root.0), false);
        let stack = GuestStack {
            sp: 0x8000,
            flags: 0,
            size: libc::MINSIGSTKSZ as u64,
        };
        let top = stack.sp + stack.size;
        let action = KernelSigaction {
            flags: libc::SA_ONSTACK as u64,
            ..Default::default()
        };
        executor.state.thread_signals.lock().altstack = Some(stack);
        for current in [stack.sp + 1, top] {
            assert_eq!(
                executor.signal_stack_top(action, current),
                Ok((current, Some(stack.sp), true, false)),
                "an rsp in (base, top] is nested",
            );
        }
        assert_eq!(
            executor.signal_stack_top(action, stack.sp),
            Ok((top, Some(stack.sp), false, false)),
            "an rsp at base is off-stack and starts a fresh altstack frame",
        );

        let autodisarm = GuestStack {
            flags: SS_AUTODISARM,
            ..stack
        };
        executor.state.thread_signals.lock().altstack = Some(autodisarm);
        assert_eq!(
            executor.signal_stack_top(action, stack.sp + 1),
            Ok((top, Some(stack.sp), false, true)),
            "an armed SS_AUTODISARM stack is treated as off-stack",
        );
        assert_eq!(executor.signal_altstack(stack.sp + 1).flags, SS_AUTODISARM,);
    }

    #[test]
    fn rt_sigreturn_ignores_invalid_altstack_restore_but_restores_the_mask() {
        let root = TestDir::new();
        let mut executor = ElfExecutor::new(test_state(&root.0), false);
        let original_stack = GuestStack {
            sp: 0x4000,
            flags: 0,
            size: libc::MINSIGSTKSZ as u64,
        };
        executor.state.thread_signals.lock().altstack = Some(original_stack);
        executor
            .state
            .thread_signals
            .lock()
            .blocked
            .insert(libc::SIGUSR1);
        let mut restored_mask = KernelSigset::default();
        restored_mask.insert(libc::SIGUSR2);
        for invalid_stack in [
            GuestStack {
                sp: 0x8000,
                flags: 0x1234,
                size: libc::MINSIGSTKSZ as u64,
            },
            GuestStack {
                sp: 0x8000,
                flags: 0,
                size: libc::MINSIGSTKSZ as u64 - 1,
            },
        ] {
            executor.restore_signal_thread_state(
                restored_mask,
                invalid_stack,
                original_stack.sp + 1,
            );
            assert_eq!(
                executor.state.thread_signals.lock().altstack,
                Some(original_stack)
            );
        }

        let overflowing_stack = GuestStack {
            sp: u64::MAX - 8,
            flags: 0,
            size: libc::MINSIGSTKSZ as u64,
        };
        executor.restore_signal_thread_state(restored_mask, overflowing_stack, original_stack.sp);
        assert_eq!(
            executor.state.thread_signals.lock().altstack,
            Some(overflowing_stack),
            "Linux stores the descriptor without eagerly adding sp and size",
        );
        executor.state.thread_signals.lock().altstack = Some(original_stack);

        let distinct_valid_stack = GuestStack {
            sp: 0x20_000,
            flags: 0,
            size: libc::MINSIGSTKSZ as u64,
        };
        executor.restore_signal_thread_state(
            restored_mask,
            distinct_valid_stack,
            original_stack.sp + 1,
        );
        assert_eq!(
            executor.state.thread_signals.lock().altstack,
            Some(original_stack),
            "rt_sigreturn ignores EPERM from replacing an active altstack",
        );

        assert!(
            !executor
                .state
                .thread_signals
                .lock()
                .blocked
                .contains(libc::SIGUSR1)
        );
        assert!(
            executor
                .state
                .thread_signals
                .lock()
                .blocked
                .contains(libc::SIGUSR2)
        );
    }

