    fn nonleader_exec_refusal_record() -> reverie::UnsupportedRefusal {
        reverie::UnsupportedRefusal::new(
            reverie::UnsupportedOperation::NonLeaderExec,
            reverie::Errno::ENOSYS,
            NONLEADER_EXEC_REFUSAL,
        )
    }

    #[test]
    fn nonleader_exec_refusal_types_every_worker_enosys_and_nothing_else() {
        let enosys = negative_errno(libc::ENOSYS);
        assert_eq!(
            nonleader_exec_refusal(enosys, 8, 7),
            Some(nonleader_exec_refusal_record())
        );
        assert_eq!(nonleader_exec_refusal(enosys, 7, 7), None);
        for result in [
            0,
            negative_errno(libc::EFAULT),
            negative_errno(libc::ENOENT),
            negative_errno(libc::EACCES),
            negative_errno(libc::ENOEXEC),
            negative_errno(libc::EBUSY),
            negative_errno(libc::ENOTSUP),
            negative_errno(libc::ENOMEM),
        ] {
            assert_eq!(nonleader_exec_refusal(result, 8, 7), None, "{result}");
            assert_eq!(nonleader_exec_refusal(result, 7, 7), None, "{result}");
        }
    }

    /// A host syscall that the exec preflight makes can itself fail with
    /// ENOSYS (here the host `faccessat2` permission check, refused by a
    /// seccomp filter as an old kernel or a sandbox would). A worker's exec
    /// that fails that way is still this backend's refusal, never an errno
    /// Linux would return, so it carries the typed refusal. A leader's does
    /// not.
    #[test]
    fn worker_exec_host_enosys_during_preflight_is_the_typed_refusal() {
        const CHILD_ENV: &str = "REVERIE_KVM_NONLEADER_EXEC_HOST_ENOSYS_CHILD";
        const PATH_ADDRESS: u64 = 0x200;
        const ARGV_ADDRESS: u64 = 0x400;
        const ENVP_ADDRESS: u64 = 0x500;

        if std::env::var_os(CHILD_ENV).is_some() {
            let root = TestDir::new();
            let mut state = test_state(&root.0);
            state.executable_file = Some(Arc::new(
                std::fs::File::open(std::env::current_exe().unwrap()).unwrap(),
            ));
            let mut leader = ElfExecutor::new(state, false);
            let mut worker = leader.thread_child(7).unwrap();
            assert_ne!(worker.state.pid, worker.state.tid);
            let mut memory = GuestMemory::new(0, 16 * 1024 * 1024).unwrap();
            memory.write(PATH_ADDRESS, b"/proc/self/exe\0").unwrap();
            memory
                .write(ARGV_ADDRESS, &PATH_ADDRESS.to_le_bytes())
                .unwrap();
            memory
                .write(ARGV_ADDRESS + 8, &0_u64.to_le_bytes())
                .unwrap();
            memory.write(ENVP_ADDRESS, &0_u64.to_le_bytes()).unwrap();
            let request = SyscallRequest::new(
                libc::SYS_execve as u64,
                [PATH_ADDRESS, ARGV_ADDRESS, ENVP_ADDRESS, 0, 0, 0],
            );

            // Every faccessat2 on this thread now fails with ENOSYS.
            let filter = [
                // SAFETY: BPF_STMT and BPF_JUMP only build instructions.
                unsafe {
                    libc::BPF_STMT(
                        (libc::BPF_LD | libc::BPF_W | libc::BPF_ABS) as u16,
                        std::mem::offset_of!(libc::seccomp_data, nr) as u32,
                    )
                },
                unsafe {
                    libc::BPF_JUMP(
                        (libc::BPF_JMP | libc::BPF_JEQ | libc::BPF_K) as u16,
                        libc::SYS_faccessat2 as u32,
                        0,
                        1,
                    )
                },
                unsafe {
                    libc::BPF_STMT(
                        (libc::BPF_RET | libc::BPF_K) as u16,
                        libc::SECCOMP_RET_ERRNO | libc::ENOSYS as u32,
                    )
                },
                unsafe {
                    libc::BPF_STMT(
                        (libc::BPF_RET | libc::BPF_K) as u16,
                        libc::SECCOMP_RET_ALLOW,
                    )
                },
            ];
            let program = libc::sock_fprog {
                len: filter.len() as u16,
                filter: filter.as_ptr().cast_mut(),
            };
            // SAFETY: plain prctl and seccomp calls; `program` outlives them.
            unsafe {
                assert_eq!(libc::prctl(libc::PR_SET_NO_NEW_PRIVS, 1, 0, 0, 0), 0);
                assert_eq!(
                    libc::syscall(
                        libc::SYS_seccomp,
                        libc::SECCOMP_SET_MODE_FILTER,
                        0,
                        &program as *const libc::sock_fprog,
                    ),
                    0
                );
            }
            // SAFETY: faccessat2 with a NUL-terminated path; the filter refuses it.
            let probe =
                unsafe { libc::syscall(libc::SYS_faccessat2, libc::AT_FDCWD, c"/".as_ptr(), 0, 0) };
            assert_eq!(
                (probe, std::io::Error::last_os_error().raw_os_error()),
                (-1, Some(libc::ENOSYS))
            );

            assert_eq!(
                worker.execute_process_action(&request, &memory),
                Some(negative_errno(libc::ENOSYS))
            );
            assert_eq!(
                worker.take_unsupported_refusal(),
                Some(nonleader_exec_refusal_record())
            );
            assert!(worker.take_process_action().is_none());

            assert_eq!(
                leader.execute_process_action(&request, &memory),
                Some(negative_errno(libc::ENOSYS))
            );
            assert_eq!(leader.take_unsupported_refusal(), None);
            assert!(leader.take_process_action().is_none());
            return;
        }

        let output = std::process::Command::new(std::env::current_exe().unwrap())
            .arg("executor::tests::worker_exec_host_enosys_during_preflight_is_the_typed_refusal")
            .arg("--exact")
            .env(CHILD_ENV, "1")
            .output()
            .expect("failed to run the isolated host-ENOSYS exec check");
        let stdout = String::from_utf8_lossy(&output.stdout);
        assert!(
            output.status.success() && stdout.contains("1 passed"),
            "isolated host-ENOSYS exec check failed with {}\nstdout:\n{stdout}\nstderr:\n{}",
            output.status,
            String::from_utf8_lossy(&output.stderr)
        );
    }

    #[test]
    fn worker_exec_preserves_preflight_errors_without_publishing_action() {
        const SENTINEL_ADDRESS: u64 = 0x30_0000;
        const SENTINEL: [u8; 8] = *b"still-ok";
        const PATH_ADDRESS: u64 = 0x200;
        const ARGV_ADDRESS: u64 = 0x400;
        const ENVP_ADDRESS: u64 = 0x500;

        let root = TestDir::new();
        let valid_path = root.0.join("valid");
        let malformed_path = root.0.join("malformed");
        let missing_path = root.0.join("missing");
        let mut image = vec![0; 0x1002];
        image[..7].copy_from_slice(b"\x7fELF\x02\x01\x01");
        for (offset, value) in [(16, 2_u16), (18, 62), (52, 64), (54, 56), (56, 1)] {
            image[offset..offset + 2].copy_from_slice(&value.to_le_bytes());
        }
        for (offset, value) in [(20, 1_u32), (64, 1), (68, 5)] {
            image[offset..offset + 4].copy_from_slice(&value.to_le_bytes());
        }
        for (offset, value) in [
            (24, 0x20_0000_u64),
            (32, 64),
            (72, 0x1000),
            (80, 0x20_0000),
            (88, 0x20_0000),
            (96, 2),
            (104, 0x1000),
            (112, 0x1000),
        ] {
            image[offset..offset + 8].copy_from_slice(&value.to_le_bytes());
        }
        image[0x1000..].copy_from_slice(&[0x0f, 0x0b]);
        std::fs::write(&valid_path, &image).unwrap();
        std::fs::write(&malformed_path, b"not an ELF image").unwrap();
        assert!(!missing_path.exists());
        let mut memory = GuestMemory::new(0, 16 * 1024 * 1024).unwrap();
        memory.write(SENTINEL_ADDRESS, &SENTINEL).unwrap();
        memory
            .write(ARGV_ADDRESS, &PATH_ADDRESS.to_le_bytes())
            .unwrap();
        memory
            .write(ARGV_ADDRESS + 8, &0_u64.to_le_bytes())
            .unwrap();
        memory.write(ENVP_ADDRESS, &0_u64.to_le_bytes()).unwrap();
        let mut leader = ElfExecutor::new(test_state(&root.0), false);
        let mut worker = leader.thread_child(7).unwrap();
        assert_ne!(worker.state.pid, worker.state.tid);
        let identity = (worker.state.pid, worker.state.tid);
        let invalid = memory.guest_end() + PAGE_SIZE;
        let mut results = Vec::new();
        let mut expected_results = Vec::new();
        for number in [libc::SYS_execve, libc::SYS_execveat] {
            for (case, path, invalid_argument, errno) in [
                ("path", &valid_path, Some(0), libc::EFAULT),
                ("argv", &valid_path, Some(1), libc::EFAULT),
                ("envp", &valid_path, Some(2), libc::EFAULT),
                ("missing", &missing_path, None, libc::ENOENT),
                ("malformed", &malformed_path, None, libc::ENOEXEC),
                ("valid", &valid_path, None, libc::ENOSYS),
            ] {
                let path = CString::new(path.as_os_str().as_bytes()).unwrap();
                memory
                    .write(PATH_ADDRESS, path.as_bytes_with_nul())
                    .unwrap();
                let mut pointers = [PATH_ADDRESS, ARGV_ADDRESS, ENVP_ADDRESS];
                if let Some(index) = invalid_argument {
                    pointers[index] = invalid;
                }
                let [path, argv, envp] = pointers;
                let args = if number == libc::SYS_execve {
                    [path, argv, envp, 0, 0, 0]
                } else {
                    [libc::AT_FDCWD as u64, path, argv, envp, 0, 0]
                };
                let request = SyscallRequest::new(number as u64, args);
                if case == "valid" {
                    assert_eq!(leader.execute_process_action(&request, &memory), Some(0));
                    assert_eq!(leader.take_unsupported_refusal(), None);
                    assert!(matches!(
                        leader.take_process_action(),
                        Some(ProcessAction::Exec { .. })
                    ));
                }
                let result = worker.execute_process_action(&request, &memory);
                eprintln!("syscall={number} case={case} result={result:?} expected=-{errno}");
                results.push(result);
                expected_results.push(Some(negative_errno(errno)));
                // Only the refusal itself is typed; an ordinary preflight
                // error is the guest's errno.
                assert_eq!(
                    worker.take_unsupported_refusal(),
                    (errno == libc::ENOSYS).then(nonleader_exec_refusal_record),
                    "syscall={number} case={case}"
                );
                assert_eq!(worker.take_unsupported_refusal(), None);
                assert!(
                    worker.take_process_action().is_none(),
                    "worker exec published a process-image replacement"
                );
                let mut observed = [0; SENTINEL.len()];
                memory.read(SENTINEL_ADDRESS, &mut observed).unwrap();
                assert_eq!(observed, SENTINEL);
                assert_eq!((worker.state.pid, worker.state.tid), identity);
            }
        }
        assert_eq!(results, expected_results);
    }

    #[test]
    fn process_clone_accepts_legacy_tid_flags_without_prevalidating_pointers() {
        const CHILD_TID: u64 = 0x100;
        const PARENT_TID: u64 = 0x108;

        let root = TestDir::new();
        let memory = GuestMemory::new(0, PAGE_SIZE as usize).unwrap();
        let mut executor = ElfExecutor::new(test_state(&root.0), false);
        let flags = libc::SIGCHLD as u64
            | libc::CLONE_PARENT_SETTID as u64
            | libc::CLONE_CHILD_SETTID as u64
            | libc::CLONE_CHILD_CLEARTID as u64;
        let request = SyscallRequest::new(
            libc::SYS_clone as u64,
            [flags, 0, PARENT_TID, CHILD_TID, 0, 0],
        );
        assert_eq!(executor.execute_process_action(&request, &memory), Some(2));
        match executor.take_process_action() {
            Some(ProcessAction::Fork {
                child_pid,
                child_stack,
                parent_tid,
                child_tid,
                clear_child_tid,
                clear_sighand,
                share_address_space,
            }) => {
                assert_eq!(child_pid, 2);
                assert_eq!(child_stack, None);
                assert!(!clear_sighand);
                assert!(!share_address_space);
                assert_eq!(parent_tid, Some(PARENT_TID));
                assert_eq!(child_tid, Some(CHILD_TID));
                assert_eq!(clear_child_tid, Some(CHILD_TID));
            }
            _ => panic!("clone did not produce a fork action"),
        }

        let mut executor = ElfExecutor::new(test_state(&root.0), false);
        let bad_pointer = memory.guest_end() - 1;
        let request = SyscallRequest::new(
            libc::SYS_clone as u64,
            [
                libc::SIGCHLD as u64 | libc::CLONE_CHILD_SETTID as u64,
                0,
                0,
                bad_pointer,
                0,
                0,
            ],
        );
        assert_eq!(executor.execute_process_action(&request, &memory), Some(2));
        match executor.take_process_action() {
            Some(ProcessAction::Fork {
                child_pid,
                child_tid,
                ..
            }) => {
                assert_eq!(child_pid, 2);
                assert_eq!(child_tid, Some(bad_pointer));
            }
            _ => panic!("clone with an invalid TID pointer did not create a child"),
        }

        let mut executor = ElfExecutor::new(test_state(&root.0), false);
        let shared_flags = flags | libc::CLONE_VM as u64 | libc::CLONE_VFORK as u64;
        let request = SyscallRequest::new(
            libc::SYS_clone as u64,
            [shared_flags, 0, PARENT_TID, CHILD_TID, 0, 0],
        );
        assert_eq!(
            executor.execute_process_action(&request, &memory),
            Some(negative_errno(libc::ENOTSUP))
        );
        assert!(executor.take_process_action().is_none());
    }

    #[test]
    fn clone3_accepts_glibc_pthread_profile_with_tls_and_tid_addresses() {
        const CLONE3_ARGS: u64 = 0x200;
        const CHILD_TID_ADDRESS: u64 = 0x300;
        const PARENT_TID_ADDRESS: u64 = 0x308;
        const CHILD_STACK: u64 = 0x4000;
        const CHILD_STACK_SIZE: u64 = 0x9000;
        const TLS: u64 = 0x1_234_000;

        let root = TestDir::new();
        let mut memory = GuestMemory::new(0, PAGE_SIZE as usize).unwrap();
        let mut clone3 = [0_u8; 88];
        let flags = THREAD_CLONE_REQUIRED_FLAGS
            | libc::CLONE_SYSVSEM as u64
            | libc::CLONE_SETTLS as u64
            | libc::CLONE_PARENT_SETTID as u64
            | libc::CLONE_CHILD_CLEARTID as u64;
        clone3[0..8].copy_from_slice(&flags.to_le_bytes());
        // glibc leaves clone_args.pidfd aliased to the thread descriptor even
        // though CLONE_PIDFD is absent; Linux ignores the slot in that case.
        clone3[8..16].copy_from_slice(&CHILD_TID_ADDRESS.to_le_bytes());
        clone3[16..24].copy_from_slice(&CHILD_TID_ADDRESS.to_le_bytes());
        clone3[24..32].copy_from_slice(&PARENT_TID_ADDRESS.to_le_bytes());
        clone3[40..48].copy_from_slice(&CHILD_STACK.to_le_bytes());
        clone3[48..56].copy_from_slice(&CHILD_STACK_SIZE.to_le_bytes());
        clone3[56..64].copy_from_slice(&TLS.to_le_bytes());
        memory.write(CLONE3_ARGS, &clone3).unwrap();
        let mut executor = ElfExecutor::new(test_state(&root.0), false);
        let request = SyscallRequest::new(
            libc::SYS_clone3 as u64,
            [CLONE3_ARGS, clone3.len() as u64, 0, 0, 0, 0],
        );

        assert!(is_thread_clone_request(&request, &memory));
        let legacy_thread = SyscallRequest::new(
            libc::SYS_clone as u64,
            [THREAD_CLONE_REQUIRED_FLAGS, CHILD_STACK, 0, 0, TLS, 0],
        );
        assert!(is_thread_clone_request(&legacy_thread, &memory));
        let process_clone = SyscallRequest::new(
            libc::SYS_clone as u64,
            [libc::SIGCHLD as u64, 0, 0, 0, 0, 0],
        );
        assert!(!is_thread_clone_request(&process_clone, &memory));

        assert_eq!(executor.execute_process_action(&request, &memory), Some(2));
        match executor.take_process_action() {
            Some(ProcessAction::Thread {
                child_tid,
                child_stack,
                parent_tid,
                child_tid_address,
                clear_child_tid,
                tls,
            }) => {
                assert_eq!(child_tid, 2);
                assert_eq!(child_stack, CHILD_STACK + CHILD_STACK_SIZE);
                assert_eq!(parent_tid, Some(PARENT_TID_ADDRESS));
                assert_eq!(child_tid_address, None);
                assert_eq!(clear_child_tid, Some(CHILD_TID_ADDRESS));
                assert_eq!(tls, Some(TLS));
            }
            _ => panic!("glibc pthread clone3 did not produce a thread action"),
        }
    }

    #[test]
    fn clone3_validates_nonzero_extensions_and_paired_stack_fields() {
        const CLONE3_ARGS: u64 = 0x200;

        let root = TestDir::new();
        let mut memory = GuestMemory::new(0, PAGE_SIZE as usize).unwrap();
        let mut clone3 = [0_u8; 96];
        clone3[95] = 1;
        memory.write(CLONE3_ARGS, &clone3).unwrap();
        let mut executor = ElfExecutor::new(test_state(&root.0), false);
        let request = SyscallRequest::new(
            libc::SYS_clone3 as u64,
            [CLONE3_ARGS, clone3.len() as u64, 0, 0, 0, 0],
        );
        assert_eq!(
            executor.execute_process_action(&request, &memory),
            Some(negative_errno(libc::E2BIG))
        );

        clone3[95] = 0;
        clone3[40..48].copy_from_slice(&0x1000_u64.to_le_bytes());
        memory.write(CLONE3_ARGS, &clone3).unwrap();
        let request = SyscallRequest::new(libc::SYS_clone3 as u64, [CLONE3_ARGS, 88, 0, 0, 0, 0]);
        assert_eq!(
            executor.execute_process_action(&request, &memory),
            Some(negative_errno(libc::EINVAL))
        );
        assert!(executor.take_process_action().is_none());
    }

    #[test]
    fn clone3_tid_flags_remain_explicitly_unsupported() {
        const CLONE3_ARGS: u64 = 0x200;

        let root = TestDir::new();
        let mut memory = GuestMemory::new(0, PAGE_SIZE as usize).unwrap();
        let mut clone3 = [0_u8; 64];
        clone3[0..8].copy_from_slice(&(libc::CLONE_CHILD_CLEARTID as u64).to_le_bytes());
        clone3[32..40].copy_from_slice(&(libc::SIGCHLD as u64).to_le_bytes());
        memory.write(CLONE3_ARGS, &clone3).unwrap();
        let mut executor = ElfExecutor::new(test_state(&root.0), false);
        let request = SyscallRequest::new(
            libc::SYS_clone3 as u64,
            [CLONE3_ARGS, clone3.len() as u64, 0, 0, 0, 0],
        );

        assert_eq!(
            executor.execute_process_action(&request, &memory),
            Some(negative_errno(libc::ENOTSUP))
        );
        assert!(executor.take_process_action().is_none());

        clone3[16..24].copy_from_slice(&1_u64.to_le_bytes());
        clone3[32..40].copy_from_slice(&255_u64.to_le_bytes());
        memory.write(CLONE3_ARGS, &clone3).unwrap();
        let request = SyscallRequest::new(
            libc::SYS_clone3 as u64,
            [CLONE3_ARGS, clone3.len() as u64, 0, 0, 0, 0],
        );
        assert_eq!(
            executor.execute_process_action(&request, &memory),
            Some(negative_errno(libc::EINVAL)),
            "malformed exit_signal takes precedence over unsupported TID flags"
        );
        assert!(executor.take_process_action().is_none());

        clone3[32..40].copy_from_slice(&(libc::SIGCHLD as u64).to_le_bytes());
        memory.write(CLONE3_ARGS, &clone3).unwrap();
        let request = SyscallRequest::new(
            libc::SYS_clone3 as u64,
            [CLONE3_ARGS, clone3.len() as u64, 0, 0, 0, 0],
        );
        assert_eq!(
            executor.execute_process_action(&request, &memory),
            Some(negative_errno(libc::ENOTSUP)),
            "a TID field remains explicitly unsupported after validation"
        );
        assert!(executor.take_process_action().is_none());
    }

    #[test]
    fn clone3_posix_spawn_vfork_with_clear_sighand_is_accepted() {
        // glibc >= 2.36 `posix_spawn` (used by `make`/`gcc` to launch recipe and
        // subprocess jobs) issues exactly this clone3: CLONE_VM|CLONE_VFORK with
        // CLONE_CLEAR_SIGHAND, an explicit child stack, and SIGCHLD as the exit
        // signal. Older glibc omitted CLONE_CLEAR_SIGHAND, so the executor must
        // accept the flag and reset caught child handlers before it runs.
        const CLONE3_ARGS: u64 = 0x200;
        const CHILD_STACK: u64 = 0x4000;
        const CHILD_STACK_SIZE: u64 = 0x9000;

        let root = TestDir::new();
        let mut memory = GuestMemory::new(0, PAGE_SIZE as usize).unwrap();
        let mut clone3 = [0_u8; 88];
        let flags = libc::CLONE_VM as u64 | libc::CLONE_VFORK as u64 | CLONE_CLEAR_SIGHAND;
        clone3[0..8].copy_from_slice(&flags.to_le_bytes());
        clone3[32..40].copy_from_slice(&(libc::SIGCHLD as u64).to_le_bytes());
        clone3[40..48].copy_from_slice(&CHILD_STACK.to_le_bytes());
        clone3[48..56].copy_from_slice(&CHILD_STACK_SIZE.to_le_bytes());
        memory.write(CLONE3_ARGS, &clone3).unwrap();

        let mut executor = ElfExecutor::new(test_state(&root.0), false);
        let mut ignored = [0; KERNEL_SIGACTION_SIZE];
        ignored[..std::mem::size_of::<usize>()].copy_from_slice(&libc::SIG_IGN.to_ne_bytes());
        let mut caught = [0; KERNEL_SIGACTION_SIZE];
        caught[..std::mem::size_of::<usize>()].copy_from_slice(&2usize.to_ne_bytes());
        test_install_signal_action(&executor.state, libc::SIGUSR1, ignored);
        test_install_signal_action(&executor.state, libc::SIGUSR2, caught);
        let request = SyscallRequest::new(
            libc::SYS_clone3 as u64,
            [CLONE3_ARGS, clone3.len() as u64, 0, 0, 0, 0],
        );
        assert!(!is_thread_clone_request(&request, &memory));
        assert_eq!(executor.execute_process_action(&request, &memory), Some(2));
        match executor.take_process_action() {
            Some(ProcessAction::Fork {
                child_pid,
                child_stack,
                parent_tid,
                child_tid,
                clear_child_tid,
                clear_sighand,
                share_address_space,
            }) => {
                assert_eq!(child_pid, 2);
                assert_eq!(child_stack, Some(CHILD_STACK + CHILD_STACK_SIZE));
                assert!(clear_sighand);
                assert!(share_address_space);
                assert_eq!(parent_tid, None);
                assert_eq!(child_tid, None);
                assert_eq!(clear_child_tid, None);
                let child = executor
                    .fork_child(child_pid, clear_sighand, share_address_space)
                    .unwrap();
                assert_eq!(
                    test_signal_action(&child.state, libc::SIGUSR1),
                    Some(ignored)
                );
                assert_eq!(test_signal_action(&child.state, libc::SIGUSR2), None);
                assert_eq!(
                    test_signal_action(&executor.state, libc::SIGUSR1),
                    Some(ignored)
                );
                assert_eq!(
                    test_signal_action(&executor.state, libc::SIGUSR2),
                    Some(caught)
                );
            }
            _ => panic!("clone3 with CLONE_CLEAR_SIGHAND did not create a fork action"),
        }
    }

    #[test]
    fn set_tid_address_tracks_current_pid_and_clear_pointer() {
        const CLEAR_TID: u64 = 0x100;

        let root = TestDir::new();
        let memory = GuestMemory::new(0, PAGE_SIZE as usize).unwrap();
        let mut executor = ElfExecutor::new(test_state(&root.0), false);
        let request =
            SyscallRequest::new(libc::SYS_set_tid_address as u64, [CLEAR_TID, 0, 0, 0, 0, 0]);
        assert_eq!(executor.execute_process_action(&request, &memory), Some(1));
        assert_eq!(executor.take_clear_child_tid(), Some(CLEAR_TID));

        let request = SyscallRequest::new(libc::SYS_set_tid_address as u64, [0; 6]);
        assert_eq!(executor.execute_process_action(&request, &memory), Some(1));
        assert_eq!(executor.take_clear_child_tid(), None);

        let request =
            SyscallRequest::new(libc::SYS_set_tid_address as u64, [CLEAR_TID, 0, 0, 0, 0, 0]);
        assert_eq!(executor.execute_process_action(&request, &memory), Some(1));
        executor.replace_after_exec(test_state(&root.0));
        assert_eq!(executor.take_clear_child_tid(), None);
    }

    #[test]
    fn post_exec_mask_preflight_preserves_both_pending_domains_across_recursive_exec() {
        const EMPTY_MASK: u64 = 0x100;
        const OLD_MASK: u64 = 0x200;
        let root = TestDir::new();

        for (label, process_directed, signal) in [
            ("thread", false, libc::SIGUSR1),
            ("process", true, libc::SIGUSR2),
        ] {
            let mut executor = ElfExecutor::new(test_state(&root.0), false);
            let pid = executor.state.pid;
            let tid = executor.state.tid;
            test_block_signal(&mut executor.state, signal);
            let (number, arguments) = if process_directed {
                (libc::SYS_kill, [pid as u64, signal as u64, 0, 0, 0, 0])
            } else {
                (libc::SYS_tkill, [tid as u64, signal as u64, 0, 0, 0, 0])
            };
            assert_eq!(
                result_of(kill_signal(&mut executor.state, number as u64, &arguments,)),
                0,
            );

            let mut memory = GuestMemory::new(0, PAGE_SIZE as usize).unwrap();
            memory.write(EMPTY_MASK, &[0; KERNEL_SIGSET_SIZE]).unwrap();
            let old_sentinel = [0xa5; KERNEL_SIGSET_SIZE];
            memory.write(OLD_MASK, &old_sentinel).unwrap();
            let request = SyscallRequest::new(
                libc::SYS_rt_sigprocmask as u64,
                [
                    libc::SIG_SETMASK as u64,
                    EMPTY_MASK,
                    OLD_MASK,
                    KERNEL_SIGSET_SIZE as u64,
                    0,
                    0,
                ],
            );

            for exec_depth in 1..=2 {
                executor.replace_after_exec(test_state(&root.0));
                assert!(
                    executor
                        .state
                        .thread_signals
                        .lock()
                        .blocked
                        .contains(signal),
                    "{label} mask was not preserved across exec {exec_depth}",
                );
                assert_eq!(
                    executor.lifecycle_signal_mask_preflight(&request, &memory),
                    Some(negative_errno(libc::ENOSYS)),
                    "{label} pending signal became eligible after exec {exec_depth}",
                );
                assert!(
                    executor
                        .state
                        .thread_signals
                        .lock()
                        .blocked
                        .contains(signal)
                );
                let still_pending = if process_directed {
                    executor
                        .state
                        .process_signals
                        .lock()
                        .unwrap()
                        .shared_pending
                        .contains(signal)
                } else {
                    executor
                        .state
                        .thread_signals
                        .lock()
                        .pending
                        .contains(signal)
                };
                assert!(still_pending, "{label} pending signal was consumed");
                let mut observed = [0; KERNEL_SIGSET_SIZE];
                memory.read(OLD_MASK, &mut observed).unwrap();
                assert_eq!(
                    observed, old_sentinel,
                    "{label} old-mask output changed before refusal",
                );
            }
        }
    }

    #[test]
    fn memory_residency_is_deterministic() {
        const VECTOR: u64 = 4 * PAGE_SIZE;

        let root = TestDir::new();
        let mut state = test_state(&root.0);
        let mut memory = GuestMemory::new(0, (5 * PAGE_SIZE) as usize).unwrap();
        memory
            .map_user_range(PAGE_SIZE, 2 * PAGE_SIZE, false)
            .unwrap();
        memory.map_user_range(VECTOR, PAGE_SIZE, false).unwrap();
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_munlock,
                [PAGE_SIZE + 1, PAGE_SIZE - 1, 0, 0, 0, 0],
            ),
            0
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_munlock,
                [PAGE_SIZE, 0, 0, 0, 0, 0],
            ),
            0
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_munlock,
                [5 * PAGE_SIZE + 1, 0, 0, 0, 0, 0],
            ),
            negative_errno(libc::ENOMEM)
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_munlock,
                [5 * PAGE_SIZE - 1, 2, 0, 0, 0, 0],
            ),
            negative_errno(libc::ENOMEM)
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_munlock,
                [1, u64::MAX, 0, 0, 0, 0],
            ),
            0
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_munlock,
                [0, u64::MAX, 0, 0, 0, 0],
            ),
            0
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_munlock,
                [u64::MAX - 1, 4, 0, 0, 0, 0],
            ),
            negative_errno(libc::EINVAL)
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_munlock,
                [u64::MAX, 0, 0, 0, 0, 0],
            ),
            negative_errno(libc::EINVAL)
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_munlock,
                [u64::MAX - (PAGE_SIZE - 1), 1, 0, 0, 0, 0],
            ),
            negative_errno(libc::EINVAL)
        );
        assert_eq!(
            syscall_result(&mut memory, &mut state, libc::SYS_munlockall, [u64::MAX; 6],),
            0
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_mincore,
                [PAGE_SIZE, PAGE_SIZE + 1, VECTOR, 0, 0, 0],
            ),
            0
        );
        assert_eq!(
            read_guest_bytes::<2>(&ProviderMemory(&memory), VECTOR).unwrap(),
            [1, 1]
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_mincore,
                [3 * PAGE_SIZE, PAGE_SIZE, VECTOR, 0, 0, 0],
            ),
            negative_errno(libc::ENOMEM)
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_mincore,
                [PAGE_SIZE + 1, PAGE_SIZE, VECTOR, 0, 0, 0],
            ),
            negative_errno(libc::EINVAL)
        );
    }

    include!("wait4_copyout_tests.rs");
    include!("waitid_copyout_tests.rs");

    #[test]
    fn wait4_wuntraced_reaps_terminal_statuses_with_linux_int_options() {
        const STATUS: u64 = 0x100;
        const USAGE: u64 = 0x200;
        let root = TestDir::new();
        for low in [libc::WUNTRACED, libc::WUNTRACED | libc::WNOHANG] {
            for high in [0, 0xdead_beef_u64 << 32] {
                for selected in [7, u64::from(u32::MAX)] {
                    for terminal in [
                        ExitStatus::Exited(3),
                        ExitStatus::Signaled(Signal::SIGTERM, false),
                        ExitStatus::Signaled(Signal::SIGABRT, true),
                    ] {
                        for outputs in [false, true] {
                            let mut state = test_state(&root.0);
                            state.children.insert(7, terminal);
                            state.children.insert(8, ExitStatus::Exited(4));
                            let mut memory = GuestMemory::new(0, PAGE_SIZE as usize).unwrap();
                            let mut expected = vec![0xa5; PAGE_SIZE as usize];
                            memory.write(0, &expected).unwrap();
                            let args = [
                                selected,
                                if outputs { STATUS } else { 0 },
                                high | low as u64,
                                if outputs { USAGE } else { 0 },
                                0,
                                0,
                            ];
                            assert_eq!(wait4(&mut memory, &mut state, &args), 7);
                            assert_eq!(
                                state
                                    .consumed_child_wait
                                    .as_ref()
                                    .map(|receipt| receipt.child_pid()),
                                Some(7)
                            );
                            assert_eq!(state.children.get(&8), Some(ExitStatus::Exited(4)));
                            assert!(!state.children.contains_key(&7));
                            if outputs {
                                expected[STATUS as usize..STATUS as usize + 4]
                                    .copy_from_slice(&terminal.into_raw().to_le_bytes());
                                expected[USAGE as usize
                                    ..USAGE as usize + std::mem::size_of::<libc::rusage>()]
                                    .fill(0);
                            }
                            // A second exact wait cannot consume the remaining sibling.
                            state
                                .children
                                .acknowledge(state.consumed_child_wait.take().unwrap())
                                .unwrap();
                            let mut second = args;
                            second[0] = 7;
                            assert_eq!(
                                wait4(&mut memory, &mut state, &second),
                                negative_errno(libc::ECHILD)
                            );
                            assert!(state.consumed_child_wait.is_none());
                            let mut actual = vec![0; PAGE_SIZE as usize];
                            memory.read(0, &mut actual).unwrap();
                            assert_eq!(actual, expected);
                        }
                    }
                }
            }
        }
    }

    #[test]
    fn wait4_rejects_invalid_low_options_without_consuming_or_writing() {
        let root = TestDir::new();
        // These low bits are invalid for Linux wait4 as well. WCONTINUED and
        // clone-class flags are a separate, inherited backend-policy refusal.
        for low in [0x40, 0x40 | libc::WNOHANG, libc::WEXITED, libc::WNOWAIT] {
            for high in [0, 0xdead_beef_u64 << 32] {
                let mut state = test_state(&root.0);
                state.children.insert(7, ExitStatus::Exited(3));
                let mut memory = GuestMemory::new(0, PAGE_SIZE as usize).unwrap();
                memory.write(0, &[0xa5; PAGE_SIZE as usize]).unwrap();
                assert_eq!(
                    wait4(
                        &mut memory,
                        &mut state,
                        &[7, 0x100, high | low as u64, 0x200, 0, 0]
                    ),
                    negative_errno(libc::EINVAL)
                );
                assert_eq!(state.children.get(&7), Some(ExitStatus::Exited(3)));
                assert!(state.consumed_child_wait.is_none());
                let mut actual = [0; PAGE_SIZE as usize];
                memory.read(0, &mut actual).unwrap();
                assert_eq!(actual, [0xa5; PAGE_SIZE as usize]);
            }
        }
    }

    #[test]
    fn kill_probes_the_synthesized_namespace_init() {
        let root = TestDir::new();
        let mut state = test_state(&root.0);
        // Renumber the root guest as the conventional PID 3, whose parent is
        // the synthesized init.
        state.pid = 3;
        state.tid = 3;
        state.pgid = 3;
        state.ppid = crate::elf::CONTAINER_INIT_PID;
        state.task_lifecycle = std::sync::Arc::new(std::sync::Mutex::new(
            crate::elf::TaskLifecycleTable::with_root(3, 3, 3, true),
        ));
        let kill = |state: &mut LoadedStaticElf, pid: i64, signal: i32| {
            result_of(kill_signal(
                state,
                libc::SYS_kill as u64,
                &[pid as u64, signal as u64, 0, 0, 0, 0],
            ))
        };
        assert_eq!(kill(&mut state, 1, 0), 0);
        assert_eq!(
            kill(&mut state, 1, libc::SIGTERM),
            negative_errno(libc::ENOSYS)
        );
        assert_eq!(kill(&mut state, 2, 0), negative_errno(libc::ESRCH));
        assert!(state.thread_signals.lock().pending.is_empty());

        // A root guest that is itself PID 1 is the init; there is no other.
        let mut init = test_state(&root.0);
        assert_eq!(init.pid, 1);
        assert_eq!(kill(&mut init, 1, 0), 0);
        assert_eq!(kill(&mut init, 2, 0), negative_errno(libc::ESRCH));
    }

    #[test]
    fn wait4_wuntraced_requires_unsupported_stopped_children() {
        use reverie::ChildExitSignalErrorKind::Unsupported;
        use reverie::ChildExitSignalOutcome::RejectedBeforeCommit;
        use reverie::syscalls::Errno;

        let root = TestDir::new();
        let mut executor = ElfExecutor::new(test_state(&root.0), false);
        let mut child = executor.fork_child(7, false, false).unwrap();
        let pid = executor.state.pid as u64;
        let tid = executor.state.tid as u64;
        for signal in [libc::SIGSTOP, libc::SIGTSTP, libc::SIGTTIN, libc::SIGTTOU] {
            for (number, args) in [
                (libc::SYS_kill, [pid, signal as u64, 0, 0, 0, 0]),
                (libc::SYS_tgkill, [pid, tid, signal as u64, 0, 0, 0]),
            ] {
                assert_eq!(
                    result_of(kill_signal(&mut executor.state, number as u64, &args)),
                    negative_errno(libc::ENOSYS)
                );
                assert!(executor.state.thread_signals.lock().pending.is_empty());
                assert!(
                    executor
                        .state
                        .process_signals
                        .lock()
                        .unwrap()
                        .shared_pending
                        .is_empty()
                );
            }
        }
        let stopped = child_exit_test_event_with_code(
            executor.state.pid,
            7,
            libc::CLD_STOPPED,
            libc::SIGSTOP,
            0xa5,
        );
        assert_eq!(
            executor.queue_child_exit_signal(stopped),
            RejectedBeforeCommit {
                kind: Unsupported,
                errno: Errno::ENOSYS,
            }
        );
        assert!(executor.take_pending_signal().is_none());
        assert!(executor.state.children.is_empty());

        // Refusing stops must not prevent an ordinary terminal WUNTRACED wait.
        child.retire_current_thread(ExitStatus::Exited(3), false);
        executor.state.children.insert(7, ExitStatus::Exited(3));
        let memory = GuestMemory::new(0, PAGE_SIZE as usize).unwrap();
        let request = SyscallRequest::new(
            libc::SYS_wait4 as u64,
            [7, 0, libc::WUNTRACED as u64, 0, 0, 0],
        );
        assert_eq!(executor.execute_checked(&request, &memory).unwrap(), 7);
        assert!(executor.state.children.is_empty());
        assert!(executor.state.consumed_child_wait.is_none());
        assert_eq!(
            executor.execute_checked(&request, &memory).unwrap(),
            negative_errno(libc::ECHILD)
        );
    }

    #[test]
    fn wait4_validates_options_before_starting_a_pending_child() {
        let root = TestDir::new();
        for low in [0x40, 0x40 | libc::WNOHANG] {
            for high in [0, 0xdead_beef_u64 << 32] {
                let mut executor = ElfExecutor::new(test_state(&root.0), false);
                let (start_sender, start_receiver) = std::sync::mpsc::channel();
                let (release_sender, release_receiver) = std::sync::mpsc::channel();
                let completion = executor.mock_child_completion(7);
                let child_completion = completion.clone();

                let handle = ChildThread::spawn(move || {
                    // Rescue a regressed blocking invalid wait; success releases
                    // immediately. Do not leave a failed assertion owning a child.
                    let _ = release_receiver.recv_timeout(std::time::Duration::from_secs(1));
                    assert!(
                        child_completion.publish(ChildCompletion::Waitable(ExitStatus::Exited(9)))
                    );

                    Ok(())
                });
                executor.register_mock_child_process(7, start_sender, completion, handle);
                let mut memory = GuestMemory::new(0, PAGE_SIZE as usize).unwrap();
                memory.write(0, &[0xa5; PAGE_SIZE as usize]).unwrap();
                let result = executor.execute(
                    &SyscallRequest::new(
                        libc::SYS_wait4 as u64,
                        [7, 0x100, high | low as u64, 0x200, 0, 0],
                    ),
                    &memory,
                );
                let not_started = matches!(
                    start_receiver.try_recv(),
                    Err(std::sync::mpsc::TryRecvError::Empty)
                );
                let still_pending = executor.has_pending_child_process(7);
                let _ = release_sender.send(());
                executor.join_all_child_processes().unwrap();
                assert_eq!(result, negative_errno(libc::EINVAL));
                assert!(not_started, "invalid options released the child start gate");
                assert!(still_pending, "invalid options collected a child");
                let mut actual = [0; PAGE_SIZE as usize];
                memory.read(0, &mut actual).unwrap();
                assert_eq!(actual, [0xa5; PAGE_SIZE as usize]);
            }
        }
    }

    #[test]
    fn wait4_wuntraced_wnohang_preserves_running_child_outputs() {
        let root = TestDir::new();
        let mut executor = ElfExecutor::new(test_state(&root.0), false);
        let (start_sender, start_receiver) = std::sync::mpsc::channel();
        let (release_sender, release_receiver) = std::sync::mpsc::channel();
        let completion = executor.mock_child_completion(7);
        let child_completion = completion.clone();

        let handle = ChildThread::spawn(move || {
            start_receiver.recv().unwrap();
            release_receiver.recv().unwrap();
            assert!(child_completion.publish(ChildCompletion::Waitable(ExitStatus::Exited(9))));

            Ok(())
        });
        executor.register_mock_child_process(7, start_sender, completion, handle);
        let mut memory = GuestMemory::new(0, PAGE_SIZE as usize).unwrap();
        memory.write(0, &[0xa5; PAGE_SIZE as usize]).unwrap();
        let request = SyscallRequest::new(
            libc::SYS_wait4 as u64,
            [
                7,
                0x100,
                (0xdead_beef_u64 << 32) | (libc::WUNTRACED | libc::WNOHANG) as u64,
                0x200,
                0,
                0,
            ],
        );
        let poll = executor.execute(&request, &memory);
        let mut before_reap = [0; PAGE_SIZE as usize];
        memory.read(0, &mut before_reap).unwrap();
        release_sender.send(()).unwrap();
        let reap = executor.execute(
            &SyscallRequest::new(
                libc::SYS_wait4 as u64,
                [7, 0x100, libc::WUNTRACED as u64, 0x200, 0, 0],
            ),
            &memory,
        );
        executor.join_all_child_processes().unwrap();
        assert_eq!(poll, 0);
        assert_eq!(before_reap, [0xa5; PAGE_SIZE as usize]);
        assert_eq!(reap, 7);
        assert_eq!(
            executor.execute(&request, &memory),
            negative_errno(libc::ECHILD)
        );
        let mut status = [0; 4];
        memory.read(0x100, &mut status).unwrap();
        assert_eq!(i32::from_le_bytes(status), 9 << 8);
    }

